(window.GIM_TS=window.GIM_TS||{})["Bekhorot.3"]={"from":72,"a":[["\u0003כמלא נקב של עול\u0004 של בהמה. הרי ששיעור \"כמלא מקדח\" שאמרו בית שמאי לענין גולגולת שנפחתה, שווה בגודלו לסלע, שהוא השיעור לדעת בית הלל (לפי הפירוש שהביא רב תחליפא)! \u0003אישתיק\u0004 \u0005[שתק]\u0006 רב תחליפא, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: שמא\u0004 לא כמלא מקדח לבדו אמרו בית שמאי, אלא כמלא \u0003מקדח וחיסומו שנינו,\u0004 כלומר, נקב המאפשר הכנסה והוצאה של המקדח, והוא גדול יותר מסלע שאמרו בית הלל?","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב תחליפא: לא תימא\u0004 \u0005[אל תאמר]\u0006 בלשון \u0003שמא, אלא\u0004 אמור: \u0003ודאי\u0004 הכוונה היא ל\u0003מקדח וחיסומו.\u0004 ו\u0003צריך\u0004 אתה \u0003להתלות עליה,\u0004 על הסבר זה \u0003כ\u0004על עדותו של \u0003חזקיה אבי עקש,\u0004 שאין בה פקפוק. ומכאן יש ללמוד לדין משנתנו, כי כשם ש\"מלא מקדח\" משמעו נקב שמקדח יכול להיכנס ולצאת בו, כך \"מלא כרשינה\" שבמשנתנו משמעו — כרשינה נכנסת ויוצאת.","ומה היא אותה עדות של חזקיה אבי עקש? \u0003דתנן\u0004 \u0005[ששנינו],\u0006 \u0003זו עדות העיד חזקיה אבי עקש לפני רבן גמליאל ביבנה, שאמר משום\u0004 (בשם) \u0003רבן גמליאל הזקן\u0004 בענייני טומאת כלים: \u0003כל\u0004 כלי \u0003שאין לו תוך\u0004 (בית קיבול) \u0003בכלי חרס\u0004 — \u0003אין לו אחורים\u0004 \u0003לחליקה,\u0004 אין חילוק, הבחנה, בין צדדיו השונים. שאין דינו כדין כלי חרס האמור בתורה, שמיטמא רק מתוכו, ולא מגבו. אלא אם \u0003נטמא תוכו,\u0004 כלומר, הצד שמשתמשים בו — \u0003נטמא\u0004 גם \u0003גבו,\u0004 וכן אם \u0003נטמא גבו\u0004 — \u0003נטמא תוכו.\u0004","ותוהים על הלכה זו: הרי \u0003כלי חרס,\u0004 בטומאה שנכנסה \u0003בתוכו תלה רחמנא\u0004 \u0005[תלתה התורה]\u0006 את הטומאה, שנאמר: \"וכל כלי חרס אשר יפול מהם אל תוכו\" (ויקרא יא, לג), ומשום כך רק אם \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003תוך\u0004 (בית קיבול) — \u0003איטמי ליה\u0004 \u0005[נטמא לו]\u0006 הכלי, אבל אם \u0003לית ליה\u0004 \u0005[אין לו]\u0006 \u0003תוך\u0004 — \u0003לא איטמי ליה\u0004 \u0005[אינו נטמא]\u0006 כלל!","\u0003אמר רב יצחק בר אבין:\u0004 אין מדובר כאן על כלי חרס, אלא על כלי שטף, כגון כלי עץ, שהם מקבלים טומאה גם אם אין להם בית קיבול. ולפי זה \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך יש להשלים את הדברים: \u0003כל שאין לו תוך\u0004 (בית קיבול) \u0003בכלי חרס,\u0004 שאינו נטמא כלל — \u0003כנגדו\u0004 (במקביל לו) \u0003בכלי שטף,\u0004 אם אין לו בית קיבול — \u0003אין לו אחורים לחליקה,\u0004 אין חלוקה בין צדדיו השונים, אלא אם \u0003נטמא תוכו\u0004 הצד שמשתמשים בו — \u0003נטמא\u0004 גם \u0003גבו, נטמא גבו\u0004 — \u0003נטמא תוכו.\u0004","ושואלים: \u0003למה לי למיתלייה\u0004 \u0005[למה לו לתלות את\u0006 ההלכה \u0005הזו]\u0006 \u0003בכלי חרס,\u0004 אם דין זה אינו שייך בהם כלל? \u0003נימא\u0004 \u0005[שיאמר]\u0006 כך בפשטות: \u0003כל שאין לו תוך\u0004 (בית קיבול) \u0003בכלי שטף\u0004 — \u0003אין לו אחורים לחליקה!\u0004","ומשיבים, \u0003הא קא משמע לן\u0004 \u0005[\u0006דין \u0005זה משמיע לנו]\u0006 בהשוואה זו: שכלי שטף ש\u0003יש לו תוך\u0004 (בית קיבול) — \u0003הרי הוא ככלי חרס; מה כלי חרס,\u0004 אם \u0003נטמא תוכו\u0004 — \u0003נטמא גבו,\u0004 אבל אם \u0003לא נטמא תוכו\u0004 — \u0003לא נטמא גבו. אף כלי שטף,\u0004 אם \u0003נטמא תוכו\u0004 — \u0003נטמא גבו,\u0004 אבל אם \u0003לא נטמא תוכו\u0004 — \u0003לא נטמא גבו.\u0004","ותמהים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003כלי חרס, גלי ביה רחמנא\u0004 \u0005[גילתה בו התורה]\u0006 \u0003\"תוכו\",\u0004 שהוא נטמא כשנפלה טומאה דווקא לתוכו, \u0003אלא כלי שטף, מי גלי ביה רחמנא\u0004 \u0005[האם גילתה בו התורה]\u0006 \u0003תוכו?\u0004 ואם כן, גם אם נגעה בו הטומאה מגבו הריהו נטמא כולו!","ומסבירים: אכן, \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בטומאה דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006 הדין\u0005],\u0006 שכלי שטף נטמא גם מגבו. ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בטומאת משקין,\u0004 שמשקים שנגעו בטומאה ונטמאו, נגעו בכלי שטף וטימאוהו, וטומאה זו אינה אלא \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים]. והוא מה\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי שנטמא אחוריו במשקין\u0004 — רק \u0003אחוריו טמאין,\u0004 ואילו \u0003תוכו, אגנו\u0004 (הקפל שבשפתו), \u0003אזנו\u0004 (ידית שלו שבצורת אוזן) \u0003וידיו\u0004 (ידית ישרה שלו) — טהורין. אבל אם \u0003נטמא תוכו\u0004 — \u0003כולו טמא.\u0004","ומסבירים את טעם הדבר: לפי \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003אין אוכל מטמא כלי, ואין משקה מטמא כלי, ורבנן הוא דגזור\u0004 \u0005[וחכמים הם שגזרו]\u0006 שמשקה שנטמא יטמא כלים, \u0003משום\u0004 חשש שמא יבואו אנשים להקל בדין \u0003משקה זב וזבה\u0004 (כגון מי רגליהם ורוקם), שהם אב הטומאה, ומטמאים גם כלים.","\u0003הלכך\u0004 \u0005[על כן],\u0006 \u0003שויוה רבנן\u0004 \u0005[עשו אותה חכמים],\u0006 את טומאת כלי שטף שנטמא מאחוריו במשקים, \u0003כטומאה\u0004 של \u0003כלי חרס,\u0004 שאם נטמא מגבו — לא נטמא תוכו, \u0003ולא שויוה רבנן\u0004 \u0005[עשו אותה חכמים]\u0006 \u0003כטומאה דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003דנפשיה\u0004 \u0005[של עצמו,\u0006 של כלי שטף\u0005],\u0006 שאם נטמא מגבו, שכולו טמא.","וטעם הדבר, כי \u0003עבדו רבנן היכירא\u0004 \u0005[עשו חכמים היכר]\u0006 בטומאה שמדבריהם, \u0003כי היכי דלא לישרוף עליה\u0004 \u0005[כדי שלא ישרפו עליה]\u0006 \u0003תרומה וקדשים\u0004 שנגעו בכלי זה, שהרי מדין תורה טהורים הם ואסור לשורפם. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שבמקרה זה מדובר, כלי שטף ש\u0003אין לו תוך נמי\u0004 \u0005[גם כן],\u0006 מדוע העיד חזקיה אבי עקש, שאם נטמא גבו נטמא תוכו (הצד שמשתמשים בו)? \u0003ליעביד נמי היכירא\u0004 \u0005[שיעשו גם כן היכר],\u0006 ולא ייטמא תוכו, כדי שלא ישרפו על כך תרומה וקדשים!","ומשיבים: \u0003כיון דעבדו היכירא\u0004 \u0005[שעשו\u0006 חכמים \u0005היכר]\u0006 \u0003ב\u0004טומאת משקים של כלי שטף ש\u0003יש לו תוך, ידיע\u0004 \u0005[ידוע]\u0006 ממילא כי גם טומאת משקים בכלי ש\u0003אין לו תוך\u0004 — \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 היא, ולא יבואו לשרוף בגללה תרומה וקדשים.","ושואלים: \u0003ו\u0004כלי ש\u0003אין לו תוך בכלי שטף,\u0004 האם \u0003דאורייתא בר קבולי\u0004 \u0005[מן התורה ראוי לקבלת]\u0006 \u0003טומאה הוא,\u0004 עד שהוצרכו חכמים לגזור שייטמא מאחוריו במשקים טמאים? הלוא כדי שיהיה הכלי ראוי לקבלת טומאה, \u0003דומיא דשק בעינן\u0004 \u0005[בדומה לשק צריכים אנו]\u0006 שיהיה, \u0003מה שק\u0004 שנזכר בענין זה (ויקרא יא, לב) הריהו \u0003מיטלטל\u0004 כשהוא \u0003מלא וריקן\u0004 — \u0003אף כל\u0004 כלי צריך שיהא \u0003מיטלטל מלא וריקן\u0004 כדי שיהיה ראוי לקבל טומאה, וכלי שאין לו תוך הרי אינו יכול להיות מלא!","ומשיבים: מדובר כאן \u0003בהנך דחזו\u0004 \u0005[באותם\u0006 כלים \u0005שראויים]\u0006 \u0003למדרסות,\u0004 שמשמשים לישיבה, והם נטמאים בטומאת זב וזבה, גם אם אין להם בית קיבול. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 כלי \u0003חרס\u0004 שאין לו תוך \u0003נמי\u0004 \u0005[גם כן]\u0006 — נגזור עליו שייטמא ממשקים טמאים, אם הוא ראוי למדרס! ומשיבים: \u0003אין\u0004 כלל דין טומאת \u0003מדרס בכלי חרס.\u0004","ושבים לקושיית רב חסדא בענין גולגולת שנפחתה, שלדעת בית שמאי אינה מטמאת באוהל אם נחסרה בשיעור מקדח. ואם נפרש כשמואל, שלדעת בית הלל, שיעורו של חסרון זה הוא כסלע, נמצא שאין מחלוקת בין בית שמאי לבית הלל, שהרי שנינו, בענין מאור (חלון) המביא את הטומאה, שמקדח שווה בגודלו לסלע. \u0003רב פפא אמר: מקדח גדול שנינו\u0004 בענין מאור המביא את הטומאה, ודווקא הוא שווה בשיעורו לסלע.","ו\u0003מכלל\u0004 הדברים אתה למד ש\u0003מקדח סתם\u0004 שהוזכר בדברי בית שמאי, לענין גולגולת שנפחתה — \u0003זוטרא נמי\u0004 \u0005[קטן]\u0006 \u0003מכסלע\u0004 ששנו בית הלל. ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003ר' מאיר\u0004 בפירוש דעת בית שמאי, \u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003באיזה מקדח אמרו\u0004 בית שמאי דעתם בענין גולגולת שנפחתה — \u0003ב\u0004מקדח \u0003קטן של רופאים,\u0004 שמשתמשים בו לקדיחה של עצמות, אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 מדובר \u0003ב\u0004מקדח \u0003גדול,\u0004 כגון \u0003של לשכה\u0004 שבמקדש. והרי לפי המשנה בענין מאור המביא את הטומאה, מקדח זה שיעורו כסלע!","ועוד שואלים: \u0003ול\u0004שיטת \u0003ר' מאיר, מי ניחא\u0004 \u0005[האם נוח]\u0006 הדבר? והרי אם מקדח סתם, ששנו בית שמאי, קטן מסלע — \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003מקולי בית שמאי ומחומרי בית הלל,\u0004 שאם נפחתה גולגולת בשיעור מקדח בלבד, בית שמאי מקילים ומטהרים מטומאת אוהל, ובית הלל מחמירים ומטמאים. \u0003ואנן\u0004 \u0005[ואנו]\u0006 כלל בידינו בענין זה: \u0003דתנן תנן\u0004 \u0005[\u0006מה \u0005ששנינו\u0006 במסכת עדיות שהוא מקולי בית שמאי, \u0005שנינו],\u0006 \u0003דלא תנן לא תנן\u0004 \u0005[\u0006ומה \u0005שלא שנינו\u0006 שם \u0005לא שנינו],\u0006 אלא בכל מקום בית שמאי מחמירים ובית הלל מקילים!","\u0003אמר רב נחמן:\u0004 דוקא לגבי \u0003סלע נירונית שנינו\u0004 במשנה בענין מאור, שהוא \u0003כ\u0004שיעור \u0003מקדח גדול.\u0004 ואילו \u0003סלע סתם,\u0004 שהוא השיעור לדעת בית הלל, \u0003זוטרא\u0004 \u0005[קטן]\u0006 אפילו \u0003מ\u0004נקב של \u0003מקדח סתם.\u0004 ונמצא שבית שמאי מחמירים יותר, אפילו לשיטת ר' מאיר.","על אלו מומים שבעין שוחטים את הבכור מחוץ למקדש: \u0003הריס\u0004 (העפעף) \u0003של עין שניקב\u0004 או \u0003שנפגם\u0004 או \u0003שנסדק,\u0004 וכן \u0003הרי\u0004 שהיה \u0003ב\u0004תוך \u0003עינו דק,\u0004 מעין כתם, וכן \u0003תבלול, חלזון, נחש, עצב. איזהו תבלול\u0004 — מעין חוט \u0003לבן הפוסק בסירא,\u0004 בעגול המקיף את השחור שבעין, \u0003ונכנס ב\u0004תוך ה\u0003שחור\u0004 שבעין. אבל אם היה חוט \u0003שחור\u0004 פוסק בסירא ו\u0003נכנס בלבן\u0004 — \u0003אינו מום,\u0004 שמום בלבן שבעין אינו נחשב למום."],["שנינו במשנה ברשימת המומים שבעין: הריס של עין שניקב שנפגם שנסדק. ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003הריס? אמר רב פפא: תורא ברא דעינא\u0004 \u0005[השורה,\u0006 המחיצה \u0005החיצונה של העין],\u0006 כלומר, העפעף. ועוד שנינו במשנה: \u0003דק תבלול.\u0004 ובענין דק, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דק,\u0004 אם הוא \u0003משוקע\u0004 בגוף העין — \u0003הרי זה מום,\u0004 ואם \u0003צף\u0004 מלמעלה — \u0003אינו מום.\u0004","ושואלים: \u0003והתניא איפכא\u0004 \u0005[והרי שנויה\u0006 ברייתא \u0005להיפך],\u0006 שמשוקע אינו מום וצף הריהו מום? ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 \u0003בשחור, הא\u0004 \u0005[זה]\u0006 כשהיה \u0003בלבן.\u0004 ועל כך תמהים, \u0003והא\u0004 \u0005[והרי]\u0006 שנינו: \u0003אין מומין בלבן! אלא\u0004 גם כאן וגם כאן מדובר בשחור שבעין, \u0003הא\u0004 \u0005[זה]\u0006 עוסק \u0003בדוק לבן, הא\u0004 \u0005[זה]\u0006 עוסק \u0003בדוק שחור.\u0004","והוא כפי שאמר ש\u0003אמר רבה בר בר חנה, סח\u0004 (אמר) \u0003לי ר' יאשיה\u0004 ש\u0003מן\u0004 העיר \u0003אושא:\u0004 אם היה \u0003דק שחור משוקע\u0004 — \u0003הרי זה מום,\u0004 אם היה \u0003צף\u0004 — \u0003אינו מום. דק לבן משוקע\u0004 — \u0003אינו מום, צף\u0004 — \u0003הרי זה מום. וסימניך\u0004 \u0005[והסימן]\u0006 לדבר: \u0003ברקא,\u0004 שהיא מחלה שבעין, שנראים בה כתמים לבנים צפים על גבי העין, והיא מום.","שנינו במשנה ברשימת המומים שבעין: \u0003חלזון נחש ועצב. איבעיא להו\u0004 \u0005[נשאלה להם ללומדים]:\u0006 האם \u0003חלזון הוא נחש, או דלמא\u0004 \u0005[שמא]\u0006 שני מומים הם, וכוונת המשנה לומר: \u0003חלזון או נחש?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר רבה בר בר חנה: סח לי ר' יוחנן בן אלעזר, זקן אחד היה בשכונתינו ור' שמעון בן יוסי לקוניא שמו, ומימי לא עברתי לפניו. פעם אחת עברתי לפניו, אמר לי, שב בני, שב\u0004ואלמדך דבר! \u0003חלזון זה\u0004 שאתה רואה בעין הבכור — \u0003מום קבוע\u0004 הוא \u0003לשחוט עליו, וזהו נחש שאמרו חכמים\u0004 שהוא מום.","\u0003ואף על פי שאמרו\u0004 חכמים: \u0003אין אדם רואה מומין לעצמו,\u0004 ולכן איני יכול להתיר בכור זה לעצמי, \u0003אבל\u0004 הרב \u0003מורה הלכה לתלמידים, ותלמידים מורין לו\u0004 על פי מה שלימדם, ומתירים לו. ולכן, לאחר שלימדתי אותך הלכה זו תוכל אתה להתיר את הבכור שבידי, שיש בו מום זה.","ומקשים: וכיצד יכול היה ר' יוחנן בן אלעזר להתיר על פי דבריו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא\u0004 שכך \u0003אמר רב הונא: כל תלמיד חכם שמורה הלכה ובא, אם קודם מעשה,\u0004 קודם שהוצרכה לו הלכה זו, \u0003אמרה\u0004 — \u0003שומעין לו, ואם לאו\u0004 \u0005[לא],\u0006 אלא אמרה בשעת מעשה — \u0003אין שומעין לו!\u0004 ומשיבים: \u0003איהו נמי מורה ובא הוה מעיקרא\u0004 \u0005[הוא גם כן,\u0006 ר' יוסי בן לקוניא, \u0005מורה ובא היה מתחילה]\u0006 הלכה זו, עוד קודם שבא לידי מעשה זה.","שנינו במשנה: \u0003איזהו תבלול?\u0004 חוט \u0003לבן הפוסק את הסירא\u0004 (המפרידה בין הלבן והשחור שבעין) ונכנס בשחור. ומבררים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יוסי היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 חוט \u0003לבן\u0004 היוצא מן הלבן שבעין \u0003ונכנס בשחור,\u0004 וכן חוט \u0003שחור\u0004 היוצא מן השחור שבעין \u0003ונכנס בלבן\u0004 — \u0003הרי זה מום,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: לבן ונכנס בשחור\u0004 — \u0003הרי זה מום, שחור ונכנס בלבן\u0004 — \u0003אינו מום, שאין מומין בלבן.\u0004","\u0003אמר רב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי?\u0004 איזה מקור בכתוב יש לדבריו? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יצא מחלב עינימו\"\u0004 (תהלים עג, ז), כלומר, יצא הרשע לתרבות רעה מרוב חלב (שומן) שבעינו, והוא בלבן שבעין. הרי שהלבן \u0003תרבא דעינא\u0004 \u0005[חלב העין]\u0006 — \u0003איקרי\u0004 \u0005[נקרא],\u0006 אבל \u0003\"עינימו\"\u0004 (עינו) \u0003סתמא\u0004 \u0005[סתם]\u0006 — \u0003לא איקרי\u0004 \u0005[אינו נקרא],\u0006 ואין תבלול נחשב מום אלא בעין עצמה, שנאמר: \"תבלול בעינו\" (ויקרא כא, כ). ושואלים: \u0003ור' מאיר מאי טעמיה\u0004 \u0005[מה טעמו]?\u0006 ומשיבים: לדעתו, \u0003מה\u0004 הוא \u0003לשון תבלול? דבר המבלבל את העינים,\u0004 העובר בין הלבן והשחור שבעין, בכל דרך.","המשנה ממשיכה ברשימת המומים שבעין, ששוחטים עליהם את הבכור: \u0003חורוור\u0004 (שנראות בעין כעין טיפות לבנות) שהוא קבוע, \u0003והמים\u0004 שיורדים בעיניו \u0003הקבועין. איזהו חורוור הקבוע?\u0004 כיצד יודעים שהוא קבוע? \u0003כל ששהה שמונים יום\u0004 ולא נרפא. \u0003ר' חנניא בן אנטיגנוס אמר: בודקין אותו שלש פעמים בתוך שמונים יום,\u0004 ורק אם נמצא החורוור בכל אותן פעמים — הרי זה קבוע. ואלו הן מים הקבועין, כלומר, כיצד יודעים אם הם קבועים או עוברים?","אם \u0003אכל,\u0004 האכילוהו לרפואה, מספוא \u0003לח ו\u0004מספוא \u0003יבש של\u0004 שדה המושקה ב\u0003גשמים\u0004 בלבד, או שאכל \u0003לח ויבש של שלחים\u0004 (שדה הצריכה השקייה), \u0003או\u0004 אפילו לא אכל לח ויבש ביחד, אלא \u0003אכל היבש ואחר כך הלח,\u0004 ולא נרפא — כל זה \u0003אינו מום\u0004 קבוע בוודאות, \u0003עד שיאכל הלח ואחר כך\u0004 יאכל \u0003היבש,\u0004 שהיא הדרך הבדוקה לרפואת המים שבעין, ואם בכל זאת ישארו בו המים — הרי אלו מים קבועים.","ומבררים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003חורוור קבוע\u0004 — \u0003ארבעים יום, ומים הקבועים\u0004 — \u0003שמונים יום,\u0004 אלו \u0003דברי ר' מאיר. ור' יהודה אומר: חורוור\u0004 — \u0003שמונים יום.\u0004","\u0003ואלו הן מים הקבועים\u0004 לשיטת ר' יהודה: אם \u0003אכל לח ויבש של בית השלחין, או שאכל יבש ואחר כך אכל הלח\u0004 ולא נרפא — \u0003אין\u0004 זה \u0003מום\u0004 קבוע בוודאות, \u0003עד שיאכל יבש אחר הלח. ו\u0004זמן ההאכלה של הלח והיבש \u0003ישנו\u0004 (נמשך) \u0003שלשה חדשים.\u0004 ושואלים: וכיצד אתה אומר שמשנתנו כשיטת ר' יהודה?","\u0003והא תרוייהו תננהי\u0004 \u0005[והרי שניהם שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אכל לח ויבש של גשמים, לח ויבש של בית השלחין,\u0004 ולא נרפא — אין זה מום. ואילו ר' יהודה הזכיר רק לח ויבש של שלחים, ומדבריו משמע כי אם אכל לח ויבש של גשמים, ולא נרפא — הרי זה מום!","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 צריך \u0005לשנותה],\u0006 לפי דברי ר' יהודה שבברייתא: \u0003אכל לח ויבש של גשמים\u0004 ולא נרפא — \u0003הרי זה מום,\u0004 לח ויבש של \u0003בית השלחין\u0004 — \u0003אינו מום. ו\u0004של \u0003הגשמים נמי\u0004 \u0005[גם כן],\u0006 אם \u0003אכל יבש ואחר כך אכל לח\u0004 — \u0003אינו מום, עד שיאכל יבש אחר הלח.\u0004","ועל מה ששנינו בברייתא: \u0003וישנו\u0004 תהליך זה של האכלה \u0003שלשה חדשים,\u0004 מקשים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה ברייתא],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב אידי בר אבין אמר רב יצחק בר אשיאן: אדר וניסן\u0004 — הרי זה \u0003לח\u0004 ששנינו במשנתנו, כשהצמחיה עדיין לחה, \u0003אלול ותשרי\u0004 — \u0003יבש,\u0004 שהוא בסוף הקיץ. הרי כאן ארבעה חדשים! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003אדר וחצי ניסן\u0004 — \u0003לח, אלול וחצי תשרי\u0004 — הרי זה \u0003יבש,\u0004 וביחד שלושה חדשים.","ועוד על מה ששנינו שצריך להאכיל לח ואחר כך יבש, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה \u0005ללומדים]:\u0006 האם צריך להאכיל אותו \u0003לח בזמן לח,\u0004 בסוף עונת הגשמים, \u0003ויבש בזמן היבש,\u0004 בסוף הקיץ, \u0003או דלמא\u0004 \u0005[שמא]:\u0006 שמאכילים \u0003לח ו\u0004אחר כך \u0003יבש\u0004 (שנותר מן הקיץ הקודם) \u0003בזמן הלח?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003אמר רב אידי בר אבין אמר רב יצחק בר אשיאן: אדר וניסן\u0004 — \u0003לח, אלול ותשרי\u0004 — \u0003יבש.\u0004 וכאן משמע שמאכילים אותו בכל זמן לפי העשב המצוי אז. ודוחים: מכאן אין ראיה לזמן בו מאכילים אותו, \u0003דלמא פירי\u0004 \u0005[שמא פירות]\u0006 של \u0003אלול ותשרי מאכילנא ליה\u0004 \u0005[מאכילים אותו]\u0006 \u0003באדר וניסן.\u0004","ועוד שואלים: \u0003וכמה מאכילין אותו\u0004 את הבכור, מאותו עשב? \u0003אמר ר' יוחנן משום ר' פנחס בן ערובא:\u0004 מאכילים אותו \u0003כ\u0004שיעור \u0003גרוגרת\u0004 (פרי התמר). \u0003אמר רבא, בעי במערבא\u0004 \u0005[שאלו בארץ ישראל]:\u0006 האם הכוונה היא שמאכילים אותו \u0003כגרוגרות בסעודה ראשונה\u0004 בכל יום,"],["\u0003או דלמא\u0004 \u0005[שמא]\u0006 כגרוגרת \u0003בכל סעודה וסעודה?\u0004 ומוסיפים: \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 שמאכילים אותו רק \u0003בסעודה ראשונה,\u0004 האם \u0003קודם אכילה או לאחר אכילה?\u0004 ומפרטים: \u0003קודם אכילה\u0004 — \u0003ודאי מעלי ליה כסמא\u0004 \u0005[מועיל לו כסם,\u0006 כתרופה\u0005],\u0006 שאנשים נוטלים קודם שאוכלים, אבל \u0003לאחר אכילה מאי\u0004 \u0005[מה],\u0006 האם מועיל הדבר לבודקו? ועוד שואלים: האם מאכילים אותה לרפואה \u0003קודם שתיה או לאחר שתיה? ו\u0004מפרטים: \u0003קודם שתיה\u0004 — \u0003ודאי מעלי ליה כשערי\u0004 \u0005[מועיל לו, כשעורים],\u0006 שהם יפים למאכל בהמה קודם שתיה. אבל \u0003לאחר שתיה מאי\u0004 \u0005[מה],\u0006 האם מועיל הדבר?","ועוד שואלים: האם נותנים לו עשבים אלו כשהוא \u0003קשור או מותר?\u0004 ומפרטים: כשהוא \u0003מותר\u0004 — \u0003ודאי מעלי ליה\u0004 \u0005[מועיל לו],\u0006 שהוא רגוע יותר, אבל כשהוא \u0003קשור מאי\u0004 \u0005[מה],\u0006 האם מועיל הדבר? ועוד: האם מאכילים אותו עשבים אלו כשהוא \u0003לבדו, או עם חבירו,\u0004 עם בהמה נוספת? ומפרטים: כשהוא \u0003עם חבירו\u0004 — \u0003ודאי מעלי ליה\u0004 \u0005[מועיל לו],\u0006 שהוא חש בנוח, אבל כשהוא \u0003לבדו מאי\u0004 \u0005[מה]?\u0006","ועוד: האם מאכילים אותו \u0003בעיר ובשדה?\u0004 ומפרטים: \u0003בשדה\u0004 — \u0003ודאי מעלי ליה\u0004 \u0005[מועיל לו],\u0006 שהוא רגוע יותר, \u0003בעיר מאי\u0004 \u0005[מה]?\u0006 \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 עוד: \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 שדוקא כשהוא \u0003בשדה\u0004 מועיל לו הדבר, ולא בעיר, \u0003גינה הסמוכה לעיר מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 כל השאלות הללו לא נפתרו, ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 הבעיה במקומה.","שנינו במשנה, בעניין חורוור הקבוע: \u0003ר' חנניא בן אנטיגנוס אמר:\u0004 בודקים אותו שלוש פעמים בשמונים יום. על כך \u0003אמר רב נחמן בר יצחק: ובלבד שיהו משולשים,\u0004 כלומר, שיהא מרווחי זמן קבועים בין הבדיקות.","ובענין ששנינו במשנתנו, שהמים הקבועים נבדקים על ידי אכילה של לח ויבש במשך שלושה חדשים, \u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003פנחס אחוה\u0004 \u0005[אחיו]\u0006 של \u0003מר שמואל משמואל: אכל\u0004 כסדר הראוי \u0003ולא איתסי\u0004 \u0005[התרפא],\u0006 והריהו איפוא בעל מום קבוע, האם \u0003למפרע הוי\u0004 \u0005[הריהו]\u0006 \u0003מומא,\u0004 מהיום שנתגלו בו המים, \u0003או מיכן ולהבא הוי\u0004 \u0005[הריהו]\u0006 \u0003מומא?\u0004","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן],\u0006 מה ההבדל בין זה לזה? ומשיבים: לענין \u0003למימעל\u0004 \u0005[למעול,\u0006 לעבור על איסור מעילה\u0005]\u0006 \u0003ב\u0004דמי \u0003פדיונו,\u0004 אם פדה בהמה זו קודם שעברו שלושה חדשי הבדיקה, והוא או אדם אחר נהנה בינתיים מן הדמים שניתנו להקדש בפדיונה. \u0003אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 \u0003למפרע הוי מומא\u0004 \u0005[הריהו מום]\u0006 — הרי \u0003מעיל\u0004 \u0005[מועל],\u0006 מפני שהפדיון חל, והדמים עברו לרשות ההקדש.","\u0003ואי\u0004 \u0005[ואם]\u0006 רק \u0003מיכן ולהבא הוי מומא\u0004 \u0005[הרי זה מום]\u0006 — הנהנה מן הדמים קודם שנתברר הדבר \u0003לא מעיל\u0004 \u0005[אינו מועל],\u0006 משום שלא ניתן לפדות בהמה תמימה מיד ההקדש, והדמים נשארו חולין. ואם כן, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003שמואל עליה\u0004 \u0005[עליו]\u0006 על אחיו: \u0003\"פסחים בזזו בז\"\u0004 (ישעיהו לג, כג), כלומר, אדם כמוהו, שאינו גדול בתורה, מצליח לשאול שאלה שאין אני יכול למצוא לה תשובה.","ועוד מומים ששוחטים עליהם את הבכור מחוץ למקדש: \u0003חוטמו שניקב ושנפגם ושנסדק. שפמו\u0004 (שפתו) שניקבה שנפגמה שנסדקה. בענין חוטמו שניקב, \u0003תנו\u0004","\u0003רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ניקבו חוטמין\u0004 (נחירים) \u0003זה לתוך זה,\u0004 אם היה הנקב \u0003מבחוץ,\u0004 במקום גלוי — \u0003הרי זה מום, מבפנים\u0004 — \u0003אינו מום.\u0004 ועל מה ששנינו: \u0003שפתו שניקבה ושנפגמה ושנסדקה, אמר רב פפא:\u0004 הכוונה היא ל\u0003תורא ברא דשיפתיה\u0004 \u0005[השורה החיצונה,\u0006 החלק הקדמי, הבולט, \u0005של שפתו].\u0006","ועוד מומים ששוחטים עליהם את הבכור מחוץ למקדש: \u0003חוטין\u0004 (החניכיים) \u0003החיצוכנות שנפגמו,\u0004 שנחסרו, או \u0003שנגממו,\u0004 נעשו בהם חתכים. וכן \u0003הפנימים שנעקרו\u0004 לגמרי. \u0003ר' חנינא בן אנטיגנוס אומר: אין בודקין מן התיומת\u0004 (מקום השיניים התאומות, הכפולות), שבחלק האחורי של הלסת, \u0003ולפנים,\u0004 מפני שגם אם נעקרו לגמרי — אין שוחטים על כך, לפי שהוא נחשב מום שבסתר. \u0003ואף לא\u0004 בודקים \u0003את\u0004 מקום \u0003התיומת\u0004 עצמה.","בענין ששנינו במשנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003התיומת, איזהו תיומת? מן התיומת ולפנים, ותיומת עצמה\u0004 דינה \u0003כלפנים,\u0004 שהוא נחשב מום שבסתר, ואין שוחטים עליו. \u0003ר' יהושע בן קפוצאי אומר: אין שוחטין אלא על החיצונות בלבד. ר' חנינא בן אנטיגנוס אומר: אין משגיחין על התיומת כל עיקר.\u0004","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אומר]\u0006 החכם בברייתא זו, שהוא שואל \"איזהו תיומת\", ואינו משיב על כך? \u0003ותו\u0004 \u0005[ועוד],\u0006 דברי \u0003ר' יהושע בן קפוצאי היינו\u0004 \u0005[הרי הוא]\u0006 מה שאומר \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 שלשניהם התיומת נחשבת מום שבסתר!","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך יש לשנות\u0006 אותה\u0005]:\u0006 \u0003איזהו\u0004 החוטין (החניכיים) \u0003הפנימית,\u0004 שאם אירע בהם מום אין שוחטים על כך את הבכור? \u0003מן\u0004 מקום \u0003התיומת ולפנים, ותיומת עצמה\u0004 דינה \u0003כלפנים. במה דברים אמורים\u0004 שאין שוחטים? במקרה \u0003שנפגמו ושנגממו\u0004 החניכיים הפנימיות. \u0003אבל\u0004 אם \u0003נעקרו\u0004 — \u0003שוחטין\u0004 עליהם.","\u0003ר' יהושע בן קפוצאי אומר: אין שוחטין אלא על\u0004 החניכיים \u0003החיצונות\u0004 בלבד, \u0003אבל פנימיות שנעקרו\u0004 — \u0003מישחט עלייהו לא שחטינן\u0004 \u0005[לשחוט עליהם אין אנו שוחטים],\u0006 \u0003אבל אפסולי מיפסל\u0004 \u0005[להיפסל\u0006 לקרבן הוא \u0005נפסל].\u0006 \u0003ר' חנינא בן אנטיגנוס אומר: אין משגיחין על התיומת כל עיקר, ואפילו איפסולי לא איפסיל\u0004 \u0005[להיפסל\u0006 לקרבן \u0005אינו נפסל].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אחדבוי בר אמי:\u0004 האם \u0003יש\u0004 דין \u0003מחוסר אבר מבפנים,\u0004 כשחסר איבר פנימי בבהמה, האם נחשב הדבר למום, \u0003או אין\u0004 דין \u0003מחוסר אבר מבפנים?\u0004 ושואלים: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 נשאלה השאלה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003בכור,\u0004 שמותר לשוחטו מחוץ למקדש על כך — \u0003\"פסח או עור\"\u0004 (דברים טו, כא) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ומשמע — דוקא מומים שבגלוי.","וכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שאר \u0003קדשים,\u0004 שהם פסולים להקרבה, ופודים אותם — הרי \u0003\"עורת או שבור\"\u0004 (ויקרא כב, כב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 שהם מומים גלויים! ומשיבים: \u0003לאישחוטי ולאיפרוקי\u0004 \u0005[לשחוט\u0006 את הבכור, \u0005ולפדות\u0006 שאר קדשים\u0005]\u0006 על כך, \u0003לא איבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 השאלה, ואין זה נחשב כמום. \u0003כי מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 השאלה, הרי זה \u0003לאיפסולי\u0004 \u0005[לפסול]\u0006 מהקרבה, \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","מצד אחד, \u0003\"תמים יהיה לרצון\"\u0004 (ויקרא כב, כא) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ומכאן נלמד: \u0003תמים\u0004 (שלם) — \u0003אין\u0004 \u0005[כן],\u0006 וכל שיש בו \u0003חסרון,\u0004 אפילו פנימי — \u0003לא\u0004 יהיה לרצון, כלומר, אינו מתקבל כקרבן. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש ללמוד על מה שנאמר: \u0003\"תמים יהיה (לרבות) [לרצון]\"\u0004ממה שנאמר מיד אחר כך: \u0003\"כל מום לא יהיה בו\". מה מום\u0004 הוא דווקא זה ש\u0003מאבראי\u0004 \u0005[מבחוץ],\u0006 וכפי שהכתוב הולך ומפרט בפסוק שאחר כך: \"עורת או שבור\", \u0003אף חסרון\u0004 נחשב רק כאשר הוא \u0003מאבראי\u0004 \u0005[מבחוץ]!\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שנחלקו חכמים בדבר זה. שהרי מצד אחד שנינו בברייתא: מה שנאמר בענין הקטרת אימורי השלמים \u0003\"ואת שתי הכליות\"\u0004 (ויקרא ג, ד), יש ללמוד מכאן שאין מקריבים אלא בעל שתי כליות, \u0003ולא בעל כוליא אחת, ולא בעל שלש כוליות. ו\u0004מצד שני, \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 נאמר \"ואת שתי הכליות... יסירנה\" (ויקרא ג, ד) — \u0003לרבות בעל כוליא אחת,\u0004 שמקריבים אותו, שהרי נאמר הדבר בלשון יחיד. הרי שנחלקו התנאים האם בהמה שחסרה לה כליה פסולה לקרבן.","\u0003סברוה\u0004 \u0005[סברו,\u0006 הבינו הלומדים\u0005]\u0006 מתחילה כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין בריה\u0004 (בריאה) של בהמה \u0003ב\u0004כליה \u0003אחת,\u0004 ואם נמצאה בה רק אחת, הרי זה משום \u0003דהא מיחסר חסר\u0004 \u0005[ש\u0006קרבן \u0005זה נחסרה לו\u0006 כליה\u0005]\u0006 לאחר שנולד. ואם כן, \u0003לימא בהא קמיפלגי\u0004 \u0005[\u0006האם \u0005נאמר שב\u0006שאלה \u0005זו הם חלוקים]:\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 בברייתא הראשונה, \u0005סבור]:\u0006 \u0003חסרון מבפנים שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003חסרון,\u0004 ולכן בעל כליה אחת פסול להקרבה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 בברייתא האחרת, \u0005סבור]:\u0006 \u0003חסרון מבפנים לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003חסרון,\u0004 ולכן הוא כשר?","\u0003אמר רב חייא בר יוסף:\u0004 אין כאן כלל מחלוקת, אלא \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003יש בריה\u0004 של בהמה \u0003ב\u0004כליה \u0003אחת, וחסרון מבפנים שמיה\u0004 \u0005[שמו]\u0006 \u0003חסרון,\u0004 שפוסל את הבהמה. \u0003ולא קשיא\u0004 \u0005[קשה]\u0006 הסתירה שבין הברייתות; \u0003כאן,\u0004 שהבהמה פסולה — \u0003כשנבראה בשתים וחסרו\u0004 אחת, \u0003כאן,\u0004 שהיא כשרה — \u0003כשנבראה באחת מעיקרא\u0004 \u0005[מתחילה],\u0006 ואינה נפסלת, שהרי לא נחסרה.","ומקשים: כיצד ניתן לפרש את הברייתא הראשונה כשהיו שתי כליות ואחר כך נחסרה אחת? \u0003והא דומיא דשלש קתני\u0004 \u0005[והרי\u0006 בדומה לבעל \u0005שלוש\u0006 כליות, שנפסל אף הוא באותה ברייתא, \u0005הוא שונה],\u0006 \u0003מה שלש\u0004 הרי זה \u0003מעיקרא\u0004 \u0005[מתחילה],\u0006 שבוודאי כך נוצרה הבהמה, שאין בהמה מגדלת איברים חדשים, \u0003אף\u0004 בעל כליה \u0003אחת\u0004 — כוונתו שהיתה כך \u0003מעיקרא\u0004 \u0005[מתחילה]!\u0006","\u0003אלא,\u0004 אף שקיימת מחלוקת בין שתי הברייתות מה דינו של בעל כליה אחת, עדיין יש לומר כי לדעת הכל חסרון מפנים הריהו חסרון. ומה שנחלקו \u0003הכא\u0004 \u0005[כאן]\u0006 שני התנאים — \u0003ב\u0004שאלה האם \u0003יש בריה\u0004 של בעלת כליה אחת \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 שבברייתא השניה, \u0005סבור]:\u0006 \u0003יש בריה ב\u0004כליה \u0003אחת,\u0004 ויש להניח כי בהמה זו שלפנינו נבראה כך, ולא נחסרה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שבברייתא הראשונה, \u0005סבור]:\u0006 \u0003אין בריה ב\u0004כליה \u0003אחת,\u0004 אלא ודאי נחסרה, ולכן הקרבן פסול.","\u0003ור' יוחנן אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין בריה ב\u0004כליה \u0003אחת, וחסרו‍ן מבפנים שמיה\u0004 \u0005[שמו]\u0006 \u0003חסרון. ולא קשיא\u0004 \u0005[קשה]\u0006 הסתירה בין שתי הברייתות; \u0003כאן,\u0004 שהיא פסולה — \u0003שחסרה\u0004 כליה \u0003קודם שחיטה,\u0004 ו\u0003כאן,\u0004 שהיא כשרה — \u0003שחסרה\u0004 כליה \u0003לאחר שחיטה.\u0004 ושואלים: \u0003ו\u0004כשחסר קרבן \u0003לאחר שחיטה, קודם קבלה\u0004 של דמו בכלי (כדי לזורקו על המזבח), \u0003מי שרי\u0004 \u0005[האם מותר]\u0006 להקריב את הקרבן?"],["\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זירא אמר רב: הצורם\u0004 (חותך, פוגם) \u0003אזן הפר\u0004 לאחר שנשחט לקרבן, \u0003ואחר כך קיבל\u0004 הכהן \u0003דמו\u0004 — \u0003פסול\u0004 הדם לזריקה, \u0003שנאמר\u0004 בקבלת הדם: \u0003\"ולקח מדם הפר\"\u0004 (ויקרא ד, ה) — \u0003הפר שהיה כבר,\u0004 כמו שהיה בחייו, ולא שחסר! \u0003אלא\u0004 יש לתקן ולומר: \u0003כאן\u0004 שפסול — \u0003שחסרה\u0004 כליה \u0003קודם קבלה\u0004 של דמו בכלי, \u0003כאן\u0004 — \u0003שחסרה לאחר קבלה.\u0004","ושואלים: \u0003ו\u0004כשחסרה \u0003לאחר קבלה, קודם זריקה\u0004 של דמו על המזבח, \u0003מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 נאמר לגבי קרבן הפסח \u0003\"שה תמים זכר בן שנה יהיה לכם\"\u0004 (שמות יב, ה), מלמד \u0003שיהא תמים בן שנה\u0004 (בן שנתו הראשונה) \u0003בשעת שחיטה.\u0004","\u0003ומנין\u0004 שצריך להיות כן גם \u0003ב\u0004שעת \u0003קבלה\u0004 של הדם בכלי, \u0003ו\u0004בשעת \u0003הולכה\u0004 של הדם למזבח, \u0003ו\u0004בשעת \u0003הזייה\u0004 (זריקה)? \u0003תלמוד לומר: \"יהיה\"\u0004 (שמות יב, ה) — \u0003שיהו כל הויותיו,\u0004 כל הנעשה בו, כשהוא \u0003תם ובן שנה.\u0004 הרי שהקרבן צריך להיות בשלמותו גם בשעת זריקת הדם!","ומשיבים: \u0003תרגמא\u0004 \u0005[תרגם,\u0006 הסבר, דרשה \u0005זו],\u0006 רק לענין שיהיה \u0003בן שנה\u0004 בשעת זריקה, ולא לענין שיהיה תם. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 כפירוש זה, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהושע אומר: כל הזבחים שבתורה ש\u0004נשחטו ונתקבל דמם בכלי, ו\u0003נשתייר מהן\u0004 אפילו רק \u0003כזית בשר\u0004 (לאכילה) \u0003או כזית חלב\u0004 (להקטירו על המזבח) — \u0003זורק את הדם, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאפילו חסרון גדול אינו פוסל אחרי קבלת הדם.","על הסבר זה של הדרשה שואלים: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר,\u0006 האם ייתכן\u0005]\u0006 ש\u0003בשעת שחיטה הוי\u0004 \u0005[הריהו]\u0006 \u0003בן שנה\u0004 (בתוך שנתו הראשונה), \u0003ובשעת קבלה והולכה הוי\u0004 \u0005[הרי הוא]\u0006 \u0003בן שתי שנים,\u0004 שהוצרכנו ללמוד שהוא פסול? \u0003אמר רבא: זאת אומרת\u0004 שאפילו \u0003שעות פוסלות בקדשים,\u0004 וכגון מקרה זה, שכבש בן שנה ושעה אחת פסול לקרבן הפסח, ולפי זה ייתכן שעברה שנתו בדיוק בשלב שבין שחיטה לקבלה והולכה. ושבים לעיקר הדיון, האם חסרון איבר מבפנים פוסל את הבהמה להקרבה.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שדבר זה שנוי במחלוקת \u0005תנאים]?\u0006 שכן שנינו, מה שנאמר ברשימת בעלי החיים הפסולים להקרבה: \u0003\"ומעוך וכתות ונתוק וכרות\u0004 לא תקריבו לה'\" (ויקרא כב, ד) — \u0003כולן בביצים\u0004 (אשכים), \u0003דברי ר' יהודה.\u0004","ותמהים: וכי אפשר לומר שהם פוסלים לדעתו רק \u0003בביצים ולא בגיד\u0004 (באיבר)? והלא בגיד ניכר הדבר יותר! אלא \u0003אימא\u0004 \u0005[אמור]:\u0006 לא רק בגיד, אלא \u0003אף בביצים,\u0004 אלו \u0003דברי ר' יהודה. ר' אליעזר בן יעקב אומר: כולן בגיד. רבי יוסי אומר: מעוך וכתות\u0004 — \u0003אף בביצים; נתוק וכרות, בגיד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בביצים\u0004 — \u0003לא.\u0004","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006בעיה \u0005זו\u0006 הם \u0005חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003חסרון מבפנים שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003חסרון,\u0004 ולפיכך, בכל מקרים אלה, שהביצים נמעכו, או ששוב אינן מתפקדות — כאילו נחסרו, והרי זה אוסר בהקרבה, למרות שאין זה ניכר. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר בן יעקב, \u0005סבור]:\u0006 \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003חסרון?\u0004","ותוהים: \u0003ותסברא\u0004 \u0005[וכי יכול אתה לסבור כן]?\u0006 אם כן, לפי דרך זו, \u0003ר' יוסי,\u0004 שמחלק בין נתוק וכרות לבין מעוך וכתות, \u0003מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 ש\u0003חסרון מבפנים שמיה\u0004 \u0005[שמו]\u0006 \u0003חסרון\u0004 — \u0003אפילו נתוק וכרות נמי\u0004 \u0005[גם כן]\u0006 ייחשב חסרון, אף שאינו נראה! \u0003ואי קסבר\u0004 \u0005[ואם סבור]\u0006 \u0003לא שמיה\u0004 \u0005[שאין שמו]\u0006 \u0003חסרון\u0004 — \u0003אפילו מעוך וכתות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ייחשב חסרון, שהרי אינו נראה בגלוי!","\u0003אלא,\u0004 יש לפרש בדרך אחרת: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003במומים שבגלוי קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 מה נחשב כמום גלוי. \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003מעוך וכתות הוי מומא\u0004 \u0005[הרי זה מום]\u0006 גלוי, מפני \u0003דמיכווצן\u0004 \u0005[ש\u0006הביצים \u0005מתכווצות]\u0006 בגלל המעיכה, והדבר ניכר בחוץ. וכן \u0003נתוק וכרות הוי מומא\u0004 \u0005[הרי זה מום],\u0006 \u0003דהא תליין\u0004 \u0005[שהרי הן\u0006 נראות \u0005תלויות\u0006 מידלדלות\u0005],\u0006 ואינן נראות מחוברות כרגיל. ואילו \u0003ר' אליעזר בן יעקב סבר\u0004 \u0005[סבור]:\u0006 \u0003מעוך וכתות לא הוי מומא\u0004 \u0005[אינו מום],\u0006 מפני שאין זה ניכר, \u0003דמעיקרא נמי זמנין דמיכווצן\u0004 \u0005[ש\u0006הרי \u0005מתחילה גם כן,\u0006 קודם שנמעכו או נכתתו, \u0005פעמים ש\u0006הן \u0005מתכווצות].\u0006 וכן \u0003נתוק וכרות לא הוי מומא\u0004 \u0005[אינו מום],\u0006 מפני \u0003דמעיקרא נמי זימנין דתליין\u0004 \u0005[שמתחילה גם כן פעמים שהן תלויות]. ור'יוסי סבר\u0006","\u0005[סבור]:\u0006 \u0003מעוך וכתות הוי מומא\u0004 \u0005[הרי הוא מום]\u0006 — \u0003דהא ליתנהו\u0004 \u0005[שהרי אינן\u0006 מצויות כלל\u0005],\u0006 שבגלל המעיכה הן שבורות לגמרי, \u0003נתוק וכרות לא הוי מומא\u0004 \u0005[אינו מום]\u0006 — \u0003דהא איתנהו\u0004 \u0005[שהרי הן מצויות]\u0006 בכיס, אף שאינן מתפקדות.","ועוד מומים ששוחטים עליהם את הבכור מחוץ למקדש: \u0003נפגם\u0004 (נחסר) \u0003הזובן\u0004 של הבכור (מעין כיס שאיבר הזכרות חבוי בו), \u0003או העריה\u0004 (בית הערוה, הבולט לחוץ) \u0003של נקבה ב\u0004שאר \u0003מוקדשין,\u0004 הבאים גם מן הנקבות. וכן אם \u0003נפגם הזנב מן העצם,\u0004 כלומר, בחוליות הזנב עצמן, \u0003אבל לא מן הפרק\u0004 שבין חוליה לחוליה, מפני שהוא חוזר ונרפא. \u0003או שראש\u0004 (קצה) ה\u0003זנב מפצל,\u0004 כלומר, ש\u0003נקלפה העור והבשר והעצם נשאר, או שיש בשר מחוליא\u0004 (בין חוליה) \u0003לחוליא מלא אצבע.\u0004","שנינו במשנתנו: נפגם הזובן. ועל כך \u0003אמר ר' אלעזר:\u0004 דוקא \u0003נפגם\u0004 הרי זה מום, \u0003ולא\u0004 במקרה ש\u0003ניטל.\u0004 וכן דווקא \u0003כיס\u0004 (הזובן) שנפגם, \u0003ולא זכרות\u0004 (הגיד). ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003נפגם\u0004 — \u0003ולא ניטל, כיס\u0004 — \u0003ולא זכרות\u0004 עצמה. וכן \u0003אמר ר' יוסי בן המשולם: מעשה בעינבל אחד שנטלו זאב,\u0004 את הזובן, \u0003וחזר\u0004 אחר כך \u0003לאיתנו,\u0004 שחזר וצמח.","שנינו במשנה: \u0003נפגמה הזנב מן העצם וכו'\u0004 או שיש בשר מחוליא לחוליא מלא אצבע. ומביאים דיון שהוזכרה בו משנתנו. \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003אצבע שאמרו\u0004 חכמים להלכה, היא \u0003אחד מארבעה בטפח של כל האדם.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזה\u0006 ענין נאמרה \u0005הלכה\u0006 זו\u0005]?\u0006 \u0003אמר רבה: לענין תכלת,\u0004 אורך חוטי הציצית. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כמה חוטין הוא נותן\u0004 בציצית? \u0003בית שמאי אומרים: ארבעה\u0004 חוטים, שכופלים אותם ונראים כשמונה. \u0003ובית הלל אומרים: שלשה.\u0004","\u0003וכמה תהא משולשת,\u0004 כלומר, כמה יהא אורכה של הציצית, כשהיא משולשלת מן הבגד? \u0003בית שמאי אומרים: ארבעה\u0004 אצבעות, \u0003ובית הלל אומרים: שלשה\u0004 אצבעות. ומוסיפים: \u0003ושל(י)ש\u0004אצבעות \u0003שבית הלל אומרים,\u0004 כלומר, שיעור אצבע לענין זה, הוא \u0003אחד מארבע בטפח של כל אדם.\u0004 והיא אותה הלכה שנאמרה בברייתא שאנו דנים בפירושה.","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר:\u0004 הלכה זו של מידת האצבע נאמרה \u0003ל\u0004ענין \u0003שתי אמות\u0004 (מידות באורך אמה) שהיו במקדש, \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003שתי אמות\u0004 \u0003היו\u0004"],["\u0003בשושן הבירה\u0004 (מקום מיוחד מעל לשער המזרחי של הר הבית), \u0003אחת\u0004 מן האמות \u0003על קרן מזרחית צפונית, ואחת על קרן מזרחית דרומית.\u0004 זו \u0003שעל קרן מזרחית צפונית היתה יתירה על\u0004 אמה \u0003של משה,\u0004 שהשתמש בה לצורך בניית המשכן, \u0003חצי אצבע, ושעל קרן מזרחית דרומית היתה יתירה עליה\u0004 על האמה הזו \u0003חצי אצבע\u0004 נוספת, \u0003נמצאת\u0004 הגדולה \u0003יתירה על של משה אצבע.\u0004","\u0003ולמה היו אחת גדולה\u0004 (אלו שהיו בשושן הבירה) \u0003ואחת קטנה\u0004 (של משה)? \u0003כשהיו אומנין\u0004 (בעלי מלאכה) עושים מלאכתם במקדש היו \u0003נוטלין בקטנה,\u0004 כלומר, מחשבים את שכרם, כך וכך דינרים לאמה, לפי האמה של משה, \u0003ומחזירין בגדולה,\u0004 כלומר, עושים בפועל לפי מידתה של אחת משתי אמות אלה, כדי \u0003שלא יבואו לידי מעילה,\u0004 שמא יטלו מן ההקדש יותר מן הראוי. ועל אותה אצבע ששנינו במשנה זו, שהגדולה יתירה על של משה, אמרו בברייתא שהיא אחד מארבעה בטפח של כל אדם.","ולגופה של משנה זו שואלים: \u0003תרתי\u0004 \u0005[שתים]\u0006 שתי אמות יתירות על של משה, בשני גדלים שונים, \u0003למה לי?\u0004 ומשיבים: \u0003חדא\u0004 — \u0003דכספא וזהבא\u0004 \u0005[אחת,\u0006 הקטנה — \u0005של\u0006 מלאכת \u0005כסף וזהב],\u0006 שמלאכתם יקרה, והפסדם של האומנים גדול אפילו בהפרש מועט. \u0003וחדא דבניינא\u0004 \u0005[ואחת,\u0006 הגדולה — \u0005של בנין]\u0006 אבן ועץ.","\u0003רב נחמן בר יצחק, ואי תימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב הונא בר נתן\u0004 אמר: מה ששנו בברייתא שאצבע שאמרו חכמים אחד מארבעה בטפח של כל אדם, נאמר ביחס \u0003לאותה\u0004 הלכה \u0003ששנינו\u0004 במשנתנו, לענין מומי הבכור: \u0003ש\u0004אם \u0003יש בשר בין חוליא לחוליא\u0004 של הזנב, \u0003מלא אצבע\u0004 — הרי זה מום.","ועוד מומים ששוחטים עליהם את הבכור מחוץ למקדש: \u0003אין לו ביצים\u0004 (אשכים), \u0003או אין לו אלא ביצה אחת. ר' ישמעאל אומר: אם יש לו שני כיסין\u0004 של ביצים — \u0003יש לו שתי ביצים, אין לו שני כיסין,\u0004 אלא אחד — \u0003אין לו אלא ביצה אחת. ר' עקיבא אומר:\u0004 ניתן לברר את הדבר. כיצד? \u0003מושיבו על עכוזו\u0004 (אחוריו) \u0003וממעך,\u0004 ממשמש ודוחק באותו מקום, לפי ש\u0003אם יש ביצה\u0004 — \u0003סופו לצאת.\u0004 ואם מיעך ולא יצאה — הרי זה מום, ומותר לשחוט את הבכור. מסופר, \u0003מעשה\u0004 בבכור שלא היתה לו אלא ביצה אחת, \u0003שמיעך ולא יצא\u0004 ביצה שניה, ו\u0003נשחטה\u0004 הבהמה, כדין בכור בעל מום, \u0003ונמצאת\u0004 הביצה \u0003דבוקה בכסלים\u0004 (בחלק הפנימי של הירך), \u0003והתיר ר' עקיבא\u0004 לאכול את בשר הבכור, מפני שלא יצאה על ידי מיעוך, \u0003ואסר ר' יוחנן בן נורי.\u0004","שנינו במשנה: אין לו ביצים או אין לו אלא ביצה אחת הרי זה מום. ושואלים: מדוע הוצרך לשנות כך? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003אין לו אלא ביצה אחת אמרת\u0004 \u0005[אומר אתה]\u0006 כי \u0003הוי מומא\u0004 \u0005[הרי זה מום],\u0006 אם \u0003אין לו כלל\u0004 ביצים \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך היא שנויה]:\u0006 \u0003אין לו שתי ביצים בשתי כיסין אלא בכיס אחד, אי נמי\u0004 \u0005[או גם כן]\u0006 יש לו \u0003שתי כיסין וביצה אחת\u0004 — \u0003הרי זה מום.\u0004","\u0003ר' ישמעאל אומר: יש לו שתי כיסים\u0004 — \u0003בידוע שיש לו שתי ביצים,\u0004 ואינו בעל מום, ואסור לשוחטו. אבל אם \u0003אין לו אלא כיס אחד\u0004 — \u0003כמי שאין לו אלא ביצה אחת דמי\u0004 \u0005[נחשב],\u0006 אף שבאמת יש לו שתים. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' עקיבא למימר\u0004 \u0005[לומר]:\u0006 אם יש לו שני כיסים, \u0003בידוע\u0004 שיש לו שתי ביצים \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 \u0003אלא מושיבו על עכוזו\u0004 (אחוריו) \u0003וממעך, אם יש ביצה סופו לצאת,\u0004 ואם לא יצאה, סימן הוא שאין לו אלא אחת, ובעל מום הוא.","שנינו במשנה: \u0003ומעשה שמיעך ולא יצא וכו'.\u0004 ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 שמסופר בה מעשה זה בהרחבה. \u0003אמר ר' יוסי: מעשה בפירן של בית מנחם,\u0004 בבכור שלא נמצאה לו אלא ביצה אחת, \u0003שמיעך ולא יצאת\u0004 (יצאה) הביצה השניה, \u0003ונשחטה ונמצאת דבוקה בכסלים, והתיר ר' עקיבא\u0004 את הבכור באכילה, \u0003ואסר ר' יוחנן בן נורי.\u0004","\u0003אמר לו ר' עקיבא לר' יוחנן בן נורי: עד מתי אתה מכלה ממונן של ישראל,\u0004 שאתה אוסר בכגון זה! \u0003אמר לו ר' יוחנן בן נורי לר' עקיבא: עד מתי אתה מאכיל\u0004 את \u0003ישראל נבילות!\u0004 ותוהים: מדוע נבילות? \u0003לאו מישחט שחטיה\u0004 \u0005[\u0006וכי \u0005לא שחט אותה]?\u0006","ומתרצים, \u0003אלא\u0004 כך אמר לו: עד מתי אתה מאכיל את ישראל \u0003טריפות.\u0004 וגם על כך מקשים: והרי \u0003לא איסור טריפות הוא! אלא\u0004 כך אמר לו: \u0003עד מתי אתה מאכיל\u0004 את \u0003ישראל קדשים בחוץ!\u0004 שהרי לדעת ר' יוחנן בן נורי אין זה מום, ונמצא מתיר אכילת קדשים תמימים מחוץ למקדש.","ועוד ברשימת המומים ששוחטים עליהם את הבכור מחוץ למקדש: \u0003בעל חמש רגלים, או שאין לו אלא שלש. ושרגליו קלוטות,\u0004 שפרסותיו מעוגלות וסגורות \u0003כ\u0004פרסות \u0003של חמור,\u0004 ולא שסועות לשתים. \u0003והשחול והכסול. איזהו שחול? שנשמטה יריכו,\u0004 שיצאה עצם הירך ממקומה, והרגל נראית שמוטה, \u0003וכסול\u0004 — \u0003שאחת מיריכים\u0004 שלו \u0003גבוהות\u0004 מן השניה.","שנינו במשנה: בעל חמש רגלים או שאין לו אלא שלוש הרי זה מום. \u0003אמר רב הונא: לא שנו אלא שחסר ויתר ביד,\u0004 ברגליים הקדמיות, אבל אם חסר ויתר \u0003ברגל,\u0004 ברגליים האחוריות — לא רק שהוא בעל מום, אלא \u0003טרפה נמי הוי\u0004 \u0005[גם כן הוא],\u0006 ואם נשחט — אסור באכילה, מפני ש\u0003כל\u0004 איבר \u0003יתיר\u0004 בגוף הבהמה — \u0003כנטול דמי\u0004 \u0005[נחשב],\u0006 כאילו נחתך איבר כזה מגופה, ובהמה שניטלה רגלה האחורית הריהי טריפה.","על מה שנאמר במשנה שכשפרסותיו קלוטות כשל חמור הרי זה מום, \u0003אמר רב פפא: לא תימא דעגילן ולא סדיקן\u0004 \u0005[אל תאמר\u0006 שהוא מום רק במקרה \u0005שהן\u0006 ממש כשל חמור, \u0005עגולות ואינן סדוקות\u0006 כלל\u0005],\u0006 \u0003אלא כיון דעגילן\u0004 \u0005[שהן עגולות]\u0006 \u0003אף על גב דסדיקן\u0004 \u0005[אף על פי שהן סדוקות],\u0006 מכל מקום הרי זה נחשב למום.","שנינו במשנה: \u0003והשחול והכסול וכו'.\u0004 ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו כסול ואיזהו שחול? שחול\u0004 — \u0003שנשמטה יריכו, כסול\u0004 — \u0003שרגלו אחד בתוך הכסל,\u0004 כלומר, שעצם הירך במקומה, \u0003ורגלו אחד\u0004 יצאה העצם ממקומה, והיא \u0003על גבי הכסל. תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 מהם \u0003השרוע והקלוט,\u0004 שהוזכרו בתורה כאסורים בהקרבה (ויקרא כב, כג)? שרוע — \u0003שנשתרבב לו יריכו,\u0004 שהיא ארוכה מחבירתה. \u0003קלוט\u0004 — \u0003שרגליו\u0004 (כלומר, פרסותיו) \u0003קלוטות כשל חמור וכשל סוס.\u0004","ועוד במומי הבכור: \u0003נשבר עצם ידו\u0004 או \u0003עצם רגלו, אף על פי שאינו ניכר,\u0004 הרי זה מום. \u0003מומין אלו\u0004 ששנינו בפרק זה, \u0003מנה אילא,\u0004 שהיה מומחה במומי הבכור, \u0003ביבנה, והודו לו חכמים.\u0004","\u0003ועוד שלשה\u0004 מיני מומים \u0003הוסיף, אמרו לו\u0004 חכמים: \u0003לא שמענו את אלו.\u0004 ומה הוסיף? בכור בהמה \u0003שגלגל עינו עגול כשל אדם, ופיו דומה כשל חזיר, ושניטל רוב\u0004 החלק \u0003המדבר בלשונו\u0004 (אילו היה זה אדם שמדבר), כלומר, החלק שאינו דבוק למקומו. \u0003בית דין של אחריהן אמרו:\u0004 גם שלושה מומים אלו שמנה אילא \u0003הרי זה מום,\u0004 ומותר לשחוט על כך את הבכור.","שנינו שאם נשברה עצם ידו או רגלו, אף על פי שאינו ניכר — הרי זה מום. ושואלים: אם היה זה שבר ש\u0003אינו ניכר, מי קא הוי מומא\u0004 \u0005[האם הוא מום]?\u0006 והלא רק מום שבגלוי נחשב למום! (ראה לעיל לז,ב). \u0003אמר רב פפא:\u0004 הכוונה היא ש\u0003אינו ניכר מחמת עצמו,\u0004 שאין שינוי צורה ברגל, \u0003אבל ניכר מחמת מלאכה,\u0004 בצורת ההליכה.","שנינו: \u0003מומין אלו מנה\u0004 אילא ביבנה, והוסיף עליהם עוד שלושה, וביניהם — את שגלגל עינו עגול כשל אדם. ושואלים: \u0003למימרא דלאו היינו אורחיה\u0004 \u0005[האם לומר שאין זה דרכו]\u0006 של בעל חיים? \u0003ורמינהו\u0004 \u0005[ומקשים]\u0006 על כך ממה ששנינו: אשה \u0003המפלת\u0004 עובר, הנראה כאילו הוא \u0003מין בהמה וחיה ועוף, בין\u0004 אם הוא נראה ממין בעלי חיים \u0003טמאין, בין\u0004 אם הוא נראה ממין \u0003טהורין, אם זכר\u0004 הוא העובר — \u0003תשב\u0004 ימי טומאה וימי טהרה כמו \u0003ל\u0004לידת \u0003זכר,\u0004 שבעה ימי טומאה, ושלושים ושלושה ימים שדמה טהור (ויקרא יב, ב—ד).","\u0003אם\u0004 היה הנפל \u0003נקבה\u0004 — \u0003תשב\u0004 כמו \u0003לנקבה,\u0004 ארבעה עשר יום ימי טומאה, וששים וששה יום ימי טהרה (ויקרא יב, ה). אם \u0003אינו ידוע\u0004 אם זכר או נקבה — \u0003תשב לזכר ולנקבה,\u0004 כחומרה שבשניהם: ארבעה עשר ימי טומאה, כנקבה, ומאז מונה תשעה עשר ימי טהרה בלבד, עד מלאת שלושים ושלושה ימי טהרה של זכר. אלו \u0003דברי ר' מאיר.\u0004","\u0003ואמר רבה בר בר חנה אמר ר' יוחנן: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' מאיר,\u0004 שהמפלת כמין בעל חיים דינה כמפלת ולד אדם — \u0003הואיל וגלגל עינו\u0004 של בעל חיים \u0003עגול כשל אדם! אמר רב יוסף: לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003באוכמא\u0004 \u0005[בשחור\u0006 של העין\u0005],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003בחיוורא\u0004 \u0005[בלבן].\u0006","ועוד שנינו בין המומים: \u0003ופיו דומה כשל חזיר. אמר רב פפא: לא תימא דשפיד\u0004 \u0005[אל תאמר ש\u0006הוא רק כשהפה \u0005מחודד]\u0006 \u0003ופרוס,\u0004 שהשפה העליונה פרוסה על התחתונה ועודפת עליה, ממש כשל חזיר. \u0003אלא כיון\u0004 ש\u0003פרוס אף על גב דלא שפיד\u0004 \u0005[אף על פי שאינו מחודד],\u0006 הרי זה מום.","ועוד שנינו: \u0003ושניטל רוב המדבר שבלשונו.\u0004 ומעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ואת שניטל רוב הלשון\u0004 הרי זה מום. \u0003ר' יהודה אומר:\u0004 לאו דוקא רוב הלשון, אלא \u0003רוב המדבר של לשונו.\u0004","\u0003ומעשה\u0004 היה \u0003שהלחי התחתון\u0004 של הבכור היה \u0003עודף על העליון, ושאל רבן גמליאל לחכמים, ואמרו: הרי זה מום.\u0004","ושואלים: \u0003מאי תנא דקתני\u0004 \u0005[מה שנה\u0006 תחילה במשנה \u0005שהוא שונה]\u0006 כאן \u0003\"ומעשה\"?\u0004 מדוע הוא שונה כאן מעשה זה? ומשיבים: \u0003משום דתנן\u0004 \u0005[ששנינו]\u0006 ברשימת המומים שהוסיף אילא במשנה הקודמת: \u0003פיו דומה לחזיר, ופליגי רבנן עליה\u0004 \u0005[וחלקו חכמים עליו]\u0006 על \u0003רבי\u0004 אילא. \u0003וקאמרינן\u0004 \u0005[ו\u0006על כך \u0005אנו אומרים]:\u0006 \u0003כי פליגי רבנן עליה\u0004 \u0005[כאשר חלוקים חכמים על]\u0006 \u0003רבי\u0004 אילא, ואינם מתירים לשוחטו כשפיו דומה לשל חזיר — הרי זה כש\u0003שפתו עליונה עודפת על התחתונה, אבל\u0004 כ\u0003שהתחתונה עודפת על העליונה\u0004 — לכל הדעות \u0003הרי זה מום.\u0004"],["\u0003ומעשה נמי\u0004 \u0005[גם כן]\u0006 היה \u0003שלחי התחתון עודף על העליון,\u0004 ו\u0003שאל רבן שמעון בן גמליאל לחכמים, ואמרו: הרי זה מום.\u0004","ומקשים: \u0003והא גבי\u0004 \u0005[והרי אצל]\u0006 מומי \u0003אדם הוא דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שפתו העליונה עודפת על התחתונה, או שתחתונה עודפת על העליונה\u0004 — \u0003הרי זה מום.\u0004 ויש לדייק: דוקא \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אדם הוא\u0004 מום, משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"איש איש מזרע אהרן\"\u0004 (ויקרא כב, ד), ומכאן למדים כי הכהן צריך להיות \u0003איש ששוה בזרעו של אהרן,\u0004 שמראהו רגיל, כשל שאר אחיו הכהנים, ומי שמראהו אינו רגיל — פסול. \u0003אבל בבהמה לא\u0004 נאמר דבר זה, ואם כן, אם שפתו התחתונה עודפת על העליונה — אין זה מום כשלעצמו!","\u0003אמר רב פפא: לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 מדובר \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה\u0004 בלחי התחתונה \u0003עצם\u0004 ארוכה יותר משל הלחי העליונה, ואז הוא מום גם בבהמה, \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה עצם,\u0004 ואז אין זה מום בבהמה, אלא באדם בלבד.","ועוד בענין המומים ששוחטים עליהם את הבכור מחוץ למקדש. \u0003אוזן הגדי\u0004 ש\u0003היתה כפולה,\u0004 שנכפלה אוזנו, כאילו יש לו אוזן נוספת, \u0003אמרו חכמים: בזמן שהוא עצם אחד,\u0004 שיש לאותה אוזן נוספת סחוס לעצמו — הרי זה \u0003מום, בזמן שאין בו עצם\u0004 — \u0003אינו מום. ר' חנניא בן גמליאל אומר: זנב הגדי שהוא דומה לשל חזיר,\u0004 או שהוא קצר כל כך \u0003שאין בה שלש חוליות\u0004 — \u0003הרי זה מום.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003פיו\u0004 של בכור בהמה \u0003בלום\u0004 (נפוח) \u0003ו\u0004כן אם \u0003רגליו מבולמות\u0004 (מנופחות), יש לחלק בענין זה: אם \u0003מחמת הרוח,\u0004 כלומר, מחמת שהתנפח — \u0003אינו מום, מחמת העצם\u0004 שהיתה גדולה במיוחד — \u0003הרי זה מום. אזניו כפולות,\u0004 אם מדובר \u0003בחסחסות\u0004 (סחוס) \u0003אחת\u0004 — \u0003הרי זה מום, בשתי חסחסיות\u0004 — \u0003אינו מום.\u0004","שנינו במשנה, \u0003רבן גמליאל אומר: זנב הגדי שהוא דומה לשל חזיר\u0004 — הרי זה מום. \u0003אמר רב פפא: לא תימא\u0004 \u0005[אל תאמר]\u0006 שהוא מום, דוקא במקרה \u0003דקטינא\u0004 \u0005[ש\u0006היא \u0005דקה\u0006 כשל חזיר\u0005],\u0006 \u0003אלא דכריכא\u0004 \u0005[\u0006כל \u0005שהיא עגולה]\u0006 כזנב החזיר, \u0003אף על גב דאלימא\u0004 \u0005[אף על פי ש\u0006היא \u0005עבה]\u0006 כשל גדי — הרי זה מום.","עוד שנינו במשנה: \u0003או שאין בה\u0004 בזנב \u0003שלש חוליות\u0004 — הרי זה מום. ובאותו ענין \u0003אמר רב הונא:\u0004 \u0003ב\u0004זנב של \u0003גדי\u0004 עזים, שתים, שתי חוליות — \u0003הרי זה מום, שלש\u0004 — \u0003אינו מום. בטלה\u0004 של כבשים, \u0003שלש\u0004 חוליות — \u0003הרי זה מום, ארבע\u0004 — \u0003אינו מום. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003בגדי,\u0004 אם היתה בזנבו רק חוליה \u0003אחת\u0004 — \u0003הרי זה מום, שתים\u0004 — \u0003אינו מום. בטלה, שתים\u0004 — \u0003הרי זה מום, שלש\u0004 — \u0003אינו מום!\u0004 ואומרים: אכן \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה\u0005]\u0006 היא על \u0003רב הונא.\u0004","ומעירים: \u0003ורב הונא\u0004 שאמר דבר זה, \u0003מתניתין אטעיתיה\u0004 \u0005[משנתנו הטעתה אותו];\u0006 \u0003איהו\u0004 \u0003סבר\u0004 \u0005[הוא\u0006 היה \u0005סבור]:\u0006 \u0003מדרישא\u0004 \u0005[מ\u0006כיון \u0005שראשה,\u0006 תחילתה, של המשנה\u0005]\u0006 מדבר \u0003ב\u0004זנב \u0003גדי\u0004 שהוא דומה לשל חזיר — \u0003סיפא נמי\u0004 \u0005[סופה גם כן],\u0006 שאין בה שלוש חוליות, מדבר \u0003בגדי. ולא היא\u0004 \u0005[ואינו כן],\u0006 \u0003רישא\u0004 \u0005[ראשה,\u0006 תחילתה\u0005]\u0006 מדבר \u0003ב\u0004זנב ה\u0003גדי, וסיפא\u0004 \u0005[וסופה]\u0006 \u0003ב\u0004זנב ה\u0003טלה,\u0004 כמו שמבואר בברייתא.","ועוד מומים ששוחטים עליהם את הבכור. ר' חנינא בן אנטיגנוס אומר: את שיבלת בעיניו, ושנפגם עצם ידו ורגלו, ושנפרק עצמו (העצם) \u0003של פיו,\u0004 כלומר, הלסת. \u0003עינו אחת גדולה ואחת קטנה, אזנו אחד גדולה ואחד קטנה, במראה,\u0004 כלומר, שההבדל בין העיניים והאוזניים ניכר גם במראה העין, \u0003אבל לא\u0004 כשהוא נבחן \u0003במדה\u0004 (במדידה) בלבד. \u0003ר' יהודה אומר:\u0004 אם היו \u0003שתי ביציו, אחת\u0004 מהן \u0003גדולה כשתים\u0004 (פי שתים) \u0003שבחבירתה\u0004 — הרי זה מום, \u0003ולא הודו לו חכמים.\u0004","שנינו במשנה: את שיבלת בעינו הרי זה מום. ותמהים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003יבלת הוי מומא\u0004 \u0005[הרי היא מום]?\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה להלן: \u0003ואלו שאין שוחטין עליהן לא במקדש,\u0004 מפני שאין הם ראויים להקרבה, \u0003ולא במדינה\u0004 (מחוץ למקדש), משום שאין זה נחשב למום גמור — \u0003בעל גרב\u0004 (שחין), \u0003ובעל יבלת!\u0004 ועל עצם העמדת הסתירה מקשים: ותסברא \u0005[ו\u0006יכול אתה \u0005לסבור\u0006 כן\u0005]\u0006 שיבלת אינה מום גמור?","\u0003הא כתיבא\u0004 \u0005[הרי כתובה]\u0006 \u0003יבלת באורייתא\u0004 \u0005[בתורה]\u0006 בין המומים הגמורים (ויקרא כב, כב)! \u0003אלא לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו במשנה להלן שאינה מום גמור — הרי זו יבלת \u0003בגופו,\u0004 \u0003הא\u0004 \u0005[זו]\u0006 שהוזכרה בתורה ובמשנתנו כמום גמור — הרי זו יבלת \u0003בעינו.\u0004","ומקשים: \u0003מכדי\u0004 \u0003קרא סתמא\u0004 \u0005[הואיל ובמקרא\u0006 נאמר \u0005בסתם]\u0006 \"יבלת\", \u0003מה לי בגופו ומה לי בעינו? אלא\u0004 יש להסביר באופן אחר: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה\u0004 ביבלת \u0003עצם, הא\u0004 \u0005[זו]\u0006 \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה עצם.\u0004","ומפרטים: \u0003דקרא\u0004 \u0005[\u0006היבלת \u0005שבמקרא],\u0006 שהיא מום גמור, היא זו \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה עצם,\u0004 ואילו היבלת של \u0003מתניתין\u0004 \u0005[המשנה] — היא זו\u0006 \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה עצם.\u0004 וכך יש לחלק בעניינה: אם היבלת היא \u0003בעינו\u0004 — \u0003הוי מומא\u0004 \u0005[הרי זה מום],\u0006 וכפי ששנינו במשנתנו. ואם היא \u0003בגופא\u0004 \u0005[בגוף]\u0006 — \u0003לא הוי מומא\u0004 \u0005[אין היא מום],\u0006 אבל היא פוסלת להקרבה, וכפי ששנינו במשנה להלן.","ושואלים: \u0003ולית לה עצם בגופא\u0004 \u0005[ו\u0006יבלת \u0005שאין לה עצם בגוף]\u0006 \u0003פסולה\u0004 היא? \u0003הרי תלתול\u0004 (בשר או עור מדולדל) \u0003בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 שאינו פוסל, וכפי \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: בעלי התילולין\u0004 (דלדולי עור או בשר) \u0003פסולין באדם וכשירין בבהמה! אלא\u0004 צריך לומר אחרת: \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 גם במשנה זו וגם במשנה להלן, מדובר ביבלת \u0003בעינו, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 במשנתנו, שהיא מום גמור, מדובר כשהיתה היבלת \u0003בשחור\u0004 שבעין, ואילו \u0003הא\u0004 \u0005[זה],\u0006 במשנה להלן, שאינה מום, אבל פוסלת להקרבה — כשהיתה היבלת \u0003בלבן.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 שנינו כי \u0003אין מומין בלבן,\u0004 ומשמע שהבהמה כשרה אפילו להקרבה! \u0003אלא,\u0004 יש לפרש כך: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003בלבן, ואמר ריש לקיש: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שיבלת אינה נחשבת כמום, אבל פוסלת להקרבה — הרי זה במקרה \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה שער, הא\u0004 \u0005[זה]\u0006 שאין זה מום כלל — במקרה \u0003דלית ד\u0004\u0005[שאין]\u0006 \u0003בה שער.\u0004 ובמשנתנו, שיבלת נחשבת כמום גמור — מדובר ביבלת שבשחור.","שנינו במשנה: \u0003עינו אחת גדולה\u0004 ואחת קטנה — הרי זה מום. ועל כך \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003גדולה\u0004 — \u0003כשל עגל, קטנה\u0004 — \u0003כשל אווז.\u0004","ועוד שנינו: \u0003אזנו אחת גדולה וכו',\u0004 ר' יהודה אומר: אחת מביציו גדולה כשתיים בחבירתה — הרי זה מום, ולא הודו לו חכמים. ושואלים: ורבנן \u0005[ו\u0006לשיטת \u0005חכמים]\u0006 \u0003עד כמה\u0004 יהיה ההבדל בין הביצים, ולא יהיה מום? ומשיבים, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אחרים אומרים: אפילו אינה לשניה,\u0004 הקטנה, \u0003אלא כ\u0004גודל \u0003פול\u0004 — בכל זאת היא \u0003כשירה.\u0004","\u0003זנב העגל\u0004 שהוא קצר, \u0003שאינה מגעת לערקוב\u0004 (פרק הרגל), \u0003אמרו חכמים:\u0004 הרי זה מום, משום ש\u0003כל מרבית\u0004 (דרך גדילה של) \u0003עגלים כן\u0004 היא: \u0003כל זמן שיהו מגדלין\u0004 — \u0003הן\u0004 זנבותיהם \u0003נמתחות,\u0004 מתארכות למטה מן הערקוב. וזה שזנבו קצר — מום הוא. \u0003איזהו ערקוב שאמרו?\u0004 איזה פרק מפרקי רגל הבהמה? \u0003ר' חנינא בן אנטיגנוס אומר: בערקוב ש\u0004נמצא \u0003באמצע הירך.\u0004"],["בענין ששנינו במשנתנו: זנב העגל שאינה מגעת לערקוב, \u0003תנא\u0004 \u0005[שנה החכם]:\u0006 ערקוב ששנינו הריהו \u0003קפץ\u0004 (פרק) \u0003העליון,\u0004 שבין עצם הירך לעצם האמצעית, \u0003ולא קפץ התחתון,\u0004 שבין העצם האמצעית לתחתונה. \u0003ו\u0004ערקוב זה ששנינו, שהוא קפץ העליון — \u0003כנגדו בגמל ניכר,\u0004 שבגמל הוא בולט, ובעגל אינו ניכר כלפי חוץ.","\u0003על אלו מומין\u0004 ששנינו במשניות הקודמות שבפרק זה, \u0003שוחטין את הבכור\u0004 מחוץ למקדש, \u0003ופסולי המוקדשין\u0004 (שאר קדשים, שאינם בכור, שנפל בהם מום) \u0003נפדין עליהן.\u0004","על מה ששנינו: על אלו מומין שוחטים את הבכור, תוהים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי? הא תנא ליה רישא\u0004 \u0005[הרי\u0006 כבר \u0005שנה\u0006 דבר \u0005זה בתחילה],\u0006 בפתיחת פרק זה: \u0003על אלו מומין שוחטין את הבכור!\u0004 ומשיבים: \u0003סיפא איצטריכא\u0004 \u0005[הסוף\u0006 של משנתנו \u0005הוצרך\u0006 לו\u0005],\u0006 מה שנאמר: \u0003פסולי המוקדשין נפדין עליהן.\u0004 ומקשים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט]!\u0006 שהרי אם \u0003מישחט שחטינן\u0004 \u0005[לשחוט\u0006 מחוץ למקדש \u0005אנו שוחטים]\u0006 את הבכור בגלל מום כזה, וכי \u0003מיפרק מיבעיא\u0004 \u0005[לפדות\u0006 בגללו בהמת קדשים \u0005נצרכה]\u0006 לומר שפודים?","\u0003אלא, איידי דתנא\u0004 \u0005[מתוך ש\u0006התנא \u0005שונה]\u0006 במשניות הקודמות: \u0003שלשה\u0004 מומים נוספים \u0003הוסיף\u0004 אילא לפני חכמים ביבנה, \u0003ואמרו לו\u0004 חכמים: \u0003לא שמענו את אלו, וקתני ואתי\u0004 \u0005[ו\u0006לאחר מכן התנא \u0005שונה והולך]\u0006 מומים נוספים בשמו \u0003דיחידאה\u0004 \u0005[של\u0006 חכם \u0005יחיד],\u0006 בשם ר' חנניא בן גמליאל ובשם ר' חנינא בן אנטיגנוס, אפשר היה לחשוב שנדחו מן ההלכה, \u0003ו\u0004לכן \u0003קא סתים לה בכולהו\u0004 \u0005[\u0006הוא \u0005סותם\u0006 במשנתנו \u0005ב\u0006יחס ל\u0005כולם]:\u0006 \u0003על אלו מומין שוחטין את הבכור ופסולי המוקדשין נפדין עליהן.\u0004","\u0003ואלו\u0004 מומים \u0003שאין שוחטין עליהן לא במקדש\u0004 — מפני שאינם ראויים להקרבה, ולא במדינה (מחוץ למקדש) — מפני שאינם מומים גמורים: \u0003חוורור\u0004 (טיפות לבנות) \u0003והמים\u0004 שבעין, שניהם במקרה \u0003שאין\u0004 הם \u0003קבועין. וחוטין\u0004 (חניכיים) \u0003הפנימיות שנפגמו, אבל לא שנעקרו. ובעל גרב\u0004 (מין שחין), \u0003ובעל יבלת, ובעל חזזית\u0004 (מין שחין). וכן אם היה \u0003זקן\u0004 או \u0003חולה\u0004 או \u0003מזוהם\u0004 (מסריח), \u0003ושנעבדה\u0004 (שנעשתה) \u0003בו עבירה,\u0004 שרבע אשה או שנרבע על ידי אדם, או \u0003שהמית אדם,\u0004 אלא שלא היו שני עדים בדבר, אלא הדבר ידוע \u0003על פי עד אחד, או על פי הבעלים.\u0004","\u0003ו\u0004כן בכור שנולד \u0003טומטום\u0004 (שסימני המין שלו מכוסים) \u0003ואנדרוגינוס\u0004 (שיש בו איברי זכר ונקבה כאחד), \u0003לא\u0004 שוחטין \u0003במקדש ולא במדינה. ר' ישמעאל אומר: אין לך מום גדול מזה,\u0004 מאנדרוגינוס, ומותר לשוחטו במדינה. \u0003וחכמים אומרים: אינו בכור,\u0004 אין קדושת בכורה חלה עליו, מפני שאינו נחשב לזכר, \u0003אלא נגזז ונעבד,\u0004 כדין בהמת חולין.","שנינו במשנה כי גרב וילפת, שהם שני מיני שחין, אינם בכלל המומים הגמורים, ששוחטים עליהם את הבכור מחוץ למקדש. ושואלים: \u0003וגרב לא\u0004 נחשב מום? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003גרב באורייתא\u0004 \u0005[בתורה]\u0006 ברשימת בעלי המומים (ויקרא כב, כב)! ועוד, \u0003וחזזית לא\u0004 מום היא? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003ילפת באורייתא\u0004 \u0005[בתורה]\u0006 (ויקרא כב, כב), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"גרב\"\u0004 האמור בתורה — \u0003זה החרס, \"ילפת\"\u0004 — \u0003זו חזזית המצרית, ואמר ריש לקיש: למה נקרא שמה\u0004 של חזזית זו בתורה \u0003\"ילפת\"\u0004 — \u0003שמלפפת\u0004 (אוחזת) \u0003והולכת\u0004 ואינה מרפה מן החולה \u0003עד יום המיתה,\u0004 שאין לה תרופה. הרי שחזזית היא מום גמור!","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 מ\u0003חזזית\u0004 על \u0003חזזית לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003כאן,\u0004 בתורה — מדובר \u0003בחזזית המצרית, כאן\u0004 במשנה — \u0003בחזזית דעלמא\u0004 \u0005[סתם].\u0006 \u0003אלא\u0004 מ\u0003גרב\u0004 על \u0003גרב קשיא\u0004 \u0005[קשה]!\u0006 ומשיבים: \u0003גרב\u0004 על \u0003גרב נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה\u0006 שבמשנה\u0005]\u0006 מדובר \u0003בלח, הא\u0004 \u0005[זה\u0006 שבתורה\u0005]\u0006 — \u0003ביבש.\u0004 ומפרשים: אם היה \u0003לח\u0004 — \u0003איתסי\u0004 \u0005[\u0006הוא \u0005מתרפא],\u0006 והואיל והוא מום עובר — אין שוחטים עליו, אבל \u0003יבש\u0004 שנזכר בתורה — \u0003לא מיתסי\u0004 \u0005[אינו מתרפא].\u0006","ושואלים: \u0003ו\u0004האם גרב \u0003לח מיתסי\u0004 \u0005[מתרפא]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בפרשת הקללות: \u0003\"יככה ה' בשחין מצרים...\u0004 ובגרב ובחרס אשר לא תוכל להרפא\" (דברים כח, כז), \u0003ומדכתיב\u0004 \u0005[ומכיון שנאמר]\u0006 \u0003\"ובחרס\",\u0004 שהוא שחין יבש כחרס, \u0003הרי \"גרב\"\u0004 שהוזכר בצידו — שחין לח אמור, וקאמר \u0005[ו\u0006הכתוב \u0005אומר]\u0006 על שניהם \u0003\"אשר לא תוכל להרפא\"!\u0004","\u0003אלא, תלתא הוו\u0004 \u0005[שלושה\u0006 מיני גרב \u0005הם]:\u0006 גרב \u0003דקרא\u0004 \u0005[של הכתוב]\u0006 בענין מומים — הריהו \u0003יבש בין מבפנים בין מבחוץ,\u0004 ואינו נרפא (והוא הקרוי \"חרס\" בפרשת הקללות). גרב \u0003דמתניתין\u0004 \u0005[ש\u0006מדובר בו \u0005במשנתנו],\u0006 שהוא יכול להירפא — \u0003לח מבחוץ ומבפנים.\u0004 גרב של \u0003מצרים,\u0004 שהוזכר בפרשת הקללות כאחד ממיני שחין מצרים — \u0003יבש מבפנים,\u0004 ולכן אינו נרפא, \u0003ו\u0004אולם \u0003לח מבחוץ, דכתיב\u0004 \u0005[שנאמר]\u0006 במכת השחין: \u0003\"ויהי שחין פורח אבעבועות באדם\u0004 ובבהמה\" (שמות ט, ט), ואבעבועות לחות הן.","שנינו במשנה שיש דברים שאינם בגדר מום, אולם אסור להקריבם: \u0003והזקן והחולה והמזוהם.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאין להקריבם? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר לגבי קרבן עולה: \"ואם \u0003מן הצאן\u0004 קרבנו \u0003מן הכשבים\u0004 או \u0003מן העזים\"\u0004 (ויקרא א, י), והמלה \"מן\" שהיא לשון מיעוט, נאמרה שלוש פעמים בפסוק זה — \u0003פרט לזקן ולחולה ולמזוהם.\u0004","ומעירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 כולם להיכתב, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו\u0006 היתה \u0005כותבת התורה]\u0006 רק מיעוט אחד, הייתי אומר: הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003זקן, דלא הדר בריא\u0004 \u0005[שאינו חוזר ומבריא],\u0006 שהרי לעולם לא ייעשה צעיר, \u0003אבל חולה, דהדר בריא\u0004 \u0005[ש\u0006הוא \u0005חוזר ומבריא]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייפסל להקרבה. \u0003ו\u0004או, מצד אחר, \u0003אי כתב\u0004 \u0005[אם היתה\u0006 התורה \u0005כותבת]\u0006 מיעוט אחד, הייתי אומר שהוא בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חולה,\u0004 ודווקא הוא פסול להקרבה משום \u0003דלאו אורחיה\u0004 \u0005[שאין זה דרכו]\u0006 של בעל חיים. \u0003אבל זקן, דהיינו אורחיה\u0004 \u0005[שזה דרכו]\u0006 של בעל חיים, שהוא מזקין והולך — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה פסול.","\u0003ואי כתב רחמנא תרי\u0004 \u0005[ואם היתה כותבת התורה שנים],\u0006 רק שני מיעוטים, הייתי אומר שבאו \u0003למעוטי הני דכחישי\u0004 \u0005[למעט את אלה שהם כחושים],\u0006 חולה וזקן, מפני שאין מביאים לקרבן אלא בעל חיים שמן ובריא. \u0003אבל מזוהם, דלא כחיש\u0004 \u0005[שאינו כחוש]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה פסול. \u0003ואי נמי\u0004 \u0005[ואם גם כן],\u0006 אם היה מיעוט אחד, הייתי אומר כי בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מזוהם, משום דמאיס\u0004 \u0005[ש\u0006הוא \u0005מאוס],\u0006 \u0003אבל הני דלא מאיסי\u0004 \u0005[אלה,\u0006 חולה וזקן, \u0005שאינם מאוסים]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכן \u0003צריכי\u0004 \u0005[צריכים]\u0006 כל המיעוטים כולם.","ועוד שנינו במשנה: \u0003ושנעבדה בו עבירה\u0004 ושהמית את האדם על פי עד אחד או על פי הבעלים — פסולים להקרבה. ומסבירים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר ביחס לקרבן עולה \"מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\" (ויקרא א, ב), ודורשים לשון \"מן\" שהוא בא למעט: \u0003\"מן הבהמה\"\u0004 — מיעוט זה בא \u0003להוציא רובע\u0004 אדם, \u0003ונרבע\u0004 על ידי אדם, שפסול להקרבה, \u0003\"מן הבקר\"\u0004 — \u0003להוציא את הנעבד\u0004 כעבודה זרה, \u0003\"מן הצאן\"\u0004 — \u0003להוציא את המוקצה\u0004 שהופרש לשם עבודה זרה, \u0003\"ומן הצאן\"\u0004 בוא\"ו יתירה — \u0003להוציא את הנוגח,\u0004 שהרג נפש.","ומקשים: הלא \u0003הני\u0004 \u0005[אלה],\u0006 הרובע והנרבע והנוגח, \u0003בני קטלא נינהו\u0004 \u0005[בני מיתה הם],\u0006 שדינם סקילה, ומה מקום לדון אם הם כשרים להקרבה? ומשיבים: מדובר כאשר נעשתה העבירה \u0003על פי עד אחד או על פי הבעלים,\u0004 שאין ממיתים אותם, כיון שאין שני עדים, אבל די בכך כדי לפוסלם.","ועוד שנינו במשנה: הטומטום והאנדרוגינוס אין שוחטים אותם, לא במקדש, ולא במדינה. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003טומטום במקדש לא\u0004 יישחט כבכור — \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003נקבה היא,\u0004 ואין זה בכור, וממילא הרי זו בהמת חולין, שאסור להביאה למקדש. וכן \u0003במדינה לא\u0004 יישחט — \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003זכר הוא\u0004 ובכור, \u0003ולית בה מומא\u0004 \u0005[ו\u0006הרי \u0005אין בו מום],\u0006 ונמצא שוחט קדשים בחוץ.","\u0003אלא אנדרוגינוס, בשלמא\u0004 \u0005[נניח,\u0006 מובן\u0005]\u0006 מדוע \u0003במקדש לא\u0004 מביאים אותו לקרבן — \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003נקבה היא. אלא במדינה\u0004 מדוע לא יישחט? \u0003נמי נהי\u0004 \u0005[גם אם]\u0006 נניח ש\u0003זכר הוא\u0004 — \u0003תעשה\u0004 איבר \u0003נקבות\u0004 שיש בו, כמו שיש \u0003חריץ\u0004 בבשרו, \u0003וישחוט עלה\u0004 \u0005[עליה],\u0006 כדין \"חרוץ\", שהוא אחד מבעלי המומים (ויקרא כב, כב)!","\u0003אמר אביי: אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין זה: \u0003\"או חרוץ או שבור\"\u0004 (ויקרא כב, כב), ומסמיכות שני המומים יש ללמוד כי \u0003חרוץ\u0004 שנאמר בכתוב הריהו \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שבור, מה שבור\u0004 הריהו \u0003במקום עצם,\u0004 שהרי אין שבר אלא בעצם ולא בבשר — \u0003אף חרוץ\u0004 מדובר \u0003במקום עצם,\u0004 ולא באיבר הנקבות, שהוא בבשר.","\u0003רבא אמר: בלא\u0004 ההשוואה ל\u0003שבור נמי\u0004 \u0005[גם כן],\u0006 \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר]\u0006 ש\u0003חרוץ במקום בשר הוי מומא\u0004 \u0005[הריהו מום].\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 \u0003הוי מומא\u0004 \u0005[\u0006ש\u0005הרי זה מום],\u0006 והלא \u0003כיון\u0004 ש\u0003אמר\u0004 החכם בברייתא: \u0003\"גרב\",\u0004 שהוזכר בפסוק זה כאחד מן המומים, \u0003זהו חרס,\u0004 אחד ממיני השחין — נמצא שגרב \u0003מיחרץ חריץ\u0004 \u0005[חרוץ\u0006 הוא\u0005]\u0006 בבשר, וכמו \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בנגעי העור: \u0003\"ומראהו עמוק מן העור\"\u0004 (ויקרא יג, ל), \u0003כמראה חמה העמוקה מן הצל. ו\u0004אם כן","\u0003ליכתב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 ברשימת המומים רק \u0003חרוץ ולא בעי\u0004 \u0005[צריך\u0006 לומר\u0005]\u0006 \u0003גרב, ואמינא\u0004 \u0005[והייתי אומר\u0006 כך\u0005]:\u0006 אם \u0003חרוץ\u0004 סתם, \u0003דלא מאיס\u0004 \u0005[שאינו מאוס]\u0006 — \u0003הוי מומא\u0004 \u0005[הרי הוא מום],\u0006 \u0003גרב דמאיס\u0004 \u0005[שהוא\u0006 גם \u0005מאוס]\u0006 \u0003לא כל שכן?\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003גרב,\u0004 שיש בו מיאוס — \u0003למימר\u0004 \u0005[\u0006כדי \u0005לומר]\u0006 שסתם \u0003חרוץ במקום בשר\u0004 — \u0003לא הוי מומא\u0004 \u0005[אינו מום].\u0006 ואם כן, אין לומר שסימן של נקבות שבאנדרוגינוס ייחשב למום, לשחוט בגללו את הבכור מחוץ למקדש.","ובהקשר זה מפרשים את מה ש\u0003רבי ישמעאל אומר\u0004 במשנה ביחס לאנדרוגינוס: \u0003אין לך מום גדול מזה,\u0004 ומכאן שהוא מבין שלסימן נקבות יש דין \"חרוץ\". ומסבירים: \u0003כאביי לא אמר\u0004 ר' ישמעאל, משום שהוא סבור ש\u0003חרוץ דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שבור לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 אלא כל אחד הוא מום לעצמו, ו\"חרוץ\" בבשר גם הוא מום.","\u0003כרבא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמר\u0004 ר' ישמעאל, מפני שיש לומר: \u0003דילמא\u0004 \u0005[שמא]\u0006 מה שלמדנו מ\"גרב\" שחרוץ במקום בשר אינו מום — הרי זה דוקא \u0003היכא דלא מינכרא\u0004 \u0005[במקום שאינו ניכר,\u0006 בולט\u0005],\u0006 \u0003אבל היכא דמינכר\u0004 \u0005[במקום שהוא ניכר],\u0006 כגון סימן נקבות, שהדבר גלוי לעין — \u0003\"מום רע\" קרינא ביה\u0004 \u0005[קוראים אנו בו],\u0006 (ראה דברים טו, כא), והוא נפסל להקרבה."],["ודנים בדבריו של ר' ישמעאל במשנתנו ביחס לאנדרוגינוס, ש\"אין לך מום גדול מזה\". \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל?\u0004 האם \u0003מיפשט פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 ש\u0003אנדרוגינוס בכור הוא,\u0004 שהוא זכר וקדוש בבכורה, \u0003ומומו עמו,\u0004 סימני הנקבות. ולכן מותר לשוחטו מחוץ למקדש. \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003ספוקי מספקא ליה\u0004 \u0005[מסופק לו]\u0006 אם הוא נחשב זכר, \u0003ו\u0004בדרך \u0003\"אם תימצא לומר\" קאמר\u0004 \u0005[הוא אומר]:\u0006 גם \u0003אם תימצא לומר\u0004 שאנדרוגינוס \u0003בכור הוא\u0004 — \u0003הרי מומו עמו,\u0004 ומותר לשוחטו מחוץ למקדש.","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכך]\u0006 אם כך או כך הוא הטעם? \u0003למילקא עליה\u0004 \u0005[ללקות עליו]\u0006 ארבעים מלקות \u0003משום גיזה ועבודה,\u0004 שאם ודאי בכור הוא — צריך לנהוג בו קדושת בכור, ומצות \"לא תעשה\" לגוזזו ולעבוד בו (דברים טו, יט). אבל אם ספק הוא, הרי אף שאסור הדבר — אינו לוקה מספק. \u0003אי נמי\u0004 \u0005[או גם כן\u0006 יש לכך השלכה\u0005]\u0006 \u0003למיתבה\u0004 \u0005[\u0006לענין \u0005לתת אותו]\u0006 \u0003לכהן,\u0004 שאם ספק הוא — אין הכהן יכול לתובעו ממנו, מפני שהמוציא מחבירו — עליו הראיה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003ר' אילעאי אומר משום\u0004 (בשם) \u0003ר' ישמעאל: אנדרוגינוס בכור הוא ומומו עמו. שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מיפשט פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שאנדרוגינוס הריהו בכור. ואומרים: מכאן אין ראיה, \u0003ודילמא\u0004 \u0005[ושמא]\u0006 גם בברייתא זו, בלשון \u0003\"אם תימצא לומר\" קאמר\u0004 \u0005[הוא אומר],\u0006 שאם בכור הוא — הרי מומו עמו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: נאמר לענין קרבן עולה מן הבקר \u0003\"זכר\"\u0004 (ויקרא א, ג), ויש לדייק: זכר — \u0003ולא נקבה. כשהוא אומר למטה\u0004 בפרשה שאחר כך \u0003\"זכר\"\u0004 (ויקרא א, יא), לגבי עולה מן הצאן, הרי זה דבר \u0003שאין תלמוד\u0004 (צורך) \u0003לומר,\u0004 שהרי כבר נאמר \"זכר\" פעם אחת בענין עולה, והכתוב הקיש עולה מן הצאן לעולה מן הבקר. \u0003מה תלמוד לומר,\u0004 איפוא, שוב \"זכר\" — \u0003להוציא טומטום ואנדרוגינוס,\u0004 שאינם כשרים לעולה.","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 ברייתא זו\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 במשנתנו, שאמר שטומטום ואנדרוגינוס אינם נשחטים במקדש, אבל גם לא במדינה — אין לומר כן, שהלא לדעתו אנדרוגינוס \u0003ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא,\u0004 שאין אנו יודעים אם הוא נחשב זכר או לא. \u0003ו\u0004כי \u0003אתי קרא למעוטי ספיקא\u0004 \u0005[בא הכתוב למעט ספק]? אלא\u0006","תאמר שברייתא זו היא כדעת \u0003רבנן בתראי\u0004 \u0005[החכמים האחרונים]\u0006 שבמשנתנו, האומרים שאנדרוגינוס בוודאי אינו זכר, אלא הוא בריה בפני עצמה, והוצרך הכתוב למעטו מהקרבה. אבל גם דבר זה לא ניתן להיאמר, שהרי לדעתם, גם נקבה וגם טומטום ואנדרוגינוס \u0003מחד קרא נפקי\u0004 \u0005[מכתוב אחד\u0006 בלבד \u0005הם באים,\u0006 נלמדים\u0005],\u0006 \u0003דהא גבי\u0004 \u0005[שהרי אצל]\u0006 \u0003בכור חד \"זכר\" הוא דכתיב\u0004 \u0005[פעם אחת \"זכר\" הוא שנאמר],\u0006 ועל ידו \u0003קא מעטי כולהו מינייהו\u0004 \u0005[ממעטים את כולם].\u0006 ואילו בברייתא זו ממעטים נקבה מ\"זכר\" אחד, וטומטום ואנדרוגינוס מ\"זכר\" שני!","\u0003אלא, פשיטא\u0004 \u0005[פשוט]\u0006 שברייתא זו היא שיטת \u0003ר' ישמעאל. ו\u0004מעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003ר' ישמעאל מיפשט פשיטא ליה\u0004 \u0005[פשוט לו\u0006 הדבר\u0005],\u0006 שאנדרוגינוס הריהו בכור זכר — \u0003היינו דאיצטריך קרא למעוטי\u0004 \u0005[זהו שהוצרך הכתוב\u0006 בעניין קרבן עולה \u0005למעט],\u0006 ולומר שאין מביאים ממנו קרבן עולה. \u0003אלא אי אמרת מספקא ליה\u0004 \u0005[אם אתה אומר\u0006 ש\u0005מסופק לו]\u0006 אם הוא זכר — וכי \u0003אצטריך קרא למעוטי ספיקא\u0004 \u0005[הוצרך הכתוב\u0006 בעולה \u0005למעט ספק]?\u0006","ודוחים: \u0003לעולם\u0004 תאמר שברייתא זו היא כשיטת \u0003רבנן בתראי\u0004 \u0005[חכמים האחרונים],\u0006 הסבורים שאנדרוגינוס כלל אינו זכר, אלא בריה בפני עצמה. \u0003ו\u0004ביחס למה שהקשינו: והרי לשיטתם די בכתוב אחד למעט נקבה וגם טומטום ואנדרוגינוס, כפי שהוא בבכור — על כך יש להשיב: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בכור\u0004 גם כן \u0003תרתי קראי כתיב\u0004 \u0005[שני מקראות כתובים]:\u0006 \u0003\"הזכר\"\u0004 (דברים טו, יט) \u0003ו\"הזכרים\"\u0004 (שמות יג, יב), אחד למעט נקבה, ואחד למעט טומטום ואנדרוגינוס.","שנינו במשנה, \u0003וחכמים אומרים: אינו בכור,\u0004 אלא נגזז ונעבד, כדין בהמת חולין. \u0003אמר רב חסדא: מחלוקת\u0004 זו היא \u0003באנדרוגינוס,\u0004 שיש בו סימני זכר וסימני נקבה, וחכמים אלו אומרים שאנדרוגינוס בודאי אינו זכר, אלא בריה בפני עצמה, ולכן אינו קדוש בבכורה. \u0003אבל בטומטום,\u0004 שעורו מכסה את איברי מינו — \u0003דברי הכל ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא,\u0004 מפני שהוא זכר גמור או נקבה גמורה, אלא שאנו לא יודעים מהו. \u0003ו\u0004לכן הוא \u0003קדוש מספיקא\u0004 \u0005[מספק],\u0006 שאינו נשחט לא במקדש ולא במדינה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אלא מעתה,\u0004 לדבריך שהוא בודאי זכר או נקבה, אם כן \u0003בערכין,\u0004 כשאדם נודר ערכו של אדם טומטום — \u0003יערך,\u0004 אם בערך איש או בערך אשה!"],["\u0003אלמה תניא\u0004 \u0005[מפני מה שנינו\u0006 בברייתא\u0005]:\u0006 הכתוב \"והיה ערכך \u0003הזכר\"\u0004 (ויקרא כז, ג) בא למעט — \u0003ולא טומטום ואנדרוגינוס?\u0004 ומשיבים: \u0003סמי\u0004 \u0005[מחק]\u0006 \u0003מיכן\u0004 מגרסת הברייתא את המלה \u0003טומטום,\u0004 וכל הדרשה נאמרה עבור אנדרוגינוס, מפני שהוא בריה בפני עצמה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מהמשכה של ברייתא זו: \u0003יכול לא יהא\u0004 טומטום נערך \u0003בערך איש, אבל יהא\u0004 נערך \u0003בערך אשה? תלמוד לומר:\u0004 \"והיה ערכך \u0003הזכר...\u0004 ו\u0003אם נקבה\u0004 היא\" (ויקרא כז, ג—ד), כלומר, זכר או נקבה, \u0003ולא טומטום ואנדרוגינוס,\u0004 שאינם לא זכר ולא נקבה! ואומרים: \u0003סמי\u0004 \u0005[מחק]\u0006 גם \u0003מיכן טומטום,\u0004 וכל הדרשה היא לגבי אנדרוגינוס.","ועוד מציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בענין קרבן שלמים: \u0003\"אם זכר אם נקבה\"\u0004 (ויקרא ג, א) — \u0003זכר ודאי נקבה ודאית, ולא טומטום ואנדרוגינוס,\u0004 שבוודאי אינם לא זכר ולא נקבה! ומשיבים: \u0003סמי\u0004 \u0005[מחק]\u0006 גם \u0003מיכן טומטום.\u0004","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: נאמר לגבי קרבן עולה מן הבקר: \u0003\"הזכר\"\u0004 (ויקרא א, ג), ומכאן למדנו — \u0003ולא נקבה. כשהוא אומר למטה\u0004 בפרשה הבאה, לגבי עולה מן הצאן: \u0003\"זכר\"\u0004 (ויקרא א, יא) — הרי זה דבר \u0003שאין תלמוד\u0004 (צריך) \u0003לומר,\u0004 שהרי הכתוב הקיש עולה מן הצאן לעולה מן הבקר. אם כן \u0003מה תלמוד לומר\u0004 שוב \"זכר\" — \u0003להוציא טומטום ואנדרוגינוס!\u0004 ואומרים: \u0003סמי\u0004 \u0005[מחק]\u0006 גם \u0003מיכן טומטום.\u0004","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת: כל עוף שלא נשחט כראוי (מן הצואר, ובסכין) הריהו נבלת העוף, שמטמאת את האדם האוכל אותה, כשהיא נמצאת בבית הבליעה שלו. חוץ מקרבנות העוף, שדינם במליקה (מן העורף, ובצפורן), ומליקתם מטהרתם. ובענין זה שנינו: עוף שהוא פסול להקרבה, כגון \u0003הנעבד\u0004 כעבודה זרה, \u0003והמוקצה\u0004 (שהופרש לצורך עבודה זרה), \u0003והאתנן\u0004 (שניתן לזונה כאתנן), \u0003והמחיר\u0004 (מחיר כלב), וטומטום ואנדרוגינוס, הואיל והם פסולים לקרבן — אין מליקתם מטהרתם, ולכן \u0003כולן מטמאין בגדים\u0004 שעל האדם האוכל אותם, כשכזית מהם מצוי ב\u0003בית הבליעה\u0004 שלו.","\u0003ר' אליעזר אומר: טומטום ואנדרוגינוס\u0004 שנמלקו \u0003אין מטמאין בגדים אבית הבליעה,\u0004 מפני שהם כשרים להקרבה. \u0003שהיה ר' אליעזר אומר: כל מקום\u0004 בתורה \u0003שנאמר\u0004 בו במפורש \u0003זכר ונקבה,\u0004 כגון בקרבן מן הבהמה — \u0003אתה מוציא טומטום ואנדרוגינוס מביניהם,\u0004 שהוא פסול, מפני שאינו זכר ולא נקבה.","\u0003ו\u0004קרבן ה\u0003עוף, הואיל ולא נאמר בו זכר ונקבה,\u0004 אלא בסתם — תורים או בני יונה — אלא כשרים הם להקרבה. ואם לדעת התנא הראשון טומטום הוא ספק זכר או נקבה — מדוע הוא פסול להקרבה? והלא קרבן העוף כשר בין אם הוא זכר ובין אם הוא נקבה! ומשיבים: \u0003סמי\u0004 \u0005[מחק]\u0006 גם \u0003מיכן טומטום.\u0004","ומציעים \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו, \u0003ר' אלעזר אומר: הטריפה והכלאים ויוצא דופן\u0004 (שנולד בניתוח דרך דופן הבטן), \u0003טומטום ואנדרוגינוס\u0004 — \u0003לא קדושים ולא מקדישין.\u0004","\u0003ואמר שמואל\u0004 כהסבר לזה: \u0003לא קדושים\u0004 — \u0003בתמורה,\u0004 שאם אמר על אחד מהם שיהא תמורת בהמת קדשים — אינו מתקדש, \u0003ולא מקדישין\u0004 — \u0003לעשות תמורה,\u0004 שאם הוא קדוש בקדושת קרבן, כגון שנולדו לבהמת קדשים, ואמר על בהמת חולין שהיא תמורתו — אין היא קדושה. ואם טומטום הוא ספק זכר או נקבה — מדוע אינו קדוש? והרי בין זכר ובין נקבה קדושים ומקדישים! ומשיבים: \u0003סמי\u0004 \u0005[מחק]\u0006 גם \u0003מיכן טומטום.\u0004","ומציעים \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה מנוסח שונה מעט של ברייתא זו, \u0003ר' אלעזר אומר: חמשה לא קדושים ולא מקדישין, ואלו הן: הטריפה, והכלאים, ויוצא דופן, וטומטום, ואנדרוגינוס. וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003סמי\u0004 \u0005[מחק]\u0006 \u0003מיכן טומטום\u0004 — אם כן \u0003הוו להו\u0004 \u0005[הרי הם]\u0006 \u0003ארבעה,\u0004 ולא חמישה! ומשיבים: \u0003אפיק\u0004 \u0005[הוצא]\u0006 \u0003טומטום\u0004 מהרשימה, \u0003ועייל\u0004 \u0005[והכנס]\u0006 \u0003יתום,\u0004 ולד שנולד לאחר מות אימו, שאף הוא פסול לקרבן.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 ששאלה זו, האם טומטום הוא קדוש מספק, או בריה בפני עצמה, שנויה \u0005כ\u0006מחלוקת \u0005תנאים]?\u0006 שכך שנינו בברייתא: \u0003ר' אילעאי אומר משום\u0004 (בשם) \u0003ר' ישמעאל: אנדרוגינוס בכור\u0004 וזכר \u0003הוא ומומו עמו. וחכמים אומרים: אין קדושה חלה עליו\u0004 כלל, שאינו זכר, אלא בריה בפני עצמה. \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: הרי הוא אומר\u0004 בענין בכור בהמה \u0003\"הזכר\u0004 תקדיש\" (דברים טו, יט), \u0003וכל מקום שנאמר \"זכר\" אינו אלא להוציא\u0004 (למעט) \u0003טומטום ואנדרוגינוס.\u0004 הרי שלדעת ר' שמעון בן יהודה הוצרך הכתוב למעט טומטום מ\"זכר\", כמו אנדרוגינוס. ואם כן, לדעתו אינו ספק זכר, אלא בריה בפני עצמה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003סמי\u0004 \u0005[מחק]\u0006 גם \u0003מיכן טומטום\u0004 מדברי ר' שמעון בן יהודה — אינך יכול לומר כן, שאם כן שיטת \u0003ר' שמעון בן יהודה היינו רבנן\u0004 \u0005[הרי זו\u0006 שיטת \u0005חכמים],\u0006 שגם הם סבורים שאנדרוגינוס אינו קדוש! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 בענין \u0003טומטום איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003דתנא קמא סבר\u0004 \u0005[שהתנא הראשון,\u0006 חכמים, \u0005סבור]:\u0006 \u0003אין קדושה חלה עליו\u0004 כלל — על \u0003אנדרוגינוס\u0004 שהוזכר מתחילה בדברי ר' אילעי, \u0003אבל טומטום\u0004 — \u0003ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא, וקדוש מספיקא\u0004 \u0005[מן הספק].\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' שמעון\u0004"],["\u0003בן יהודה למימר\u0004 \u0005[לומר]\u0006 כי \u0003טומטום\u0004 אינו בגדר ספק זכר, אלא \u0003בריה\u0004 בפני עצמה \u0003הוא, ולא קדוש\u0004 כלל! ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003טומטום בבריה\u0004 בפני עצמה \u0003לא מספקא\u0004 \u0005[אין להסתפק\u0006 בו\u0005],\u0006 שאין מי שסבור שהוא בריה. אלא \u0003זכר ונקבה הוא דמספקא\u0004 \u0005[שיש להסתפק\u0006 בו\u0005],\u0006 שמא זכר הוא או נקבה.","ואם היה הטומטום \u0003מטיל מים במקום\u0004 שמצוי פי איבר ה\u0003זכרות\u0004 בזכר — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003זכר הוא. כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003במטיל מים במקום נקבות,\u0004 שהמים יוצאים במקום בו נקבה מטילה מימיה, מאחוריה, \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, חכמים, \u0005סבור]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא נהפכה\u0004 איבר \u0003זכרותו ל\u0004מקום \u0003נקבותו,\u0004 כלומר, לאחוריו, ומשם הוא מטיל מים. ודינו, איפוא, כספק. \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה, ר' שמעון בר' יהודה, \u0005סבור]:\u0006 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 אלא בוודאי נקבה הוא. וסבור ר' שמעון בר' יהודה \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003הורה ר' אלעזר:\u0004 בכור טומטום \u0003בבהמה,\u0004 אם \u0003מטיל מים במקום נקבות\u0004 — הרי הוא \u0003חולין,\u0004 משום שבוודאי נקבה הוא.","בענין הוראתו של ר' אלעזר, שטומטום המטיל מים במקום נקבות — חולין הוא, ואינו ספק זכר בכור, מסופר, \u0003תהי בה\u0004 \u0005[תוהה\u0006 היה \u0005בכך]\u0006 \u0003ר' יוחנן: מאן דלא חש\u0004 \u0005[מי\u0006 הוא זה \u0005שאינו חושש]\u0006 \u0003ל\u0004דעת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 במשנתנו, \u0003ול\u0004דעת \u0003ר' ישמעאל,\u0004 הסבורים שטומטום ספק הוא! ושואלים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 \u0003ר' יוחנן נמי\u0004 \u0005[גם כן]:\u0006 \u0003מאן דלא חש לרבנן בתראי\u0004 \u0005[מי\u0006 הוא זה \u0005שאינו חושש לדעת חכמים האחרונים]\u0006 במשנה. שהרי \u0003אמר רב חסדא: מחלוקת\u0004 — \u0003באנדרוגינוס,\u0004 שהחכמים האחרונים סבורים שאינו ספק זכר, אלא בריה בפני עצמה הוא, \u0003אבל בטומטום\u0004 — \u0003דברי הכל ספיקא\u0004 \u0005[ספק]\u0006 זכר או נקבה הוא, וקדוש מספק!","ומשיבים: \u0003ר' יוחנן לא סבירא ליה\u0004 \u0005[אינו סבור]\u0006 כ\u0003רב חסדא,\u0004 ולדעתו סבורים החכמים האחרונים שטומטום בוודאי אינו בכור, אלא בריה בפני עצמה. ומקשים: \u0003אי לא סבירא ליה\u0004 \u0005[אם\u0006 ר' יוחנן \u0005אינו סבור\u0006 כן\u0005],\u0006 מדוע תמה על הוראתו של ר' אלעזר? \u0003לימא\u0004 \u0005[נאמר]\u0006 שר' אלעזר \u0003הוא\u0004 ש\u0003אמר כרבנן בתראי\u0004 \u0005[כדעת חכמים אחרונים]!\u0006 ומשיבים: באמת, \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן\u0006 הוא \u0005אומר],\u0006 לזאת כוונתו: \u0003מאן שביק תרי ועביד כחד\u0004 \u0005[מיהו זה שמניח\u0006 דעת \u0005שנים,\u0006 שני חכמים, התנא הראשון ור' ישמעאל, \u0005ועושה כ\u0006דעת חכם \u0005אחד,\u0006 החכמים האחרונים\u0005]!\u0006","ומעירים: \u0003ור' אלעזר כמאן סברא\u0004 \u0005[כמי הוא סבור]\u0006 — \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר ריש לקיש: לא אמרו\u0004 ב\u0003טומטום\u0004 שהוא \u0003ספק אלא באדם, הואיל וזכרותו ונקבותו במקום אחד,\u0004 שמי הרגלים של איש ואשה יוצאים באותו מקום בגוף. והואיל והוא מכוסה — הרי זה ספק. \u0003אבל\u0004 טומטום \u0003בהמה,\u0004 שזכרותה ונקבותה מצויים במקומות שונים — אין בו ספק אם הוא זכר או נקבה, אלא אם \u0003מטיל מים במקום זכרות\u0004 — הרי הוא \u0003זכר, מטיל מים במקום נקבות\u0004 — \u0003נקבה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אושעיא:\u0004 גם אם הוא מטיל מים במקום נקבות — \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא נהפכה זכרותו\u0004 כלפי \u0003נקבותו,\u0004 ומשום כך הוא מטיל מים במקום נקבות, ואין זה יוצא מכלל ספק! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אתה אומר זאת, \u0003כ\u0004דעת \u0003ר' מאיר דחייש למיעוטא\u0004 \u0005[שחושש למיעוט]?\u0006 והרי אין הלכה כמותו. ואם כן יש ללכת אחר הרוב, שזכרותם אינה מתהפכת!","\u0003אביי בר אבין ורב חנניא בר אבין דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 הסבורים שבדרך כלל אין חוששים למיעוט — במקרה זה יש לחשוש, ולומר: \u0003הואיל ואישתני\u0004 \u0005[והשתנה]\u0006 בעל חיים זה מבעלי חיים רגילים, והוא טומטום — יש לחשוש כי גם בענין אחר \u0003אישתני\u0004 \u0005[השתנה],\u0006 שנהפכה זכרותו לנקבותו. ומעירים: נחלקו, איפוא, חכמים בעקרון זה, \u0003אית דאמר אישתני\u0004 \u0005[יש\u0006 מי \u0005שאומר\u0006 כי אומרים: הואיל והשתנה \u0005השתנה],\u0006 \u0003ואית דאמר לא אישתני\u0004 \u0005[ויש\u0006 מי \u0005שאומר\u0006 כי \u0005אין\u0006 אומרים: כיון שהשתנה \u0005השתנה].\u0006","ומציעים: \u0003לימא אישתני ולא אישתני תנאי\u0004 \u0005[האם לומר\u0006 שהמחלוקת בענין \u0005השתנה ולא השתנה\u0006 מחלוקת \u0005תנאים\u0006 היא\u0005]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003טומטום שקידש\u0004 אישה — \u0003קדושיו קדושין\u0004 מספק, שמא איש הוא. וכן אם \u0003נתקדש\u0004 כאשה על ידי איש — \u0003קדושיו קדושין\u0004 מספק, שמא אשה הוא.","\u0003ו\u0004אם מת אחיו בלא בנים, ואין שם אח אחר שיוכל ליבם אותה — \u0003חולץ,\u0004 כלומר, יבמתו חולצת את נעלו, שמא הוא זכר, והיא זקוקה לחליצה כדי להתירה מזיקתו. \u0003ו\u0004אם מת הטומטום — אחיו (אחד מהם) \u0003חולצין לאשתו\u0004 או \u0003מיבמים לאשתו,\u0004 שמא היה זכר. ותניא אידך \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אשת טומטום\u0004 — \u0003חולצת ולא מתייבמת.\u0004","ואומרים: \u0003סברוה\u0004 \u0005[סבורים\u0006 היו חכמים\u0005]\u0006 שהציעו דבר זה, \u0003דכולי עלמא\u0004 \u0005[שהכל,\u0006 בעלי שתי הברייתות, \u0005סבורים]\u0006 \u0003כ\u0004דעת \u0003ר' עקיבא,\u0004 ש\u0003אמר: סריס חמה,\u0004 שמטבע ברייתו אינו יכול להוליד — \u0003לא חולץ ולא מייבם\u0004 לאשת אחיו, מפני שאינו בכלל מצות יבום. וכן אחיו אינם חולצים ואינם רשאים ליבם את אשתו, משום שהיא אסורה עליהם כדין אשת אח שאינה זקוקה ליבום.","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה הם חלוקים],\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאומר]\u0006 שטומטום \u0003חולץ, ו\u0004אחיו \u0003חולצין לאשתו ומיבמים את אשתו,\u0004 סבור כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003הואיל ואישתני\u0004 \u0005[והשתנה]\u0006 מבני אדם רגילים, והוא טומטום — \u0003אישתני\u0004 \u0005[השתנה],\u0006 ויש לחשוש שמא היה סריס חמה, ואחיו אסורים ליבמה. אלא יש להניח שאם היה זכר — היה בר הולדה, ואשתו זקוקה ליבום.","\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שאשת טומטום \u0003חולצת ולא מתייבמת,\u0004 הרי זה משום שלדעתו \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003הואיל ואישתני אישתני\u0004 \u0005[והשתנה השתנה],\u0006 וגם אם היה זכר — שמא סריס חמה היה, ולכן אין מייבמים את אשתו?","ודוחים: \u0003לא, דכולי עלמא אמרינן\u0004 \u0005[לדעת הכל אומרים אנו]\u0006 \u0003הואיל ואישתני אישתני\u0004 \u0005[והשתנה השתנה],\u0006 ויש לחשוש שהיה סריס חמה. אלא \u0003הא\u0004 \u0005[זו],\u0006 הברייתא המתירה לייבם את אשתו — הריהי שיטת \u0003ר' אליעזר,\u0004 החולק על ר' עקיבא, וסבור כי אשת סריס חמה ראויה ליבום, \u0003והא\u0004 \u0005[וזו],\u0006 האוסרת — שיטת \u0003ר' עקיבא\u0004 היא, הסבור שאשת סריס חמה אינה ראויה ליבום.","ושואלים: \u0003ומאן תנא אליבא\u0004 \u0005[ומיהו התנא\u0006 ההולך \u0005לפי שיטתו]\u0006 של \u0003ר' עקיבא,\u0004 שאשת סריס חמה אינה זקוקה ליבום, ולמרות זאת לדעתו על אשת טומטום לחלוץ? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ר' יהודה\u0004 הוא, \u0003הא\u0004 \u0005[הרי]\u0006 לשיטתו, גם אם ייקרע ויימצא זכר — כדין \u0003ודאי סריס\u0004 (חמה) \u0003משוי ליה\u0004 \u0005[\u0006הוא \u0005עושה אותו],\u0006 ואינה זקוקה כלל לחליצה.","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: טומטום שנקרע ונמצא זכר\u0004 — \u0003הרי זה לא יחלוץ, מפני שהוא כסריס\u0004 חמה, ואין חליצתו חליצה. וכשם שסריס אינו חולץ — כך אלמנתו אינה זקוקה לחליצה!","אלא שיטת \u0003ר' יוסי בר' יהודה היא,\u0004 הסבור שטומטום שנקרע ונמצא זכר הריהו ספק סריס חמה, ולכן צריך לחלוץ לאשתו. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: טומטום לא חולץ\u0004 לאשת אחיו שמת, כשיש לו אחים נוספים — \u0003שמא יקרע\u0004 העור המכסה את איבריו \u0003וימצא סריס חמה,\u0004 ונמצא שלא הותרה היבמה בחליצה זו, אבל לשיטתו אין זה ודאי שיימצא סריס חמה. ולעצם דברי ר' יוסי בר' יהודה שואלים: ומדוע הוא תולה את האיסור לחלוץ רק באפשרות זו, שיימצא סריס חמה?","\u0003אטו כל דמיקרע\u0004 \u0005[וכי כל\u0006 טומטום \u0005שנקרע]\u0006 \u0003זכר משתכח\u0004 \u0005[נמצא],\u0006 \u0003נקבה לא משתכח\u0004 \u0005[אינו נמצא]?\u0006 והלא גם אם נקבה הוא — אין חליצתו מועילה להתיר את אשת אחיו! ומשיבים: בלשון \u0003שמא קאמר\u0004 \u0005[\u0006הוא \u0005אומר],\u0006 והוא כולל בכך יותר מספק אחד: \u0003שמא יקרע וימצא נקבה,\u0004","\u0003אי נמי\u0004 \u0005[\u0006ו\u0005אם גם כן]\u0006 \u0003זכר\u0004 הוא — \u0003נמי\u0004 \u0005[גם כן]\u0006 לא יחלוץ, \u0003שמא ימצא סריס חמה.\u0004 ושואלים: הואיל וגם ר' יהודה וגם ר' יוסי בר' יהודה אומרים שטומטום אינו חולץ ליבמתו, \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה? \u0003אמר רבא:\u0004"],["ההבדל ביניהם הוא לענין \u0003לפסול\u0004 בחליצתו את היבמה ליבום \u0003במקום\u0004 שיש \u0003אחים\u0004 נוספים; לדעת ר' יהודה, שהוא בוודאי סריס חמה — לא עשה בחליצתו כלום, והיא ראויה ליבום. ולדעת ר' יוסי בר' יהודה — שמא אינו סריס, וחליצתו חליצה, והיא אסורה איפוא על האחים כדין אשת אח. \u0003ו\u0004כן לענין \u0003לחלוץ\u0004 ליבמתו \u0003שלא במקום אחים,\u0004 כאשר הוא האח היחיד, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005];\u0006 לדעת ר' יהודה אין בכך צורך, שהרי אינה זקוקה כלל ליבום וחליצה שלו. ולדעת ר' יוסי בר' יהודה — צריך לחלוץ לה, שמא זכר הוא, ואינו סריס.","","","\u0003מומין אלו,\u0004 ששנינו ביחס לבכור בהמה, \u0003בין\u0004 שהם \u0003קבועין בין\u0004 שהם \u0003עוברים\u0004 — \u0003פוסלין באדם,\u0004 שאם היו בכהן הריהו פסול לעבודה. \u0003ויתר עליהן\u0004 על מומי בהמה, מומים נוספים שהם מיוחדים לאדם: \u0003הכילון והלפתן והמקבן,\u0004 שיש לראשם צורה משונה, \u0003ושראשו שקוט, וסקיפת\u0004 (שיבואר עניינם בגמרא).","\u0003ובעלי חטרות\u0004 (מעין בליטה בגב) — \u0003ר' יהודה מכשיר, וחכמים פוסלין. הקרח פסול. איזהו קרח\u0004 שהוא פסול? \u0003כל שאין לו שיטה\u0004 (שורה) \u0003של שער מוקפת,\u0004 מקיפה את ראשו \u0003מאוזן לאוזן, אם יש לו\u0004 — \u0003הרי זה כשר.\u0004","שנינו במשנה שמומים ששנינו לגבי בהמה בפרק הקודם — פוסלים גם באדם (כהן). ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 המומים הפוסלים בזה פוסלים גם בזה? \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003יבלת, דלא כתיב באורייתא\u0004 \u0005[שאינה כתובה בתורה]\u0006 \u0003באדם,\u0004 אלא רק בבהמה (ויקרא כב, כב)! \u0003ותו\u0004 \u0005[ועוד]\u0006 יש לשאול: \u0003דק תבלול, דלא כתיבי\u0004 \u0005[שאינם כתובים]\u0006 בתורה \u0003ב\u0004מומי ה\u0003בהמה,\u0004 אלא דווקא באדם (וי'קרא כא, כ), מדוע שנינו בפרק הקודם שהם פוסלים בבהמה?","ומשיבים: \u0003מילף ילפי מהדדי\u0004 \u0005[למדים הם זה מזה],\u0006 וכפי \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003באדם לא נאמר בו יבלת, בבהמה לא נאמר דק תבלול, מנין\u0004 אתה למד \u0003ליתן את האמור של זה בזה ואת האמור של זה בזה? תלמוד לומר\u0004 בשניהם: \u0003\"גרב\" \"גרב\"\u0004 (ויקרא כא, כ, וויקרא כב, כב), וכן \u0003\"ילפת\" \"ילפת\"\u0004 (ויקרא כא, כא, וויקרא כב, כב), וכתובים אלה באים \u0003ל\u0004למד מזה על זה ב\u0003גזירה שוה.\u0004","ומעירים: \u0003מפני\u0004 \u0005[מופנים]\u0006 הכתובים הללו, אינם נחוצים לגופם, ולא נאמרו אלא לגזירה שווה זו. \u0003דאי לא מפני איכא למיפרך\u0004 \u0005[שאם אינם מופנים יש\u0006 מקום \u0005לפרוך]\u0006 את ההשוואה ולומר כך: \u0003אדם\u0004 (כהן) \u0003מבהמה לא יליף\u0004 \u0005[אינו למד]\u0006 לפוסלו לעבודה באותם מומים שנזכרו בה, \u0003שכן\u0004 יש לבהמה חומרה יתירה, ש\u0003היא עצמה קריבה לגבי מזבח.\u0004 וכן מן הצד השני, \u0003בהמה מאדם לא ילפא\u0004 \u0005[אינה למדה],\u0006 \u0003שכן\u0004 האדם יש בו חומרה יתירה, ש\u0003נתרבה במצות.\u0004","\u0003לאיי\u0004 \u0005[משום כך]\u0006 צריכים לומר ש\u0003אפנויי מפני\u0004 \u0005[\u0006שהכתובים \u0005הללו מופנים]\u0006 לגזירה שווה. וכאילו נאמר הדבר במפורש בתורה, כך שלא ניתן להקשות על כך מסברה. ומנין שהם מופנים? \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"ילפת\"\u0004 במומי האדם ובמומי הבהמה, \u0003ולא בעי\u0004 \u0005[ולא צריך]\u0006 לכתוב \u0003\"גרב\",\u0004 לא כאן ולא כאן, \u0003ואנא אמינא\u0004 \u0005[ואני\u0006 הייתי \u0005אומר\u0006 מדעתי\u0005]:\u0006 \u0003ומה ילפת דלא מאיסא\u0004 \u0005[שאינה מאוסה]\u0006 \u0003הוי מומא\u0004 \u0005[הרי היא מום],\u0006 \u0003גרב דמאיס\u0004 \u0005[שהוא מאוס]\u0006 \u0003לא כל שכן\u0004 שהוא מום? אם כן, \u0003\"גרב\" \"גרב\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 גם באדם וגם בבהמה \u0003למה לי?\u0004 הרי זה \u0003לאפנויי\u0004 \u0005[להפנות אותם]\u0006 לצורך גזירה שווה.","ושואלים: אם המומים הפוסלים באדם פוסלים גם בבהמה, ולהיפך — \u0003ולכתבינהו רחמנא כולהו בחד\u0004 \u0005[ושתכתוב התורה את\u0006 כל המומים \u0005כולם ב\u0006מקום \u0005אחד],\u0006 באדם או בבהמה, \u0003ו\u0004תכתוב \u0003גרב וילפת הכא והכא\u0004 \u0005[כאן וכאן],\u0006 לצורך גזירה שווה, \u0003ולילפו מחדא\u0004 \u0005[וכך ילמדו\u0006 את כל שאר המומים \u0005מאחד]!\u0006","ומשיבים: \u0003אהייא בהי ליכתב רחמנא\u0004 \u0005[באיזה מהם שתכתוב התורה]\u0006 את המומים? \u0003אי כתב\u0004 \u0005[אם היתה\u0006 התורה \u0005כותבת]\u0006 \u0003באדם, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כל\u0004 ש\u0003פסול באדם פסול בבהמה,\u0004 אבל \u0003קלוט\u0004 (שפרסותיו עגולות כשל חמור) \u0003וחוטין\u0004 (החניכיים) שנפגמו, \u0003דליתנהו\u0004 \u0005[שאינם\u0006 כתובים\u0005]\u0006 \u0003באדם,\u0004 מפני שאינם שייכים בו, שהרי אין לו פרסות, והחניכיים שלו מכוסות כולן בשיניים, הייתי אומר: \u0003בבהמה נמי לא ליפסלו\u0004 \u0005[גם כן שלא יפסלו].\u0006 \u0003ו\u0004כן אם \u0003לכתוב רחמנא כולהו\u0004 \u0005[תכתוב התורה את כולם]\u0006 \u0003בבהמה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כך: כל ש\u0003פסול בבהמה פסול באדם,\u0004 אבל \u0003גבן\u0004 (שיש לו מומים בגבות עיניו) \u0003וחרום\u0004 (שחוטמו שקוע בין עיניו), \u0003דליתנהו\u0004 \u0005[שאינם\u0006 כתובים\u0005]\u0006 \u0003בבהמה,\u0004 מפני שאין מצויים בה מומים אלה — \u0003באדם נמי לא ליפסלו\u0004 \u0005[גם כן שלא יפסלו].\u0006 לכן הוצרכו כל המומים להיכתב בכל אחד מהם, בגלל המומים המיוחדים לו.","","ומקשים: ומדוע הוצרכה התורה לכתוב חלק מן המומים המשותפים באדם וחלק בבהמה? \u0003ולכתבינהו רחמנא כולהו בחד\u0004 \u0005[ושתכתוב התורה את\u0006 המומים המשותפים \u0005כולם ב\u0006מקום \u0005אחד],\u0006 או באדם או בבהמה, \u0003והנך דליתנהו באידך\u0004 \u0005[ואלה שאינם באחר],\u0006 כלומר, מומים שיש רק בבהמה ולא באדם — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003בבהמה, והנך דליתנהו באידך\u0004 \u0005[ואלה שאינם באחר]\u0006 כלומר, שישנם באדם ולא בבהמה — \u0003לכתוב\u0004 \u0005[שתכתוב התורה]\u0006 \u0003באדם, וגרב וילפת\u0004 ייכתבו \u0003הכא והכא\u0004 \u0005[כאן וכאן],\u0006 לשם גזירה שווה, \u0003ולילפי מהדדי\u0004 \u0005[ושילמדו זה מזה]\u0006 לגבי המומים המשותפים, שנזכרו רק באחד מהם!","\u0003אלא\u0004 יש להסביר דבר זה \u0003כדתנא\u0004 \u0005[כפי ששנה] דבי\u0006 \u0005[\u0006החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל פרשה שנאמרה\u0004 בתורה \u0003ונשנית\u0004 פעם נוספת — \u0003לא נשנית\u0004 כולה \u0003אלא בשביל דבר\u0004 אחד \u0003שנתחדש בה.\u0004 ואף כאן, נאמרו המומים גם באדם וגם בבהמה בגלל המומים המיוחדים שנתחדשו בכל אחד מהם (גיבן וחרום באדם, קלוט וחוטין בבהמה).","\u0003אמר רבא: למה לי דכתב רחמנא\u0004 \u0005[לשם מה כתבה התורה]\u0006 ש\u0003מום\u0004 פוסל \u0003באדם,\u0004 כלומר, בכהן (ויקרא כא, יז—כג), ש\u0003מום\u0004 פוסל בקדשים, בבהמות שהוקדשו למזבח (ויקראד כב, כ—כה), וש\u0003מום\u0004 פוסל להקרבה \u0003בבכור\u0004 בהמה (דברים טו, כא)?","\u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר בכל אחד מהם, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 ש\u0003מום\u0004 פוסל \u0003באדם,\u0004 הייתי אומר שדוקא בו המום פוסל, \u0003שכן נתרבה במצוות\u0004 יותר מבהמה. וכן אם היה הדבר נאמר רק בבכור הייתי אומר: \u0003אדם מבכור בהמה לא אתי\u0004 \u0005[אינו בא,\u0006 נלמד\u0005],\u0006 \u0003שכן הוא\u0004 הבכור \u0003עצמו קרב לגבי מזבח,\u0004 שהכהן מצווה להקריבו, ויש לומר שמשום כך המום פוסל בו. מה שאין כן האדם.","וכן \u0003קדשים מבכור לא אתי\u0004 \u0005[אינם באים,\u0006 נלמדים\u0005],\u0006 \u0003שכן קדושתו\u0004 של בכור \u0003מרחם,\u0004 כלומר, משנולד, ושאר קדשים צריכים הקדשה על ידי האדם, וקדושה פחותה היא.","וכן אם היה הדבר נכתב רק בקדשים, הייתי אומר: \u0003אדם מקדשים לא אתי\u0004 \u0005[אינו בא,\u0006 נלמד\u0005],\u0006 \u0003שכן הן\u0004 הקדשים \u0003עצמן קריבין.\u0004 וכן \u0003בכור מקדשים לא אתי\u0004 \u0005[אינו בא,\u0006 נלמד\u0005],\u0006 \u0003שכן קדושתו\u0004 (קדושתם) של שאר קדשים \u0003מרובה\u0004 משל בכור, שיש מינים רבים של קדשים שאדם מקדיש, עולות חטאות ועוד, אבל בכור יש רק אחד. על כן כתבה התורה שהמומים פוסלים בכל אחד מהם.","ושואלים: אמנם \u0003חדא מחדא לא אתיא\u0004 \u0005[אחת מאחת אינה באה,\u0006 אינה יכולה להילמד\u0005],\u0006 אבל \u0003תיתי חדא מתרתי\u0004 \u0005[תבוא,\u0006 תילמד \u0005אחת משתים\u0006 אחרות\u0005]!\u0006 ודוחים: \u0003מהי תיתי\u0004 \u0005[מאיזה תבוא,\u0006 תילמד\u0005]\u0006 כל אחת מהן? אם תאמר: \u0003לא לכתב רחמנא\u0004 \u0005[שלא תכתוב התורה]\u0006 שמומים פוסלים \u0003בבכור, ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה],\u0006 מאדם וקדשים — יש לפרוך: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן קדושתן מרובה,\u0004 שאדם נתרבה במצוות, וקדשים יש בהם מינים רבים; \u0003ונוהגין בפשוטין,\u0004 שכל כהן כשר לעבודה, וכל בהמה כשרה להקרבה, ולא רק בכור. ואם תאמר: \u0003לא לכתוב רחמנא\u0004 \u0005[שלא תכתוב התורה]\u0006 שמום פוסל \u0003בקדשים, ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד, \u0005מאלה],\u0006 מבכור ומאדם — אפשר לדחות: \u0003מה להנך\u0004 \u0005[לאלה],\u0006 \u0003שכן קדושתן מאליהן,\u0004 שכהן הוא הנולד לכהן, ובכור הוא הנולד ראשון לאמו, ואינם צריכים הקדשה! ואם תאמר: \u0003לא לכתוב\u0004 \u0005[שלא תכתוב התורה]\u0006 שמום פוסל \u0003באדם, ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה]\u0006 מבכור וקדשים — יש לפרוך: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 בכור וקדשים, \u0003שכן הן עצמן קריבין לגבי מזבח,\u0004 מה שאין כן האדם. משום כך \u0003צריכי\u0004 \u0005[צריכים]\u0006 שלושתם להיכתב כדי ללמד שמום פוסל בהם.","","","שנינו במשנה שנוסף למומים המנויים בבהמה \u0003יתר עליהן באדם\u0004 אנשים שצורתם משונה, אף שאין בהם מום של ממש. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שדבר זה פוסל את הכהנים לעבודה? \u0003אמר ר' יוחנן, דאמר קרא\u0004 \u0005[שאמר המקרא]:\u0006 \u0003\"כל איש אשר בו מום מזרע אהרן\u0004 לא יגש להקריב את אשי ה' \" (ויקרא כא, כא) — ומכאן למדים שצריך הכהן להיות \u0003איש ששוה בזרעו של אהרן,\u0004 שדומה במראה לכל שאר הכהנים, ולא שונה מהם."],["ושואלים: \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש]\u0006 להלכה \u0003בין\u0004 כהן הנפסל לעבודה משום שיש בו \u0003מומא\u0004 \u0005[מום]\u0006 גמור, השווה באדם ובבהמה, \u0003ל\u0004בין כהן שנפסל לעבודה מחמת \u0003שאינו שוה בזרעו של אהרן?\u0004 ומשיבים: \u0003איכא\u0004 \u0005[יש]\u0006 הבדל ביניהם \u0003משום אחולי\u0004 \u0005[חילול]\u0006 \u0003עבודה;\u0004 כהן שיש בו \u0003מומא\u0004 \u0005[מום]\u0006 ועבד במקדש — \u0003מחיל\u0004 \u0005[מחלל]\u0006 \u0003עבודה\u0004 שעבד, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מום בו ולא יחלל\u0004 את מקדשי\" (ויקרא כא, כג), ומה שעשה — פסול. אבל מי \u0003שאינו שוה בזרעו של אהרן,\u0004 אף על פי שאסור לו לעבוד במקדש — \u0003לא מחיל\u0004 \u0005[אינו מחלל]\u0006 \u0003עבודה,\u0004 לא נפסלה עבודתו.","ועוד שואלים: \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש]\u0006 \u0003בין\u0004 מי שנפסל לעבודה מחמת \u0003שאינו שוה בזרעו של אהרן,\u0004 כגון אלו ששנינו במשנתנו, הכילון והלפתן וכו', \u0003ו\u0004בין מי שנפסל במשניות להלן \u0003משום מראית העין,\u0004 כגון מי שנשרו ריסי עיניו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 איסור \u0003עשה,\u0004 שכהן שאינו שווה בזרעו של אהרן שעבד — עובר על מצות עשה, שרק איש שהוא שווה בזרעו של אהרן מותר בעבודה. אבל בדבר שהוא מטעם מראית העין — אין זה איסור שמן התורה, אלא חכמים אמרו שלא יעבוד.","שנינו במשנה שמומים אלו פוסלים את הכהנים: הכילון, הלפתן, המקבן, שראשו שקוט וסקיפת. ומבארים: \u0003\"כילון\"\u0004 — \u0003דדמי רישיה לאכלא\u0004 \u0005[שדומה ראשו לכיסוי\u0006 של חבית\u0005],\u0006 רחב מלמטה וצר מלמעלה. \u0003\"לפתא\"\u0004 — \u0003דדמי רישיה לגדגלידא דליפתא\u0004 \u0005[שדומה ראשו לראש של לפת],\u0006 שהוא רחב ומעוגל, ונעשה צר מלמטה. \u0003תנא\u0004 \u0005[שנה החכם]:\u0006 \u0003וצוארו עומד באמצע ראשו,\u0004 שראשו בולט לכל הכיוונים בשווה. ולא כצוארו של אדם רגיל, שעומד בצד האחורי של ראשו.","\u0003\"מקבן\"\u0004 — \u0003דדמי רישיה למקבן\u0004 \u0005[שדומה ראשו למקבת,\u0006 מעין פטיש\u0005].\u0006 \u0003\"ושראשו שקוט\"\u0004 — כוונתו שיש מעין שקע בראשו \u0003מלפניו. \"וסקיפת\"\u0004 — שראשו נראה כאילו ניטלה חתיכה \u0003מאחוריו, כדאמרי אינשי\u0004 \u0005[כמו שאומרים אנשים]:\u0006 \u0003שקיל פיסא\u0004 \u0005[נטולה חתיכה],\u0006 ו\"סקיפת\" הוא כעין קיצור של לשון זו. עד כאן בפירוש המומים שנזכרו במשנה. ומעירים, \u0003תנא\u0004 \u0005[שנה החכם]\u0006 בברייתא עוד מומים הפוסלים בכהן: \u0003וצוארו שקוט\u0004 (קצר) \u0003ושמוט.\u0004 ומבארים: \u0003שקוט\u0004 — \u0003דחביא מחבא\u0004 \u0005[ש\u0006צוארו \u0005חבוי],\u0006 אינו נראה בין כתפיו. \u0003שמוט\u0004 — \u0003דאריך\u0004 \u0005[ש\u0006צוארו \u0005ארוך]\u0006 \u0003ושמוט.\u0004","שנינו במשנה: \u0003ובעלי חטרות\u0004 (גבנון, חטוטרת, בליטה בגב) — \u0003ר' יהודה\u0004 מכשיר, וחכמים פוסלים. ומסבירים: במקרה \u0003דאית ביה\u0004 \u0005[שיש בה,\u0006 בחטוטרת\u0005]\u0006 \u0003עצם\u0004 — \u0003כולי עלמא לא פליגי דפסלא\u0004 \u0005[הכל אינם חולקים ש\u0006היא \u0005פוסלת]\u0006 את הכהן לעבודה. כי פליגי \u0005[כאשר נחלקו]\u0006 הרי זה בחטוטרת \u0003דלית ביה\u0004 \u0005[שאין בה]\u0006 \u0003עצם, מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אינו שוה בזרעו של אהרן\u0004 ויש לפוסלו, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003קרקורא דבישרא בעלמא\u0004 \u0005[חתיכה של בשר בלבד]\u0006 \u0003הוא,\u0004 ואינו נחשב למום.","שנינו במשנה: \u0003הקרח פסול.\u0004 איזהו קרח — כל שאין לו שיטה (שורה) של שיער מקפת מאוזן לאוזן. \u0003אמר רבא: לא שנו\u0004 שהקרח פסול \u0003אלא שאין לו\u0004 שיטה של שיער \u0003לאחריו, ויש לו לפניו. אבל יש לו\u0004 שיטה של שיער גם לפניו וגם \u0003לאחריו\u0004 — \u0003כשר, וכל שכן\u0004 שהוא כשר כ\u0003שיש לו לאחריו ואין לו לפניו,\u0004 שהוא כדרכם של אנשים מבוגרים.","\u0003ואיכא דמתני אסיפא\u0004 \u0005[ויש ששונים\u0006 דבר זה \u0005על הסוף\u0006 של הלכה זו\u0005]:\u0006 \u0003ואם יש לו\u0004 שיטה של שיער — \u0003הרי זה כשר. אמר רבא: לא שנו\u0004 שהוא כשר \u0003אלא שיש לו לאחריו ואין לו לפניו, אבל יש לו בין לאחריו בין לפניו\u0004 — \u0003פסול, וכל שכן שיש לו לפניו ואין לו לאחריו, ו\u0004כן ש\u0003אין לו כלל,\u0004 לא לפניו ולא לאחריו, ש\u0003פסול.\u0004","\u0003אמר ר' יוחנן:\u0004 הכהנים \u0003הקרחנין\u0004 (הקרחים) \u0003והננסין והזבלגנין\u0004 (שעיניהם זולגות תמיד) — פסולין לעבודה, \u0003לפי שאינן\u0004 בכלל מי שהוא \u0003שוה בזרעו של אהרן.\u0004 ושואלים: מדוע הוצרך ר' יוחנן לומר כן? הלא \u0003קרחנין\u0004 — כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנתנו, וכן \u0003ננסין\u0004 — \u0003תנינא\u0004 \u0005[שנינו]\u0006 להלן (מה,ב)!","ומשיבים: \u0003זבלגנין\u0004 \u0003איצטריך ליה לאשמועינן\u0004 \u0005[הוצרך לו להשמיענו],\u0006 שהרי אינם נזכרים במשנה. \u0003ו\u0004גם קרחנים וננסים הוצרך להשמיענו, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שפסולם אינו אלא מדברי חכמים \u0003משום מראית העין,\u0004 לכן הוצרך לומר לנו שהם פסולים מן התורה, משום שאינם שווים בזרעו של אהרן. ושואלים: ומדוע יכולים היינו לומר כן?","\u0003והא כל היכא דאיכא\u0004 \u0005[והרי בכל מקום שיש\u0006 בו\u0005]\u0006 \u0003משום מראית העין איתנא קתני\u0004 \u0005[שונה\u0006 התנא את הדבר במפורש\u0005],\u0006 כגון מה ששנינו להלן: ושנשרו ריסי עיניו פסול מפני מראית העין! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003תני חדא\u0004 \u0005[שנה\u0006 דוגמא \u0005אחת],\u0006 \u0003ו\u0004אולם \u0003הוא הדין לכולהו\u0004 \u0005[לכולם],\u0006 וגם לקרח וננס.","ומקשים: \u0003והא כל היכא דאיכא מיהדר ומיתנא\u0004 — \u0003קא הדר ותני\u0004 \u0005[והרי בכל מקום שיש\u0006 מקום \u0005לחזור ולשנות\u0006 שהוא משום מראית עין — הוא \u0005חוזר ושונה]\u0006 כפי ששנינו במשנה בעמוד הבא: \u0003ושניטלו שיניו פסול משום מראית העין! אלא\u0004 יש לתרץ בדרך אחרת, שמה שאמר ר' יוחנן בא \u0003לאפוקי מהא דתניא\u0004 \u0005[להוציא מ\u0006דעה \u0005זו ששנויה\u0006 בברייתא\u0005],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הקרחנין והננסין והזבלגנין כשרים, ולא אמרו\u0004 חכמים שהוא \u0003פסול אלא משום מראית העין.\u0004 ועל כך אמר ר' יוחנן שיש בהם פסול מן התורה, שאינם בכלל איש ששווה בזרעו של אהרן.","ומעירים: \u0003מאן האי תנא\u0004 \u0005[מיהו תנא זה]\u0006 שסבור שכהנים אלו כשרים? שיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 מה שנאמר \"וערכו בני אהרן \u0003הכהנים\"\u0004 (ויקרא א, ח) — הרי זה \u0003לרבות הקרחנין,\u0004 שהם כשרים לעבוד.","\u0003אין לו\u0004 לכהן \u0003גבינין\u0004 (גבות עיניים) כלל, \u0003או אין לו אלא גבין אחד,\u0004 שגבות עיניו מחוברות — \u0003זהו גבן האמור בתורה\u0004 ברשימת בעלי המומים (ויקרא כא, כ). רבי דוסא אומר: \"גבן\" האמור בתורה הוא זה \u0003שגביניו\u0004 ארוכים עד שהם \u0003שוכבין,\u0004 ומכסים את עיניו. \u0003רבי חנינא בן אנטיגנוס אומר:\u0004 \"גבן\" הוא זה \u0003שיש לו שני גבין ושתי שדראות.\u0004","שנינו במשנה: אין לו גבינים וכו' זהו \"גבן\" האמור בתורה. ושואלים: \u0003ו\"גבן\"\u0004 — ש\u0003אין לו\u0004 גבינים \u0003משמע\u0004 \u0005[משמעו]?\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003\"גבן\"\u0004 שהוזכר בתורה — \u0003שיש לו גבינין הרבה. אין לו גבינין, או אין לו אלא גבין אחד מנין? תלמוד לומר: \"או גבן\"\u0004 (שמות יב, ה), ונמצא שלמדים מי שאין לו גבינים רק מן הייתור של \"או\", ולא מן המלה \"גבן\" כשלעצמה! \u0003אמר רבא,\u0004 כך יש להבין את המשנה: אין לו גבינים — \u0003זה\u0004 מה שלמדו מ\u0003מדרש\u0004 המלים \u0003\"או גבן\",\u0004 אבל לא מן המלה \"גבן\" לעצמה, שמשמעה לפי הברייתא — מי שיש לו גבינים הרבה.","ועוד שנינו במשנה, \u0003רבי דוסא אומר:\u0004 \"גבן\" האמור בתורה הוא כל שיש לו שני גבים ושתי שדראות. ומדייקים: ממה שכהן כזה נפסל לעבודה כבעל מום, האם יש \u0003למימרא\u0004 \u0005[לומר,\u0006 ללמוד מכאן\u0005]\u0006 שמי שיש לו שני גבים ושתי שדראות \u0003דחיי\u0004 \u0005[שהוא חי]?\u0006 \u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו אמוראים בדין \u0003המפלת בריה שיש לה שני גבין ושתי שדראות. ואמר רב: באשה\u0004 — \u0003אינו\u0004 נחשב ל\u0003וולד,\u0004 מפני שאינו יכול להתקיים, ואין אמו טמאה טומאת לידה. בבהמה — הרי הוא \u0003אסור באכילה!\u0004","ואומרים: \u0003כבר רמא ניהליה\u0004 \u0005[הקשה את הדבר הזה לו]\u0006 \u0003רב שימי בר חייא לרב, ואמר ליה\u0004 \u0005[לו]\u0006 רב בתמיהה: האם \u0003שימי את\u0004 \u0005[אתה]?\u0006 לא התכוון ר' חנינא בן אנטיגנוס במשנתנו למי שיש לו שתי שדראות ממש, \u0003אלא\u0004 הכוונה היא \u0003בששדרתו עקומה,\u0004 שנראית כשתים, ועליו אמר ר' חנינא שהוא בעל מום ופסול לעבודה.","\u0003החרום פסול. איזהו חרום? הכוחל,\u0004 מעביר מכחול של משחה או צבע, על \u0003שתי עיניו כאחת,\u0004 ששורש חוטמו שקוע כל כך עד שאין הפסק כלל בין העינים. היו \u0003שתי עיניו למעלה, ושתי עיניו למטה, עינו אחת למעלה ועינו אחת למטה, רואה את החדר ואת העלייה כאחד. סכי שמש\u0004 (שאינם יכולים להסתכל באור השמש), \u0003והזגדן והצירן\u0004 (שיבואר עניינם בגמרא). \u0003ושנשרו ריסי עיניו\u0004 — הרי זה \u0003פסול\u0004 לעבודה \u0003מפני מראית העין,\u0004 שאסרו עליו חכמים לעבוד במקדש, ולא מפני שהוא מום מן התורה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"חרום\"\u0004 שנזכר ברשימת הכהנים בעלי המום (ויקרא כא, יח) — הרי זה \u0003שחוטמו שקוע.\u0004 אם היה \u0003חוטמו סולד\u0004 (קצר במיוחד, ומכווץ כלפי מעלה), \u0003חוטמו בולם\u0004 (סתום), \u0003חוטמו נוטף\u0004 (ארוך ותלוי למטה), \u0003מנין\u0004 שהוא פסול? תלמוד לומר: \"או חרום\" (ויקרא כא, יח), ו\"או\" בא לרבות כל מום שבחוטמו. ל\u0003ר' יוסי אומר: אין \"חרום\" אלא הכוחל\u0004 את \u0003שתי עיניו כאחת, אמרו לו: הפלגת,\u0004 הרחקת לכת, אלא כל שחוטמו שקוע יותר מן הרגיל הרי זה \"חרום\", שהוא בעל מום,"],["\u0003אף על פי שאינו כוחל שתי עיניו כאחת,\u0004 אלא כל ששורש אפו שקוע מן הרגיל הרי זה מום.","נאמר במשנה: שתי עיניו למעלה \u0003שתי עיניו למטה.\u0004 ושואלים: \u0003מה\u0004 פירוש \u0003שתי עיניו למעלה שתי עיניו למטה? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003שתי עיניו למעלה\u0004 — \u0003דחזי\u0004 \u0005[שרואה,\u0006 שנראה כמסתכל\u0005]\u0006 כל הזמן \u0003למעלה,\u0004 וכן \u0003שתי עיניו למטה\u0004 — \u0003דחזי\u0004 \u0005[שרואה]\u0006 כל הזמן \u0003למטה,\u0004 אם כן מה שהוא שונה: \u0003עינו אחת למעלה ועינו אחת למטה,\u0004 צריך אתה לפרש באותו אופן, שכוונתו — \u0003דחזאי\u0004 \u0005[שרואה]\u0006 \u0003עינו אחת למטה ועינו אחת למעלה,\u0004 ואולם \u0003היינו\u0004 \u0005[הרי זה בדיוק]\u0006 אותה הלכה שנאמרה לאחר מכן: \u0003רואה את החדר ואת העלייה כאחת!\u0004","\u0003אלא\u0004 כך צריך לומר: \u0003שתי עיניו למעלה\u0004 — \u0003דקיימן\u0004 \u0005[שמצויות]\u0006 עיניו \u0003למעלה\u0004 ממקומן הרגיל, וכן \u0003שתי עיניו למטה\u0004 — \u0003דקיימן\u0004 \u0005[שמצויות]\u0006 \u0003למטה\u0004 ממקומן, \u0003עינו אחת למעלה ועינו אחת למטה\u0004 — \u0003דקיימי\u0004 \u0005[שמצויות]\u0006 \u0003עינו אחת למעלה ועינו אחת למטה.\u0004 ועל כך הוסיפה המשנה: \u0003וקיימי\u0004 \u0005[ו\u0006במקרה ש\u0005מצויות]\u0006 עיניו \u0003כסדרן,\u0004 במקומן הרגיל \u0003נמי\u0004 \u0005[גם כן],\u0006 \u0003ורואה את החדר ואת העלייה כאחת\u0004 — הרי זה מום.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 שמומים אלו פוסלים? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר במומי הכהנים: \"או דק או תבלול בעינו\" (ויקרא כא, כ). והרי ידוע שדק ותבלול הם בעינו! אלא, לכך נאמר \u0003\"בעינו\"\u0004 — ללמד: \u0003כל מה,\u0004 כל מום \u0003ש\u0004ישנו \u0003בעינו,\u0004 הרי זה פוסלו. \u0003מכאן אמרו\u0004 חכמים: \u0003שתי עיניו למטה, שתי עיניו למעלה, עינו אחת למעלה ועינו אחת למטה, ורואה את החדר ואת העלייה כאחת, או שמדבר עם חבירו, ו\u0004אדם \u0003אחר אומר: לי\u0004 (אותי) \u0003רואה\u0004 — כל אלה הם מומים הפוסלים את הכהן מעבודה.","וביחס לשאר מומים ששנו חכמים בעין, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר במומי האדם \u0003\"עור\"\u0004 (ויקרא כא, יח) כוונתו — \u0003בין\u0004 שהוא \u0003סומא\u0004 מטבע ברייתו \u0003בשתי עיניו, בין סומא באחת מעיניו.\u0004 אבל מי שאינו מסוגל לראות מחמת \u0003חורוור והמים הקבועין\u0004 שבעין, שהם מחלות הגורמות לאובדן כושר הראיה, \u0003מנין\u0004 שהוא פסול? \u0003תלמוד לומר: \"איש עור\"\u0004 (ויקרא כא, יח) ו\"איש\" בא לרבות גם את אלו.","ועוד בענין זה, \u0003אמר רבא: למה לי\u0004 כל הפירוט \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 במומי העין: \u0003\"איש\", \"עור\", \"דק\", \"תבלול\", \"בעינו\"? צריכי\u0004 \u0005[צריכים]\u0006 הם כולם, \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"עור\"\u0004 — הייתי אומר שהוא נחשב למום \u0003משום דליתנהו\u0004 \u0005[ש\u0006עיניו \u0005אינן\u0006 קיימות\u0005]\u0006 \u0003כלל, אבל חורוור והמים הקבועין דאיתנהו ביה\u0004 \u0005[שישנם בו]\u0006 העיניים, אלא שאינו רואה — \u0003לא\u0004 נחשב כמום, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"איש\"\u0004 לרבות גם את אלה.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 \u0003\"איש\u0004 עור\", הייתי אומר שהוא פסול \u0003משום דלא קא חזי\u0004 \u0005[שאינו רואה]\u0006 \u0003כלל,\u0004 בין משום שאין לו עינים, ובין משום מחלה, אבל אם ראייתו קיימת, אלא שהיא \u0003מחסורייתא\u0004 \u0005[חסרה,\u0006 לקויה\u0005]\u0006 — \u0003לא\u0004 פסול, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"דק\",\u0004 שעניינו כתם המפריע לראיה. \u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 גם \u0003\"דק\"\u0004 — הייתי אומר שהוא פסול \u0003משום דמחסרן\u0004 \u0005[ש\u0006עיניו \u0005חסרות\u0006 בראייתן\u0005],\u0006 \u0003אבל\u0004 אם ראייתו תקינה, אלא שיש בעינו \u0003מבלבליתא\u0004 \u0005[תבלול,\u0006 המבלבל ומערב את השחור והלבן שבעין\u0005],\u0006 וכפי ששנינו בפרק הקודם (לז,א) — \u0003לא\u0004 פסול, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"תבלול\".\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 גם \u0003\"תבלול\"\u0004 — הייתי אומר שהוא פסול \u0003משום דמבלבלן\u0004 \u0005[שהן מבולבלות],\u0006 \u0003אבל משום משניותא\u0004 \u0005[שינוי],\u0006 שעיניו משונות במיקומן או בגודלן, או שונות זו מזו — \u0003לא\u0004 פסול, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"בעינו\".\u0004","\u0003אמר רבא: הלכך\u0004 \u0005[על כן],\u0006 \u0003כל\u0004 מום שהוא \u0003מחמת כהיותא\u0004 \u0005[כהות,\u0006 אובדן מאור העיניים\u0005]\u0006 — \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 \u0003מ\u0004הריבוי של \u0003\"איש\",\u0004 כל דבר שיש בו \u0003מחסורייתא\u0004 \u0005[חסרון\u0006 בכושר הראיה\u0005]\u0006 — \u0003מ\"דק\",\u0004 כל דבר שיש בו \u0003מבלבליתא\u0004 \u0005[בלבול\u0006 השחור והלבן שבעין\u0005]\u0006 — נלמד \u0003מ\"תבלול\",\u0004 ואילו \u0003משניותא\u0004 \u0005[שינוי\u0006 שבעין\u0005]\u0006 — \u0003מ\"בעינו\".\u0004","שנינו במשנה: \u0003סכי שמש. תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בהסבר דבר זה: \u0003סני\u0004 \u0005[שונא]\u0006 \u0003שמש,\u0004 כלומר, מי שאינו מסוגל לפקוח את עיניו באור השמש. ועוד שנינו במשנה: \u0003זגדיין.\u0004 כפירוש לכך היה \u0003מחוי\u0004 \u0005[מחוה,\u0006 מורה באצבעו\u0005]\u0006 \u0003רב הונא:\u0004 כמו מי שיש לו \u0003חד מדידן\u0004 \u0005[\u0006עין \u0005אחת משלנו]\u0006 שהיא עין רגילה, \u0003וחד מדידהו\u0004 \u0005[ואחת משלהם],\u0006 והצביע לעבר רב יהודה. \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 על כך \u0003רב יהודה,\u0004 שהצביע לעברו, שהיו לו עיניים משונות משל אחרים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על פירושו של רב הונא ל\"זגדיין\", ממה ששנינו בברייתא: \u0003שכבנא\u0004 ששנו חכמים שהוא פסול — הריהו זה \u0003שגביניו\u0004 (גבות עיניו) \u0003שוכבים\u0004 על עיניו. \u0003זגדום,\u0004 כלומר, זגדיין — ש\u0003אחד\u0004 מגביניו \u0003שחור ואחד לבן!\u0004 ומשיבים: ה\u0003תנא, כל זוגא דלא שוי להדדי\u0004 \u0005[כל זוג\u0006 איברים \u0005שאינם שווים זה לזה]\u0006 \u0003\"זגדום\" קרי ליה\u0004 \u0005[קורא לו].\u0006","ועוד שנינו במשנה: \u0003הצירן.\u0004 ובענין זה מביאים מה ששנינו בברייתא: \u0003עיניו תרוטות,\u0004 שעפעפיו פתוחים מעט, \u0003וצירניות,\u0004 עגולות לגמרי, וכן מי שעיניו \u0003דומעות,\u0004 או \u0003דולפות,\u0004 או \u0003טורדות\u0004","\u0003. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בברייתא מומים נוספים שבעין: \u0003הזדיר והלופין והתמיר.\u0004 ומבארים: \u0003זויר\u0004 (זדיר) — הוא \u0003דמזור עיניה\u0004 \u0005[שמוזרות עיניו],\u0006 \u0003לופין\u0004 — \u0003דנפישין זיפיה\u0004 \u0005[שמרובים זיפיו,\u0006 ריסי עיניו\u0005],\u0006 \u0003תמיר\u0004 — \u0003שתמו\u0004 \u0005[שאין לו]\u0006 \u0003זיפין.\u0004 ושואלים: \u0003והני\u0004 \u0005[ואלה]\u0006 שאין לו ריסים, \u0003גבי מומין תנו להו\u0004 \u0005[אצל המומים הוא שונה אותם]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 מי \u0003שנשרו ריסי עיניו פסול מפני מראית העין,\u0004 אבל אין זה מום! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא דאשתיור גרדומי\u0004 \u0005[זה שנשארו גדמים,\u0006 שורשי הריסים בעפעף\u0005]\u0006 — הרי זה פסול רק מפני מראית עין, \u0003הא דלא אישתיור גרדומי\u0004 \u0005[זה שלא נשתיירו אפילו גדמים],\u0006 הריהו נחשב למום.","ועוד מומים המיוחדים לאדם, ופוסלים את הכהן לעבודה: היו \u0003עיניו\u0004 של הכהן \u0003גדולות כשל עגל או קטנות כשל אווז.\u0004 היה \u0003גופו גדול מאבריו,\u0004 כלומר, ביחס לידיו ורגליו, \u0003או\u0004 שהיה גופו \u0003קטן מאבריו\u0004 לפי היחס הרגיל, וכן אם היה \u0003חוטמו גדול\u0004 הרבה \u0003מאבריו\u0004 האחרים באופן יחסי, \u0003או קטן מאיבריו. הצומם והצומע. איזהו צומע? כל שאזניו קטנות, והצומם\u0004 — \u0003כל שאזניו דומות לספוג.\u0004 היתה \u0003שפתו העליונה עודפת על התחתונה,\u0004 או \u0003התחתונה עודפת על העליונה\u0004 — \u0003הרי זה מום. ו\u0004מי \u0003שנשרו שיניו\u0004 — \u0003פסול,\u0004 אבל לא משום שהוא מום, אלא רק \u0003מפני מראית העין.\u0004","שנינו במשנה: היה גופו גדול מאבריו או קטן מאבריו. ובענין זה מסופר, \u0003אמר רב: משה רבינו עשר אמות היה\u0004 גובהו, ומנין? \u0003שנאמר: \"ויפרש את האהל על המשכן\"\u0004 (שמות מ, יט), \u0003מי פרשו\u0004 — \u0003משה רבינו פרשו. וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]\u0006 ביחס לגובה המשכן: \u0003\"עשר אמות אורך הקרש\"\u0004 (שמות כו, טז), ורק אם היה משה גבוה כגובה המשכן לפחות, יכול היה לפרוש את האהל על הקרשים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שימי בר חייא לרב: אם כן עשיתו למשה רבינו בעל מום, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו]\u0006 במשנתנו לגבי מומים הפוסלים בכהן: \u0003גופו גדול מאבריו או קטן מאבריו.\u0004 והרי אורך גופו של אדם רגיל אינו ארוך אלא כשלוש אמות שלו, ואילו משה היה גבוה עשר אמות! והבין רב שימי כי כוונת רב היתה שקומתו של משה היתה כעשר אמות של משה עצמו, ונמצא שגופו גדול הרבה מאיבריו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003שימי,\u0004 לא באורך האמה של משה עצמו מדובר, אלא \u0003באמה של קרש קאמר\u0004 \u0005[הוא אומר],\u0006 שהשתמשו בה לבניית המשכן, שהיה משה בגובה עשר אמות של אדם רגיל, כגובה המשכן. ואמתו היתה גדולה בהתאם לגודל גופו.","ועוד שנינו ברשימת המומים שבמשנה: \u0003חוטמו גדול\u0004 מאבריו או קטן מאבריו. \u0003תנא\u0004 \u0005[שנה החכם]\u0006 בברייתא: שיעור זה הוא \u0003כאצבע קטנה.\u0004","שנינו ברשימת המומים שבמשנה: \u0003הצימם והצימע. תנא\u0004 \u0005[שנה החכם]\u0006 בברייתא: \u0003אף הצימח\u0004 פסול. מסופר, \u0003לא הוו ידעי רבנן מאי \"צימח\"\u0004 \u0005[לא היו יודעים חכמים מהו \"צימח\"],\u0006 \u0003שמעו לההוא טייעא דהוה קאמר\u0004 \u0005[שמעו ערבי\u0006 אחד \u0005שהיה אומר]:\u0006 \u0003מאן דבעי\u0004 \u0005[מי הוא זה שרוצה]\u0006 \u0003צימח, ואישתכח גדיא חזיזא\u0004 \u0005[ונמצא גדי שאזניו ארוכות מאד].\u0006 ואם כן, הכוונה היא לכהן שאזניו ארוכות ונופלות. מתוך שהובא דינם של הצימח הצימע והצומם באדם, דנים במומים אלה כשהם בבהמה.","וכך \u0003אמר רב חסדא: עז שאין לה קרנים\u0004 כלל, \u0003ורחל\u0004 (כבשה) \u0003שיש לה קרנים\u0004 — \u0003כשרים לגבי מזבח,\u0004 אף על פי שהם שונים משאר עזים ורחלים.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003יש דברים שהן\u0004 נראים \u0003כמומין, ו\u0004אולם באמת \u0003אינן כמומין, ו\u0004לכן \u0003שוחטין עליהם במקדש,\u0004 כלומר, מקריבים בהמה למרות שיש בה פגם זה, \u0003אבל לא\u0004 הותר לשחוט את הבהמה \u0003במדינה\u0004 בגללם, גם מפני שבאמת אין זה מום. \u0003ואלו הן: עז שאין לו\u0004 (לה) \u0003קרנים, ורחל שיש לו\u0004 (לה) \u0003קרנים, ו\u0004כן \u0003הצימח והצימם והצימע.\u0004 שאין הם נחשבים מומים אלא באדם, כפי ששנינו במשנתנו, אבל לא בבהמה.","ועוד בענין קרניים, \u0003אמר רב חסדא אמר אמימר:\u0004 אם \u0003נטלו קרנותן\u0004 של בהמות, \u0003וזכרותן\u0004 (מעין עצם שבתוך הקרן) \u0003עמהן\u0004 — הרי זו \u0003פסולה\u0004 להקרבה, \u0003ו\u0004אולם \u0003אין פודין עליהם\u0004 את הקדשים, שאין זה מום גמור. אבל אם \u0003נטלו טלפיים,\u0004 החלק הקרני שבקצות רגליהם, הפרסה, \u0003וזכרותם\u0004 (חלק הרגל שהטלפיים מחוברות אליו) \u0003עמהן,\u0004 עם הטלפיים — \u0003פסולין\u0004 להקרבה \u0003ו\u0004גם \u0003נפדין עליהם,\u0004 מפני שהוא מום גמור.","על מה שאמר רב חסדא שאם ניטלו הקרניים עם זכרותם אין זה מום גמור כדי לפדות בגללו את הקדשים, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003נטלו קרניין וטלפיין וזכרותן עמהן\u0004 — \u0003פסולין ונפדין עליהן!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא דאיתעקור איתעקורי\u0004 \u0005[זה שנעקרו לגמרי]\u0006 זכרותם של הקרניים — הרי זה מום גמור, ונפדים על כך. \u0003הא דאיגום איגומי\u0004 \u0005[זה שנגממו,\u0006 נחתכו\u0005]\u0006 זכרותם, אבל לא נעקרו לגמרי — פסולים, אבל אין נפדים על כך.","ושואלים: \u0003ודאיגום איגומי\u0004 \u0005[ו\u0006במקרה \u0005ש\u0006רק \u0005נגממו]\u0006 זכרותם של קרניים, האם \u0003פסול\u0004 הוא? \u0003ורמינהו\u0004 \u0005[ומשליכים על כך]\u0006 קושיה ממה ששנינו: \u0003פרה\u0004 אדומה \u0003שקרניה וטלפיה שחורים\u0004 — הרי זה \u0003יגוד\u0004 \u0005[יחתוך\u0006 אותן\u0005],\u0006 ותישאר כולה אדומה. משמע שאפשר לחתוך את הקרניים, ואין זה נחשב מום! \u0003תרגמה\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה]\u0006 \u0003זעירי\u0004 משנה זו: מדובר שם שחותך את הקרניים \u0003מעילוי\u0004 \u0005[מעל]\u0006 ה\u0003זכרות,\u0004 שהרי אין הזכרות מגיעה עד קצה הקרן ממש. אבל אם נחתך מן הזכרות עצמה — הרי זה פוסל."],["ועוד ברשימת המומים הפוסלים בכהנים: היו לו \u0003דדין\u0004 (שדיים) גדולים עד שהיו \u0003שוכבין כשל אשה,\u0004 או \u0003כריסו צבה\u0004 (נפוחה ובולטת), או היה \u0003טיבורו יוצא,\u0004 או היה \u0003נכפה\u0004 (חולה בחולי נפילה) \u0003אפילו אחת לימים,\u0004 לעתים רחוקות, או \u0003רוח קצרה באה עליו,\u0004 וכן \u0003המאושבן, ובעל גבר,\u0004 שיבואר עניינם בגמרא.","בענין כרס צבה ששנינו במשנה, מביאים מה ש\u0003אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא:\u0004 תלמידי חכמים \u0003משתינין מים בפני רבים,\u0004 ואין חוששים לחוסר צניעות שבדבר, הואיל ויש בכך סכנה. \u0003ו\u0004אולם \u0003אין\u0004 תלמידי חכמים \u0003שותין מים בפני רבים,\u0004 שראוי לו לתלמיד חכם להיות צנוע בשתייתו. \u0003ותניא נמי הכי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003משתינין מים בפני רבים, ואין שותין מים בפני רבים. ומעשה באחד שביקש להשתין מים ולא השתין, ונמצא כריסו צבה.\u0004","מסופר, \u0003שמואל איצטריך ליה בשבתא דרגלא\u0004 \u0005[נצרך לו\u0006 להשתין \u0005בשבת של הרגל],\u0006 השבת שהיו באים כולם לשמוע את דרשתו, \u0003נגדו ליה גלימא\u0004 \u0005[פרסו לו גלימה\u0006 מסביב\u0005]\u0006 כדי שלא יראו אותו. לאחר זמן \u0003אתא לקמיה דאבוה\u0004 \u0005[בא\u0006 שמואל \u0005לפני אביו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אתן לך ארבע מאה זוזי\u0004 \u0005[ארבע מאות זוז]\u0006 \u0003וזיל אהדר עובדא\u0004 \u0005[ולך והחזר את המעשה],\u0006 כלומר, דרוש ברבים שאין עושים כן, כדי שלא ילמדו ממך שאין להשתין בפני רבים, שכן \u0003את\u0004 \u0005[אתה]\u0006 שאדם חשוב אתה, \u0003אפשר לך\u0004 לנהוג כך, שיעשו סביבך מחיצה, אבל מי ש\u0003לא אפשר ליה\u0004 \u0005[לו]\u0006 \u0003ליסתכן\u0004 \u0005[יסתכן].\u0006","ועוד מסופר בענין זה, \u0003מר בר רב אשי איצטריך אגודא גמלא\u0004 \u0005[הוצרך\u0006 לנקביו כשהיה מהלך \u0005על הגשר],\u0006 ו\u0003אשתין\u0004 \u0005[והשתין],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003חמתך קאתיא\u0004 \u0005[חמותך באה]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003באודנה\u0004 \u0005[באוזנה]\u0006 הייתי עושה כן. כלומר, כיוון שיש סכנה בדבר, אין אני חושש לכך. ושבים למסופר בברייתא, על אחד שביקש להשתין ולא השתין, ולפי הברייתא, נעשתה כרסו צבה משום כך.","ושואלים: \u0003ותיפוק לי\u0004 \u0005[ושתצא לי,\u0006 יכול אני לומר\u0005]\u0006 שבטנו צבה \u0003משום עלקא\u0004 \u0005[\u0006\u0005עלוקה\u0006 שנכנסה למעיו\u0005]!\u0006 ומשיבים: מדובר היה \u0003בשותת\u0004 מים, שלא יכול היה להטיל מים כדרכו. ואם כן, מחמת קלקול בדרכי השתן היה הדבר.","ובענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שני נקבים יש בו באדם, אחד\u0004 מהם \u0003מוציא שתן ואחד מוציא שכבת זרע, ואין בין זה לזה\u0004 מחיצה \u0003אלא כקליפת השום, בשעה שאדם נצרך\u0004 לנקביו, ועוצר בעצמו, \u0003אם נקבו\u0004 צינור השתן וצינור הזרע \u0003זה לתוך זה\u0004 — \u0003נמצא עקר,\u0004 שמי הרגליים חודרים לאיברי הרבייה.","ועוד בעניין זה מביאים מה ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בפרשת הברכות: \u0003\"לא יהיה בך עקר ועקרה ובבהמתך\"\u0004 (דברים ז, יד), \u0003אימתי לא יהיה בך עקר? בזמן ש\"בבהמתך\",\u0004 שאתה נוהג כבהמה, ומטיל מים כשאתה נצרך לכך, ולא מתאפק.","\u0003אמר ר' יהושע בן לוי\u0004 על אותו פסוק: \u0003\"לא יהיה בך עקר\"\u0004 — כוונתו \u0003מן התלמידים,\u0004 שמי שלא השאיר אחריו תלמידים הריהו כאדם עקר. \u0003\"ועקרה\"\u0004 — \u0003שלא תהא תפלתך עקורה לפני המקום,\u0004 מושלכת הצידה, אלא ישמע לך. ו\u0003אימתי\u0004 לא תהא תפילתך עקורה — \"ובבהמתך\", \u0003בזמן שאתה משים עצמך כבהמה,\u0004 בענוה ושפלות נפש. ומביאים דברים נוספים שאמרו חכמים בענין הטלת מי רגליים.","\u0003אמר רב פפא: לא ישתין אדם מים\u0004 בבבל, אלא על עפר, שבו נספגים המים. אבל \u0003לא על כלי חרס, ולא על מקום קשה,\u0004 מפני שכך אין המים נספגים, אלא זורמים ומגיעים למי התהום. והרי \u0003אמר רב: הני מדורי דבבל מהדרי מיא\u0004 \u0005[אותם המדרונות שבבבל מחזירים,\u0006 מביאים את ה\u0005מים]\u0006 עד \u0003לעין עיטם\u0004 שבארץ ישראל, משם היו מביאים את המים לבית המקדש. ועוד בענין הטלת מים, \u0003אמר אביי: הא איתתא לא תקום להדיא באנפי ינוקא\u0004 \u0005[אשה לא תעמוד\u0006 להטיל מים \u0005ממש בפני ילד],\u0006 אבל אם היא עושה זאת \u0003אגיסא\u0004 \u0005[\u0006כשהיא פונה \u0005הצידה],\u0006 \u0003לית לן בה\u0004 \u0005[אין בזה\u0006 איסור\u0005].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: עמוד\u0004 של צואה \u0003החוזר,\u0004 אדם העושה צרכיו, ועוצר עצמו באמצע — \u0003מביא אדם לידי\u0004 מחלת \u0003הדרוקן. סילון\u0004 של מי רגלים \u0003החוזר\u0004 — \u0003מביא אדם לידי\u0004 מחלת \u0003ירקון. אמר רבה בר רב הונא, אמר רב קטינא אמר ריש לקיש:\u0004 אם \u0003דם רבה\u0004 על האדם, שיש בגופו דם יתר מן הרצוי, ואינו מקיז דם — \u0003שחין רבה\u0004 עליו. אם \u0003שכבת זרע רבה\u0004 עליו, ואינו משמש מטתו — \u0003צרעת רבה\u0004 עליו. אם \u0003צואה רבה\u0004 באדם, שאינו עושה צרכיו — מחלת \u0003הדרוקן רבה,\u0004 אם \u0003מי רגלים רבין\u0004 באדם — \u0003ירקון רבה.\u0004","שנינו במשנה בתוך המומים הפוסלים את הכהן: \u0003רוח קצרית באה עליו.\u0004 ושואלים: \u0003מאי נינהו\u0004 \u0005[מהו זה]?\u0006 \u0003תנא\u0004 \u0005[שנה החכם]:\u0006 \u0003רוח בן נפלים באה עליו,\u0004 כלומר, רוח רעה, של שד, נכנסת בו.","ועוד שנינו: \u0003המאושבן ובעל גבר.\u0004 ובפירוש דבר זה \u0003תנא\u0004 \u0005[שנה החכם]:\u0006 \u0003משובן\u0004 — כוונתו \u0003בביצים,\u0004 שהן גדולות מאד, \u0003ובעל גבר\u0004 — פירושו \u0003בגיד,\u0004 באיבר עצמו, שהוא גדול במיוחד. וכן \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003משובן\u0004 — \u0003זה ה\u0004קרוי \u0003קיין,\u0004 \u0003הגרבתן\u0004 — \u0003זה\u0004 הקרוי \u0003בעל קיק; קיין\u0004 — הרי זה \u0003בביצים, גרבתא\u0004 — \u0003בגיד.\u0004","ושואלים: \u0003ועד כמה\u0004 נקרא גדול, כדי שיהא פסול לעבודה? \u0003מחוי\u0004 \u0005[היה מראה]\u0006 \u0003רב יהודה: עד רכובה,\u0004 עד הברך. וכן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר:\u0004 אם הגיע הגיד \u0003עד רכובה\u0004 — \u0003פסול,\u0004 עד \u0003למעלה מן רכובה\u0004 — \u0003כשר. איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 אם הגיע \u0003עד רכובה\u0004 — \u0003כשר,\u0004 ובכלל זה הרכובה עצמה, \u0003למטה מן הרכובה\u0004 — \u0003פסול.\u0004","כהן ש\u0003אין לו ביצים, או אין לו אלא ביצה אחת\u0004 — \u0003הרי זה \"מרוח אשך\" האמור בתורה\u0004 (ויקרא כא, כ), בין המומים הפוסלים את הכהן לעבודה. \u0003ר' ישמעאל אומר:\u0004 \"מרוח אשך\" הוא \u0003כל שנימוחו\u0004 (נמעכו) \u0003אשכיו. ר' עקיבא אומר: כל שרוח באשכיו,\u0004 שהם נפוחים. \u0003ר' חנינא בן אנטיגנוס אומר:\u0004 \"מרוח אשך\" אינו עוסק באשכים, אלא הכוונה היא ל\u0003כל שמראיו חשוכין,\u0004 שצבע עורו כהה במיוחד.","ומסבירים מדוע פירש כל אחד מן החכמים באופן שונה את הביטוי \"מרוח אשך\". \u0003קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 \u0003לר' ישמעאל:\u0004 אם כפירושם של חכמים, שהכוונה למי שאין לו ביצים, או אין לו אלא ביצה אחת — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"חסר אשך\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לכתוב! ולפיכך \u0003תני\u0004 \u0005[\u0006הוא \u0005שונה]\u0006 כי הכוונה היא למי \u0003שנמרחו אשכיו.\u0004 ועל הסברו של ר' ישמעאל \u0003קשיא ליה\u0004 \u0005[\u0006היה \u0005קשה לו]\u0006 \u0003לר' עקיבא:\u0004 אם במי שנמרחו אשכיו מדובר — \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"ממרוח\u0004 (ממורח) \u0003אשך\" מיבעי ליה\u0004 \u0005[צריך לו]\u0006 לכתוב! לכן \u0003תני\u0004 \u0005[\u0006הוא \u0005שונה]\u0006 \"מרוח אשך\" — \u0003שהרוח באשכיו.\u0004","ועל פירושו של ר' עקיבא \u0003קשיא ליה\u0004 \u0005[\u0006היה \u0005קשה לו]\u0006 \u0003לרבי חנינא בן אנטיגנוס:\u0004 אם כן, \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"רוח אשך\" מיבעי ליה\u0004 \u0005[צריך לו\u0006 לכתוב\u0005]!\u0006 לכן הוא \u0003תני\u0004 \u0005[שונה]\u0006 ומפרש: \u0003שמראיו חשוכין.\u0004 וכיצד הוא מפרש כך? \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי דורשים כתוב זה באופן ש\u0003גורעין\u0004 (מחסרים) אות ממלה אחת \u0003ומוסיפין\u0004 אותה למלה אחרת, \u0003ו\u0004כך \u0003דורשין\u0004 את הכתוב. ולכן במלים \"מרוח אשך\" גורעים את הח' מ\"מרוח\" ואת הא' מ\"אשך\", ומוסיפים את הא' ל\"מר\", ואת הח' ל\"שך\", ודורשים כתוב זה כאילו נכתב \"מראו חשך\".","ושואלים: לפי פירושו של ר' חנינא בן אנטיגנוס, מראיו חשוכין \u0003היינו\u0004 \u0005[הרי זהו]\u0006 \u0003כושי,\u0004 שכבר שנינו להלן בין הפסולים! ומשיבים: \u0003ר' חנינא בן אנטיגנוס לא תני\u0004 \u0005[אינו שונה]\u0006 בין המומים \u0003כושי,\u0004 אלא רק מום זה של מרוח אשך.","ועוד ברשימת הכהנים הפסולים לעבודה: היה כהן ה\u0003מקיש בקרסוליו,\u0004 שרגליו עקומות כלפי פנים, ובזמן הליכה קרסוליו מקישים זה בזה, או שמקיש \u0003בארכבותיו\u0004 (בברכיו), שרגליו עקומות כלפי חוץ, והברכיים נוקשות זו לזו בזמן ההליכה,"],["\u0003ובעל הפיקים,\u0004 ו\u0003העיקל. איזהו העיקל? כל שהוא מקיף פרסותיו\u0004 (מצמיד את כפות רגליו) \u0003ואין ארכבותיו\u0004 (ברכיו) \u0003נוקשות\u0004 \u0003זו לזו,\u0004 מפני שרגליו מעוקלות כלפי חוץ. ועוד פסולים: \u0003פיקה\u0004 (בליטה) \u0003יוצא מ\u0004צד \u0003גודלו, עקיבו יוצא לאחוריו\u0004 ובולט החוצה, \u0003פרסותיו\u0004 (כפות רגליו) \u0003רחבות כשל אווז.\u0004","היו \u0003אצבעותיו\u0004 של ידו או של רגלו \u0003מורכבות זו על זו, או\u0004 שהיו \u0003קלוטות\u0004 (מחוברות) מ\u0003למעלה\u0004 ממקום חיבורן בכף היד או בכף הרגל, \u0003עד הפרק\u0004 האמצעי — \u0003כשר,\u0004 וכן אם היו מחוברות עד \u0003למטה מן הפרק, וחתכה,\u0004 והבדיל בין האצבעות — הרי זה \u0003כשר. היתה בה\u0004 בידו או ברגלו אצבע \u0003יתרת וחתכה, אם יש בה,\u0004 באצבע זו, \u0003עצם\u0004 — הרי זה \u0003פסול\u0004 אפילו לאחר חיתוך, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שהיה זה רק בשר — \u0003כשר.\u0004","\u0003יתר\u0004 שיש אצבע יתירה \u0003בידיו וברגליו,\u0004 שבכל אחת יש \u0003שש ושש\u0004 אצבעות, שבסך הכל הן \u0003עשרים וארבע\u0004 — \u0003ר' יהודה מכשיר, וחכמים פוסלין. השולט בשתי ידיו\u0004 — \u0003רבי פוסל,\u0004 לפי שהוא כאיטר יד, \u0003וחכמים מכשירין.\u0004","בענין המומים ששנינו במשנה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ממה שנאמר בתורה במומי הכהנים \u0003\"שבר רגל\"\u0004 (ויקרא כא, יט) \u0003אין לי\u0004 ללמוד מכאן \u0003אלא\u0004 על \u0003שבר רגל\u0004 ממש, \u0003מנין לרבות הקישן\u0004 (מקיש בקרסוליו ובארכבותיו) \u0003והעיקל והקילבן? תלמוד לומר: \"או שבר רגל\"\u0004 (ויקרא כא, יט), והמלה \"או\" באה לרבות כל מומים שברגל. ועוד בענין מומים שברגל, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בברייתא: \u0003בעל הקיפין והשופנר. אמר ר' חייא בר אבא אמר ר' יוחנן: בעל הפיקין\u0004 — \u0003שיש לו כסתות\u0004 (בליטות) \u0003הרבה\u0004 ברגליו, \u0003שופנר\u0004 — \u0003שאין לו כסתות כל עיקר.\u0004","ועוד שנינו במשנה: \u0003פיקה יוצא מגודלו ועקיבו יוצא לאחוריו. אמר ר' אלעזר:\u0004 עקיבו יוצא לאחריו — כאילו \u0003שוקו יוצא באמצע\u0004 כף \u0003רגלו.\u0004 ועוד שנינו: \u0003פרסותיו רחבות כשל אווז. אמר רב פפא: לא תימא\u0004 \u0005[אל תאמר]\u0006 שהוא מום רק במקרה שפרסתו ממש כשל אווז, \u0003דטריפה ולא סדיקא\u0004 \u0005[שהיא\u0006 גם \u0005שטוחה ודקה ו\u0006גם \u0005אינה סדוקה,\u0006 מפוצלת לאצבעות נפרדות\u0005].\u0006 \u0003אלא כיון דטריפה\u0004 \u0005[ש\u0006היא \u0005שטוחה ודקה]\u0006 ביותר, \u0003אף על גב דסדיקא\u0004 \u0005[אף על פי ש\u0006היא \u0005סדוקה,\u0006 מפוצלת לאצבעות\u0005]\u0006 — הרי זה מום.","ועוד שנינו במשנה: אם היו \u0003אצבעותיו מורכבות זו על גב זו, או קלוטות\u0004 למעלה עד הפרק, או אפילו קלוטות למטה מן הפרק וחתכן — כשר. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר ברשימת המומים \u0003\"שבר יד\"\u0004 (ויקרא כא, יט) — \u0003אין לי אלא שבר יד\u0004 שהוא פוסל, היו","\u0003אצבעות מורכבות למעלה\u0004 זו על גבי זו, \u0003או קלוטות למעלה מן הפרק וחתכן,\u0004 מנין שהוא פסול? תלמוד לומר: \"או שבר יד\". ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 במשנה שאם חתכן \u0003כשר! אלא\u0004 כך צריך לשנות בברייתא: \u0003ולא חתכן, מנין\u0004 שהוא פסול? \u0003תלמוד לומר: \"או שבר יד\".\u0004","שנינו במשנה: \u0003היתה בו\u0004 בידו או ברגלו אצבע \u0003יתרת וחתכה, אם יש בה עצם\u0004 — \u0003פסול,\u0004 אפילו חתכה, מפני שניטל ממנו אבר שלם, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003כשר. אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 מתי נחשבת היתרת כאבר, שאם נחתכה הרי זה פסול — \u0003והוא ש\u0004היתה \u0003נספרת על גבי היד,\u0004 כלומר, שהיתה עומדת בשורה עם שאר האצבעות.","ובענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אצבע \u0003יתירה\u0004 שנחתכה מן המת, \u0003שיש בה עצם, ו\u0004אפילו \u0003אין בה צפורן\u0004 — \u0003מטמא במגע ובמשא\u0004 את הנוגע בה או את הנושא אותה, \u0003ו\u0004כן \u0003מטמא באהל,\u0004 כדין איבר מן המת. \u0003ו\u0004גם אם אין בה בשר, ואין לה דין איבר מן המת — הריהי \u0003עולה למנין מאה עשרים וחמשה,\u0004 שהוא רוב מנין של איברי האדם (מאתיים ארבעים ושמונה), ורוב מנין עצמות המת מטמא באוהל, גם אם אין עליהן בשר כלל. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: ו\u0004מדובר בברייתא זו \u0003ב\u0004עצם ש\u0003נספרת על גב היד,\u0004 ורק אז היא נחשבת כאיבר.","ועוד בענין זה \u0003אמר רב חסדא: דבר זה רבינו הגדול אמרו,\u0004 כלומר, רב (שהיה רבם של אמוראי בבל), \u0003המקום יהיה בעזרו:\u0004 אצבע \u0003יתרת\u0004 של מת \u0003שיש בה עצם ואין בה צפורן\u0004 — \u0003מטמא במגע ובמשא, ו\u0004אולם \u0003אין מטמא באהל. אמר רבה בר בר חנה אמר ר' יוחנן: ו\u0004מתי אמרו שאינה מטמאה באוהל — \u0003בשאינה נספרת על גב היד.\u0004","ועל הלכה זו \u0003אמר ר' יוחנן: עשו\u0004 חכמים \u0003דבריהם כדברי נביאות,\u0004 כלומר, כגזירה משמים, שאין לחפש בה סברה. שכן \u0003מה נפשך\u0004 \u0005[דעתך],\u0006 מאיזה צד אתה רוצה לדון עליה? \u0003אי\u0004 \u0005[אם]\u0006 אצבע שאינה נספרת עם שאר אצבעות \u0003אבר הוא\u0004 — \u0003באהל נמי\u0004 \u0005[גם כן]\u0006 \u0003תטמא, ואי לאו\u0004 \u0005[ואם לא]\u0006 \u0003אבר הוא\u0004 — \u0003במגע ובמשא נמי לא ליטמי\u0004 \u0005[גם כן לא תטמא]!\u0006","\u0003אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: משום עצם כשעורה נגעו בה,\u0004 כלומר, לא דנו בה חכמים דין איבר מן המת, אלא דין עצם כשעורה, שמטמאה במגע ובמשא, אבל לא באוהל.","\u0003רב פפא אמר:\u0004 \u0003גזירה\u0004 היא שגזרו חכמים על אצבע זו \u0003שאינה נספרת\u0004 עם האצבעות, \u0003אטו\u0004 \u0005[משום]\u0006 \u0003נספרת,\u0004 שזו שנספרת נחשבת כאיבר גמור, ומטמאת באוהל. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 זו \u0003שאינה נספרת באהל נמי\u0004 \u0005[גם כן]\u0006 \u0003תטמא!\u0004","ומשיבים: \u0003עבדו רבנן היכירא\u0004 \u0005[עשו חכמים היכר]\u0006 בדברים שגזרו עליהם טומאה, שלא ינהגו בהם כטומאה מן התורה, \u0003כי היכי דלא לישרפו עלייהו\u0004 \u0005[כדי שלא ישרפו עליהם,\u0006 בגללם\u0005]\u0006 \u0003תרומה וקדשים\u0004 שנטמאו על ידם, מפני שאסור לשרוף תרומה וקדשים אלא אם כן נטמאו ממש, בטומאה שמן התורה.","ועוד בעניינו של איבר יתר שבאדם, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]\u0006 במסכת אהלות: \u0003רוב בנינו ורוב מנינו של\u0004 שלד ה\u0003מת, אף על פי שאין בו\u0004 כדי \u0003רובע\u0004 הקב עצמות — \u0003טמאין.\u0004 ועל כך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו רוב בנינו\u0004 של שלד — \u0003שני שוקיים וירך אחד, הואיל ו\u0004הוא \u0003רוב גובהו\u0004 של אדם \u0003ב\u0004אדם \u0003גדול, איזהו רוב מנינו\u0004 — \u0003מאה עשרים וחמשה\u0004 עצמות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: תנא מניינא אתא לאשמועינן\u0004 \u0005[\u0006וכי \u0005התנא חשבון\u0006 \u0005בא להשמיע לנו]?\u0006 והרי כבר שנינו במשנה שיש באדם מאתים ארבעים ושמונה איברים (שבכל אחד מהם עצם)! השיב לו רבא: דבר זה \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא, \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 מת שהוא \u0003חסר, שאין בו אלא מאתים\u0004 איברים, או שהוא \u0003יתר, שיש בו מאתים ושמונים ואחד\u0004 — עצמותיו של אדם זה \u0003כולן עולין למנין מאה עשרים וחמש,\u0004 שאינו מטמא בפחות מכך, גם אם יש בהן רוב מנין איבריו שלו. ואם יש שם מנין זה — הריהו מטמא, גם אם הוא פחות ממחצית מנין עצמותיו. כי \u0003זיל בתר רובא דאינשי\u0004 \u0005[לך אחר רובם של בני האדם],\u0006 ולרוב יש מאתים ארבעים ושמונה איברים.","ועוד בענין מנין איבריו של אדם, \u0003אמר רב יהודה אמר שמואל: מעשה בתלמידיו של ר' ישמעאל ששלקו\u0004 (בישלו) גופת \u0003זונה אחת שנתחייבה שריפה למלך,\u0004 כדי להפריד את הבשר מן העצמות, \u0003בדקו ומצאו בה מאתים וחמשים ושנים\u0004 איברים (שיש בהם עצמות), ותהו על כך שהמספר הוא גדול מזה שאמרו חכמים, מאתים ארבעים ושמונה. \u0003אמר להם\u0004 ר' ישמעאל: \u0003שמא באשה בדקתם, שהוסיף לה הכתוב שני צירים ושני דלתות,\u0004 ולפיכך יש לה ארבעה איברים יתרים על של האיש.","ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: כשם ש\u0004יש \u0003צירים לבית\u0004 — \u0003כך\u0004 יש \u0003צירים לאשה, שנאמר: \"ותכרע ותלד כי נהפכו עליה צריה\"\u0004 (שמואל א ד, יט). \u0003רבי יהושע אומר: כשם שדלתות לבית\u0004 — \u0003כך דלתות לאשה, שנאמר: \"כי לא סגר דלתי בטני\"\u0004 (איוב ג, י), כלומר, הדלתות של בטן אמי, שיצאתי משם.","\u0003ר' עקיבא אומר: כשם שמפתח לבית\u0004 — \u0003כך מפתח לאשה, שנאמר:\u0004 \"וישמע אליה אלהים \u0003ויפתח את רחמה\"\u0004 (בראשית ל, כב). ומתקשים: \u0003ל\u0004דברי \u0003ר' עקיבא קשיא\u0004 \u0005[קשה]\u0006 מן הבדיקה שבדקו \u0003תלמידי ר' ישמעאל,\u0004 שמצאו באותה זונה רק ארבעה איברים יתירים, שהרי צריך להיות עוד אחד, המפתח! ומשיבים: \u0003דלמא איידי דזוטרא אתמוחי מתמח\u0004 \u0005[שמא מתוך שהוא קטן נמוח]\u0006 כששלקו את גופת אותה אשה.","\u0003אמר רב: וכולן,\u0004 כל האיברים היתרים שבאשה — \u0003אין מטמאין באהל, שנאמר\u0004 בענין זה: \u0003\"זאת התורה אדם כי ימות באהל\"\u0004 (במדבר יט, יד), לומר: רק \u0003דבר השוה לכל אדם,\u0004 בין איש ובין אשה, יש לו דין טומאת אוהל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ובאיש ליכא\u0004 \u0005[אין]\u0006 צירים? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בדברי הנביא: \u0003\"צירים אחזוני כצירי יולדה\"\u0004 (ישעיהו כא, ג)! ומשיבים: אותם צירים שמתאר הנביא הם \u0003צירי בשר,\u0004 ואין קוראים איבר אלא לזה שיש בו עצם. ומקשים עוד: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בדברי דניאל: \u0003\"אדני במראה נהפכו צירי\"\u0004 (דניאל י, טז)! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר ב\u0003צירי בשר.\u0004 ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 שצירי האיש צירי בשר הם, \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 \u0003מאתים וארבעים ושמנה\u0004 איברים שמנו חכמים באדם \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006 \u0003לא באיש ולא באשה.\u0004"],["שנינו במשנה: \u0003יתר בידיו וברגליו\u0004 שש ושש עשרים וארבע, ר' יהודה מכשיר וחכמים פוסלים. \u0003אמר ר' יצחק: ושניהם מקרא אחד דרשו,\u0004 שנאמר במלחמות דוד בפלשתים: \u0003\"ותהי עוד מלחמה\u0004 בגת\" (שמואל ב כא, כ), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי איש מדון אצבע ידיו ואצבע רגליו שש ושש\"\u0004 (שמואל ב כא, כ), \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, חכמים, \u0005סבור]:\u0006 \u0003בגנותיה משתעי\u0004 \u0005[בגנותו\u0006 של אותו איש מדון \u0005מספר\u0006 הכתוב\u0005],\u0006 ומכאן שיש בדבר מום. \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה, ר' יהודה, \u0005סבור]:\u0006 \u0003בשבחיה משתעי\u0004 \u0005[בשבחו מספר\u0006 הכתוב\u0005]\u0006 שהיה גדול במדותיו, ואינו מום כלל.","ובפירושו של פסוק זה, \u0003אמר רבה:\u0004 לשם \u0003מה לי דכתיב\u0004 \u0005[\u0006זה \u0005שנאמר]\u0006 שם \u0003\"שש ושש עשרים וארבע מספר\"?\u0004 מדוע הוצרך הכתוב לתיאור מפורט כל כך? \u0003צריכי\u0004 \u0005[צריכים]\u0006 הם כל אותם ביטויים, \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"שש ושש\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003שית דידיה ושית דכרעיה\u0004 \u0005[שש של ידו\u0006 אחת \u0005ושש של רגלו\u0006 האחת\u0005],\u0006 ובסך הכל שתים עשרה — לכן \u0003כתב\u0004 \u0005[כתבה\u0006 התורה\u0005]\u0006 \u0003\"עשרים וארבע\". ואי כתב\u0004 \u0005[ואם היתה\u0006 התורה \u0005כותבת]\u0006 רק \u0003\"עשרים וארבע\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הוא חמש\u0004 אצבעות \u0003מהאי גיסא\u0004 \u0005[מצד זה]\u0006 \u0003ושבע מהאי גיסא\u0004 \u0005[מצד זה],\u0006 ואין האצבעות היתירות מחולקות בשווה בין הידים ובין הרגלים, על כן \u0003כתב\u0004 \u0005[כתבה\u0006 התורה\u0005]:\u0006 \u0003\"שש ושש\",\u0004 שש לכל אחת מידיו ומרגליו. ומה שנאמר שם \u0003\"מספר\"\u0004 כוונתו שמדובר \u0003ב\u0004אצבע יתירה שהיא \u0003נספרת על גבי היד,\u0004 בשורה אחת עם שאר אצבעות.","ובאשר למחלוקת במשנתנו, האם יש בכך מום או לא, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה:\u0004 ראיה לדברי שהוא כשר, \u0003מעשה באדם אחד שבא לפני ר' טרפון\u0004 שהיה \u0003יתר בידיו וברגליו שש ושש עשרים וארבע, אמר לו\u0004 ר' טרפון: \u0003כמותך ירבה בישראל\u0004 אנשים גיבורים! \u0003אמר לו ר' יוסי: משם\u0004 הבאת \u0003ראיה?\u0004 להיפך, \u0003כך אמר לו: כמותך,\u0004 כמו שמועטים אנשים בעלי מום, כמוך, כך \u0003יתמעטו ממזירי ונתיני\u0004 \u0005[ממזרים ונתינים,\u0006 גבעונים\u0005]\u0006 \u0003מישראל.\u0004","שנינו במשנה: \u0003השולט בשתי ידיו,\u0004 רבי פוסל וחכמים מכשירים. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איטר, בין ביד בין ברגל\u0004 — \u0003פסול\u0004 לכהונה. \u0003השולט בשתי ידיו\u0004 — \u0003רבי פוסל וחכמים מכשירין.\u0004 ומסבירים את טעמיהם, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003כחישותא אתחלא\u0004 \u0005[כחישות,\u0006 חולשה, \u0005התחילה]\u0006 \u0003ב\u0004יד \u0003ימין,\u0004 ומשום כך הוא משתמש גם ביד השניה, ולכן הוא פוסלו — בגלל החולשה בידו הימנית, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003בריותא אתחלא\u0004 \u0005[בריות,\u0006 חוזק, \u0005התחילה]\u0006 \u0003ב\u0004יד \u0003שמאל,\u0004 ואין זה מורה על חלישות ביד ימין.","ועוד כהנים פסולים לעבודה: \u0003הכושי, הגיחור, והלבקן, והקפח\u0004 (שיבואר עניינם בגמרא), \u0003והננס, והחרש, והשוטה, והשיכור, ו\u0004כן \u0003בעלי נגעים טהורים,\u0004 נגעי עור, כגון בוהק (ויקרא יג, לט), שאין להם דין צרעת שמטמאת — כל אלה \u0003פסולין באדם וכשרים בבהמה. רבן שמעון בן גמליאל אומר:\u0004 אף \u0003שוטה מן הבהמה אינה מן המובחר. ר' אלעזר אומר: אף בעלי הדלדולין,\u0004 שיש להם חתיכות בשר או עור מידלדלות מגופם, \u0003פסולין באדם וכשרין בבהמה.\u0004","שנינו במשנה: הכושי הגיחור והלבקן. ומבארים: \u0003כושי\u0004 — הרי זה \u0003אוכמא\u0004 \u0005[שחור],\u0006 \u0003גיחור\u0004 — זהו \u0003חיוורא\u0004 \u0005[לבן],\u0006 \u0003לבקן\u0004 — \u0003סומקא\u0004 \u0005[אדום].\u0006 ושואלים: \u0003איני\u0004 \u0005[וכך הוא]?\u0006 \u0003והא ההוא דאמר להו\u0004 \u0005[והרי היה\u0006 אחד \u0005שאמר להם]\u0006 לאנשים: \u0003מאן בעי\u0004 \u0005[מי רוצה]\u0006 טלה \u0003לוקיאני, ואישתכח חיוורא\u0004 \u0005[ונמצא\u0006 שהיה בצבע \u0005לבן]!\u0006 \u0003אלא\u0004 כך צריך לומר: \u0003כושי\u0004 הוא \u0003אוכמא\u0004 \u0005[שחור],\u0006 \u0003גיחור\u0004 — \u0003סומקא\u0004 \u0005[אדום],\u0006 \u0003כדאמרי אינשי\u0004 \u0005[כמו שאומרים אנשים]\u0006 על אדם שהוא \u0003\"סומקא גיחיא\"\u0004 \u0005[אדום מאד],\u0006 \u0003לבקן\u0004 — \u0003חיוורא\u0004 \u0005[לבן]\u0006 הוא, \u0003כההוא דאמר להו\u0004 \u0005[כמו זה שאמר להם]\u0006 לאנשים: \u0003\"מאן בעי\u0004 \u0005[מי רוצה]\u0006 \u0003לוקיאני\" ואישתכח חיוורי\u0004 \u0005[ונמצא שהיו לבנים].\u0006","שנינו במשנה: \u0003קפח.\u0004 בפירוש דבר זה \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב זביד: גבוה.\u0004 ותוהים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 האם להיות גבוה ביותר הוא מום? \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' אבהו: מנין שהקדוש ברוך הוא משתבח בבעלי קומה\u0004 — \u0003שנאמר: \"ואנכי השמדתי את האמרי מפניהם אשר כגבה ארזים גבהו\"\u0004 (עמוס ב, ט)! \u0003אמר רב פפא:\u0004 לא מדובר במשנה במי שגבוה ובנוי כהוגן, אלא \u0003באריכא שמיטה סניא\u0004 \u0005[ב\u0006מי \u0005שארוך, שמוט ומכוער],\u0006 שהוא רזה ודק שלא כרגיל.","ובעניינים אלה מביאים מה ש\u0003אמר ריש לקיש:\u0004 מי שהוא \u0003גבוה לא ישא גבוהית\u0004 — \u0003שמא יצא מהן תורן\u0004 (איש גבוה ביותר), וכן \u0003ננס לא ישא ננסת\u0004 — \u0003שמא יצא מהם אצבעי\u0004 (איש קטן ביותר), \u0003לבן\u0004 (איש בהיר) \u0003לא ישא לבנה\u0004 — \u0003שמא יצא מהם בוהק\u0004 (לבן ביותר), \u0003שחור\u0004 (כהה) \u0003לא ישא שחורה\u0004 — \u0003שמא יצא מהן טפוח\u0004 (שחור כטפיח=קדירה).","ועוד שנינו ברשימת הכהנים הפסולים: \u0003החרש השוטה והשכור.\u0004 ושואלים: הלא \u0003שכור מחיל\u0004 \u0005[מחלל]\u0006 \u0003עבודה,\u0004 אם הוא עובד בעודו שיכור, ואם כן \u0003בהדי מומי דמחילי עבודה בעי למיחשב\u0004 \u0005[ביחד עם מומים שמחללים עבודה היה צריך להחשיב אותם],\u0006 ולא בין הפסולים השנויים במשנה זו, שהם פסולים מפני שאינם \"שווים בזרעו של אהרן\", שהם משונים משאר אנשים, שאמנם אסור להם לעבוד אבל בדיעבד עבודתם כשרה (ראה לעיל מג,ב)!","ומשיבים: מדובר כאן בשיכור \u0003בשאר דברים המשכרים,\u0004 שאינם יין, והוא אינו מחלל את עבודתו. ומעירים: \u0003ו\u0004משנתנו היא ש\u0003לא כ\u0004שיטת \u0003ר' יהודה,\u0004 הסבור שגם שיכור כזה מחלל עבודה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 ר' יהודה אומר: מי ש\u0003אכל דבילה קעילית\u0004 (מאיזור העיר קעילה) הגורמת לשכרון, \u0003ו\u0004כן אם \u0003שתה חלב או דבש,\u0004 ונשתכר, ו\u0003נכנס למקדש\u0004 — \u0003חייב\u0004 מלקות, שעבר על מצות לא תעשה, שנאמר לאהרן: \"יין ושכר אל תשת אתה ובניך אתך בבואכם אל אהל מועד\" (ויקרא י, ט), וכל דבר שמשכר הריהו בכלל \"שכר\". וכהן שנשתכר מחלל עבודתו, כפי שנאמר מיד אחר כך: \"ולהבדיל בין הקדש ובין החול\" (ויקרא י, י), ששתיית יין ושכר עושה את הקודש חול.","\u0003אלו כשרין\u0004 לעבודה \u0003באדם ופסולין בבהמה\u0004 להקרבה: אותו ואת בנו, שאסור להקריב את הבן ביום שנשחטה אמו, ולהיפך. מי שהיה \u0003טריפה,\u0004 שנחבל או חלה וסופו למות מחמת כך, \u0003ויוצא דופן,\u0004 שנולד בניתוח דרך דופן הרחם, \u0003ושנעבדה בהן עבירה\u0004 (שנרבעו על ידי אדם או רבעו אדם), \u0003ושהמית את האדם.\u0004","\u0003ו\u0004כהן \u0003הנושא נשים בעבירה,\u0004 כגון שנושא גרושה או חלוצה — \u0003פסול עד שידירנה הנאה,\u0004 שיאסור עצמו בנדר מליהנות ממנה. \u0003ו\u0004הכהן \u0003המטמא למתים פסול\u0004 מלעבוד \u0003עד שיקבל עליו שלא יהא מטמא למתים.\u0004","שנינו במשנה: \u0003ואלו כשירין באדם\u0004 ופסולים בבהמה — אותו ואת בנו. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 ההבדל ששנינו \u0003ב\u0004עניין \u0003\"אותו ואת בנו\"?\u0004 באיזו מציאות מדובר?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כגון \u0003אהרן ובניו\u0004 שמותרים לעבוד במקדש באותו יום, \u0003דכותיה\u0004 \u0005[שכמותו]\u0006 נאסר להקריב ביום אחד \u0003תייש ובנו,\u0004 \u0003מי נהיג\u0004 \u0005[האם נוהג\u0006 בבהמה איסור זה\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 \u0005ברייתא\u0006\u0005]:\u0006 \u0003\"אותו ואת בנו\"\u0004 — \u0003נוהג בנקבות,\u0004 כלומר, באם ובבנה או בתה, \u0003ואינו נוהג בזכרים,\u0004 באב ובבנו או בתו! \u0003אלא\u0004 תאמר שמדובר ב\u0003תיישה ובנה,\u0004 שאסור לשוחטם ביום אחד, \u0003דכוותה הכא\u0004 \u0005[שכמותה כאן],\u0006 לענין פסול כהונה, מדובר ב\u0003כהנת ובנה,\u0004 וכי \u0003כהנת בת עבודה היא?\u0004","ומשיבים: \u0003לעולם\u0004 מדובר על \u0003אהרן ובניו, דכוותה הכא\u0004 \u0005[שכיוצא בו כאן]\u0006 \u0003תייש ובנו.\u0004 ואף ששנינו בברייתא ש\"אותו ואת בנו\" אינו נוהג בזכרים, אמרי במערבא משמיה \u0005[אומרים בארץ ישראל משמו]\u0006 של \u0003ר' יוסי בר אבין: עדא אמרה\u0004 \u0005[זאת אומרת]\u0006 כי משנתנו שיטת \u0003חנניה היא,\u0004 הסבור שאיסור אותו ואת בנו נוהג בזכרים. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"אותו ואת בנו\" נוהג בנקבות ואינו נוהג בזכרים,\u0004 ואילו \u0003חנניה אומר: נוהג בזכרים ובנקבות.\u0004","שנינו במשנה: \u0003והנושא נשים\u0004 בעבירה — פסול עד שידירנה הנאה. ועל כך \u0003תנא\u0004 \u0005[שנה החכם]:\u0006 כהן העובד, ונתברר כי הוא נושא אשה בעבירה — אינו מפסיק מעבודתו, אלא \u0003נודר\u0004 ממנה הנאה \u0003ועובד\u0004 עבודה, ומשסיים לעבוד, \u0003יורד\u0004 מהמזבח \u0003ומגרש\u0004 את האשה.","ושואלים: ומדוע נתיר לו לעבוד קודם שיגרשנה? \u0003וליחוש דלמא אזיל לגבי חכם ושרי ליה\u0004 \u0005[ונחשוש שמא ילך אצל החכם ויתיר לו\u0006 את נדרו\u0005]!\u0006 ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 התנא שהנשאל לחכם שיתיר את נדרו — \u0003צריך לפרט את הנדר,\u0004 וכשיפרט כהן זה את הנדר, ויאמר שנדר כן משום שהיא אשה שאסורה עליו — לא יתיר לו החכם.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שהנשאל לחכם \u0003צריך לפרט את הנדר. אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אין צריך לפרט את הנדר, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע יכול להמשיך ולעבוד קודם שגירש את אשתו? ומשיבים: \u0003דמדרינן ליה\u0004 \u0005[שמדירים אותו]\u0006 \u0003ברבים,\u0004 במעמד רבים, ונדר כזה לא ניתן להתיר.","ואומרים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003נדר שהודר ברבים אין לו הפרה,\u0004 כלומר, התרה על ידי חכם, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003יש לו הפרה מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003דמדרינן\u0004 \u0005[שמדירים]\u0006"],["\u0003ליה\u0004 \u0005[אותו]\u0006 על \u0003דעת רבים.\u0004","\u0003אמר אמימר: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005],\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003נדר שהודר ברבים יש לו הפרה,\u0004 נדר שהודר \u0003על דעת הרבים אין לו הפרה.\u0004 ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 כאשר בא לבקש התרה \u0003ל\u0004צורך \u0003דבר הרשות, אבל\u0004 אם רוצה להתיר \u0003לדבר מצוה\u0004 — \u0003יש לו הפרה\u0004 אפילו הודר על דעת רבים, \u0003כי ההוא דמקרי דרדקי\u0004 \u0005[כמו\u0006 אותו מעשה \u0005של מלמד תינוקות],\u0006 \u0003אדריה\u0004 \u0005[\u0006ש\u0005הדיר אותו]\u0006 \u0003רב אחא\u0004 מללמד, על דעת הציבור, מפני \u0003דקא פשע בינוקי\u0004 \u0005[שהיה פושע בתינוקות]\u0006 ומכה אותם, \u0003ואהדריה\u0004 \u0005[והחזיר אותו]\u0006 \u0003רבינא\u0004 לתפקידו, \u0003דלא אשכח דהוה דייק כוותיה\u0004 \u0005[\u0006מפני \u0005שלא נמצא מי שהיה מדייק כמותו].\u0006","שנינו במשנה: \u0003והמטמא למתים\u0004 פסול לעבודה עד שיקבל עליו שלא ייטמא יותר. ושואלים: \u0003מאי שנא הכא דסגי ליה\u0004 \u0005[במה שונה כאן שדי לו]\u0006 \u0003בקבלה\u0004 כדי שיוכל לעבוד, \u0003ומאי שנא התם דמדרינן ליה\u0004 \u0005[ומה שונה שם,\u0006 בענין נושא אשה בעבירה, \u0005שמדירים אותו]\u0006 קודם שיוכל לעבוד? ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 ביחס לאשה \u0003יצרו תקפו,\u0004 ומכיון שיש בכך יצר — לא די לא בקבלה בלבד, אלא צריך גם לנדור נדר.","","\u0003יש\u0004 אדם שהוא \u0003בכור לנחלה\u0004 שיורש פי שנים בנחלת אביו, \u0003ואינו בכור ל\u0004ענין \u0003כהן,\u0004 שאין צריך לפדות אותו; ויש מי שהוא \u0003בכור לכהן ואינו בכור לנחלה;\u0004 יש שהוא \u0003בכור לנחלה ולכהן, ויש ש\u0004הוא הגדול שבבנים ובכל זאת \u0003אינו בכור לא לנחלה ולא לכהן.\u0004","ומפרטים: \u0003איזהו בכור לנחלה ואינו בכור לכהן? הבא אחר נפלים,\u0004 שנולד לאחר נפל, עובר שלא נגמרה התפתחותו, \u0003אף על פי שיצא\u0004 (שהוציא) הנפל \u0003את ראשו\u0004 \u0003חי,\u0004 או שבא לאחר \u0003בן תשעה\u0004 חדשים, שכבר נגמרה התפתחותו, אלא \u0003שיצא ראשו מת,\u0004 שאלו אינם חשובים לאביהם כבכור לרשת נחלה, ולכן הבא אחריהם נחשב בכור לענין זה. אבל לענין פדיון הבן — אינו בכור, לפי שאינו \"פטר רחם\", שלא יצא ראשון מרחם אמו. וכן אשה \u0003המפלת כמין בהמה חיה ועוף,\u0004 בן הנולד לה לאחר מכן הריהו בכור לנחלה, אבל לא לכהן, מפני שאינו \"פטר רחם\" — אלו \u0003דברי ר' מאיר,\u0004 \u0003וחכמים אומרים:\u0004 אין הראשון פוטר את הבא אחריו מן הפדיון \u0003עד שיהא בו מצורת אדם,\u0004 ואם לא היה בצורת אדם אינו נחשב לולד, להחשיבו כ\"פטר רחם\". \u0003המפלת\u0004 חתיכה כמין \u0003סנדל\u0004 (ולד חסר צורה), \u0003או\u0004 מפלת \u0003שליא,\u0004 מעין כיס שהעובר מצוי בתוכו ברחם אמו, בלא ולד, \u0003או\u0004 שהפילה \u0003שפיר\u0004 (עובר) \u0003מרוקם,\u0004 שניכרת בו צורת ולד, \u0003ו\u0004כן ולד \u0003היוצא מחותך,\u0004 מפני שסיכן את אמו, או מפני שלא הצליחו לילד את אמו — הבא אחריהם הוא \u0003בכור לנחלה,\u0004 מפני שהראשונים אינם נחשבים כבכור לאב לרשת נחלה, \u0003ואין בכור לכהן,\u0004 מפני שאינו \"פטר רחם\".","","\u0003מי שלא היו לו בנים, ונשא אשה שכבר ילדה,\u0004 הבן הראשון שנולד להם הוא בכור לנחלה, מפני שהוא בן ראשון לאב, ואינו בכור לכהן שהרי אינו \"פטר רחם\". וכן אם נשא אשה אשר ילדה ב\u0003עודה שפחה\u0004 כנענית \u0003ונשתחררה,\u0004 או שילדה ב\u0003עודה נכרית ונתגיירה,\u0004 ו\u0003משבאת לישראל ילדה\u0004 בן — הריהו \u0003בכור לנחלה,\u0004 שהרי הוא בכור לאביו, \u0003ואין בכור לכהן,\u0004 שהרי אינו \"פטר רחם\". \u0003ר' יוסי הגלילי אומר:\u0004 ולד כזה הוא \u0003בכור לנחלה ולכהן, שנאמר: \"פטר רחם בישראל\"\u0004 (ראה שמות יג, ב) — שאין הנולדים תחילה לאמם נחשבים כ\"פטר רחם\" \u0003עד שיפטרו רחם מישראל,\u0004 ומה שילדה אשה בגויותה אינו נחשב \"פטר רחם\" לענין זה.","","\u0003מי שהיו לו בנים ונשא אשה שלא ילדה,\u0004 וכן אשה ש\u0003נתגיירה\u0004 כשהיא \u0003מעוברת,\u0004 או \u0003נשתחררה\u0004 כשהיא \u0003מעוברת,\u0004 וילדה — הולד בכור לכהן, מפני שהוא ראשון לאמו, אבל אינו בכור לנחלה, מפני שכבר נולדו בנים לאביו, או מפני שאין לו אב (כשנתגיירה אמו). \u0003ו\u0004כן מי ש\u0003ילדה\u0004 במקום אחד \u0003היא\u0004 \u0003וכהנת, היא ולויה, היא ואשה שכבר ילדה,\u0004 שבניהם פטורים מפדיון הבן, ונתערבו, ואין ידוע של מי כל ולד, \u0003וכן מי שלא שהתה לאחר\u0004 שמת \u0003בעלה\u0004 \u0003שלשה חדשים, ונשאת\u0004 לאדם אחר \u0003וילדה\u0004 בן בכור לאמו, \u0003ואינו ידוע אם\u0004 הילד הזה הוא \u0003בן תשעה\u0004 חדשים \u0003לראשון, אם בן שבעה לאחרון\u0004 — בכל הספקות האלו הרי זה \u0003בכור לכהן,\u0004 שהרי הוא \"פטר רחם\", \u0003ואינו בכור לנחלה,\u0004 מפני שעליו להביא ראיה שהוא הבן הראשון של אביו, כדי ליטול את חלק הבכורה, ואין בידו להוכיח את הדבר.",""],["\u0003אמר שמואל: אין הראש פוטר בנפלים,\u0004 יציאת ראשו של נפל מן הרחם בלא גופו — אינה נחשבת כלידה, לפטור את הבא אחריו מפדיון, וכגון שהחזיר ראשו ויצא אחיו התאום.","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 נאמר: \u0003\"כל אשר נשמת רוח חיים באפיו\"\u0004 (בראשית ז, כב), ומכאן יש ללמוד כי \u0003כל היכא\u0004 \u0005[היכן]\u0006 ש\u0003נשמת רוח חיים באפיו,\u0004 שהוא בן קיימא — הוא דחשיב רישיה \u0005[שנחשב ראשו],\u0006 \u0003אידך\u0004 \u0005[אחר],\u0006 נפל, שאינו בן קיימא — \u0003לא חשיב רישיה\u0004 \u0005[נחשב ראשו].\u0006","ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הבא אחר נפלים, שיצא ראשו\u0004 של הנפל \u0003חי, ו\u0004כן נולד לפניו \u0003בן תשעה שיצא ראשו מת\u0004 — בכור לנחלה ואינו בכור לכהן. ואף שהמשנה עוסקת גם בבן תשעה, \u0003קתני מיהא\u0004 \u0005[\u0006הריהו \u0005שונה על כל פנים]\u0006 לגבי נפל ש\u0003ראשו\u0004 פוטר את הבא אחריו! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ראשו?\u0004 כוונתו: ראשו וכן \u0003רובו.\u0004","ומקשים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 במפורש \u0003רובו!\u0004 ומשיבים: \u0003בדין הוא דאיבעי ליה למיתני\u0004 \u0005[שהיה צריך לשנות]\u0006 \u0003רובו, ואיידי דקא בעי למיתני סיפא\u0004 \u0005[ומתוך שרצה לשנות בסוף]\u0006 \u0003בן תשעה שיצא ראשו מת,\u0004 כדי לדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003ראשו מת\u0004 הבא אחריו בכור לנחלה, \u0003הא\u0004 \u0005[אבל]\u0006 אם יצא בן תשעה ו\u0003ראשו חי\u0004 — \u0003הבא אחריו בכור לנחלה נמי לא הוי\u0004 \u0005[גם כן איננו]\u0006 — \u0003תנא רישא נמי\u0004 \u0005[שנה בהתחלה,\u0006 לגבי נפל, \u0005גם כן]\u0006 \u0003ראשו.\u0004","ומקשים על הסבר זה: \u0003ומאי קא משמע לן\u0004 \u0005[ומה\u0006 הוא \u0005משמיע לנו בזה]?\u0006 \u0003דכיון דמפיק ליה רישיה\u0004 \u0005[שכיון שמוציא\u0006 ולד \u0005את ראשו]\u0006 \u0003הוה\u0004 \u0005[הרי זו]\u0006 \u0003לידה?\u0004 והלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה במשנה לגבי עובר בהמה: \u0003הוציא ראשו\u0004 קודם שנשחטה אמו, \u0003אף על פי שהחזירו\u0004 — \u0003הרי זה כילוד,\u0004 ואין דינו כעובר, ששחיטת אמו מתירה אותו באכילה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אשמועינן\u0004 \u0005[השמיע לנו]\u0006 הלכה זו ב\u0003בהמה, וקא משמע לן\u0004 \u0005[ומשמיע לנו]\u0006 במשנתנו דין זה \u0003באדם.\u0004 ויש צורך בזה ובזה, כי \u0003אדם מבהמה לא יליף\u0004 \u0005[אינו נלמד],\u0006 משום שהבהמה \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה פרוזדור,\u0004 אין פתח הרחם שלה מוסתר כמו באשה, ולכן יש לומר כי דווקא בבהמה, שהראש מתגלה מיד ביציאתו נחשבת הדבר ללידה, אבל לא באשה.","וכן מצד אחר, \u0003בהמה מאדם לא ילפא\u0004 \u0005[אינה נלמדת]\u0006 \u0003משום דחשיב\u0004 \u0005[שחשוב]\u0006 \u0003פרצוף פנים דידיה\u0004 \u0005[שלו],\u0006 ולכן יציאת הראש לעצמה נחשבת לידה, מה שאין כן בבהמה.","והלא \u0003הא נמי תנינא\u0004 \u0005[זו\u0006 באדם \u0005גם כן\u0006 כבר \u0005שנינו\u0006 במשנה\u0005]:\u0006 אם \u0003יצא\u0004 הולד \u0003כדרכו\u0004 כדרך לידה רגילה, שהראש יוצא תחילה — \u0003משיצא רוב ראשו\u0004 הרי הוא כילוד. \u0003ואיזהו רוב ראשו? משתצא פדחתו\u0004 (מצחו). ונמצא שלא הוצרכה המשנה לדין ראשו של בן תשעה! ואם כן, מה ששנינו שראשו של נפל פוטר את הבא אחריו, הרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003שמואל,\u0004 שטען כי אין הראש פוטר בנפלים. ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","ובאותו ענין \u0003אמר ר' שמעון בן לקיש:\u0004 יציאת \u0003פדחת\u0004 לבדה באדם \u0003פוטרת,\u0004 נחשבת כלידה \u0003בכל מקום, חוץ מן הנחלה,\u0004 שאם הוציא ולד רק את פדחתו, והחזיר ראשו, ויצא אחיו — השני הוא הבכור לנחלה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"יכיר\"\u0004 \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 לענין נחלה: \"כי את הבכור... יכיר לתת לו פי שניים\" (דברים כא, יז), ואין הכרה על ידי פדחת לבדה. \u0003ור' יוחנן אמר: אפילו לנחלה\u0004 די בכך.","ומסבירים: מה שאמר ריש לקיש \"פוטרת \u0003בכל מקום\" לאיתויי מאי\u0004 \u0005[להביא\u0006 להוסיף, \u0005את מה\u0006 הוא בא\u0005]\u0006 מלבד לענין פדיון הבן — \u0003לאיתויי הא דתנו רבנן\u0004 \u0005[להביא את זו ששנו חכמים]:\u0006 \u0003גיורת שיצאה פדחת ולדה\u0004 בלבד \u0003בגיותה, ואחר כך נתגיירה\u0004 וילדה את הולד כולו — \u0003אין נותנין לה ימי טומאה וימי טהרה\u0004 של יולדת ישראלית, \u0003ו\u0004כן \u0003אינה מביאה קרבן לידה,\u0004 משום שהולד נחשב כנולד בעודה גויה.","על דברי ר' יוחנן \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003\"יכיר\"\u0004 — \u0003זו הכרת פנים, ואיזו היא הכרת פנים? פרצוף פנים עם החוטם.\u0004 הרי שלא די בפדחת בלבד! ומשיבים, \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"עד החוטם\",\u0004 ואין החוטם בכלל. ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת, ממה ששנינו: \u0003אין מעידים\u0004 על אדם שמת, כדי להתיר את אשתו להינשא, \u0003אלא על\u0004 פי עדים שהכירוהו, על פי \u0003פרצוף פנים עם החוטם!\u0004 ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 גם כאן: \u0003\"עד החוטם\".\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בענין זה: אנשים שראו \u0003פדחת\u0004 של אדם שמת \u0003בלא פרצוף פנים, פרצוף פנים בלא פדחת\u0004 — \u0003אין מעידין\u0004 עליו שמת, להתיר את אשתו, \u0003עד שיהו שניהם עם החוטם. ו\u0004על כך \u0003אמר אביי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב כהנא: מאי קראה\u0004 \u0005[מה הכתוב]\u0006 המלמד על כך? שנאמר: \u0003\"הכרת פניהם ענתה בם\"\u0004 (ישעיהו ג, ט), ואין הכרת פנים בלא חוטם! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עדות אשה\u0004 להתירה להינשא, \u0003דאחמירו בה רבנן\u0004 \u0005[שהחמירו בה חכמים],\u0006 מפני שיש בה התרת אשת איש לכל העולם, וחשש ממזרות, ולכן הצריכו בה בירור מעולה, אבל לדיני בכור — די בהכרה כל שהיא, בפדחת.","ושואלים: \u0003ומי אחמירו\u0004 \u0005[והאם החמירו]\u0006 חכמים בעדות אשה? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 להיפך: \u0003הוחזקו\u0004 חכמים \u0003להיות משיאים\u0004 אשה שהעידו שמת בעלה, על פי עדות שאינה כשרה בדרך כלל, כגון \u0003עד מפי עד\u0004 אחר שראהו מת, וכן \u0003מפי אשה, מפי עבד, מפי שפחה!\u0004 ומשיבים: \u0003כי אקילו רבנן\u0004 \u0005[כאשר הקלו חכמים]\u0006 הרי זה \u0003בסופה\u0004 של העדות, לקבל את העדות שהאיש מת. אבל \u0003בתחלתה,\u0004 בעצם הבירור, האם הכירו העדים היטב את המת כשראוהו — \u0003לא אקילו רבנן\u0004 \u0005[הקילו\u0006 בה \u0005חכמים].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 דרך אחרת ליישב את דברי ר' יוחנן:"],["\u0003\"יכיר\"\u0004 שנאמר לענין בכור לנחלה הוא ענין \u0003לחוד, והכרת פנים\u0004 הוא ענין \u0003לחוד.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בבעיה הבאה: \u0003היו לו בנים בגיותו ונתגייר\u0004 — \u0003ר' יוחנן אומר: אין לו בכור לנחלה,\u0004 כלומר, בנו הראשון הנולד בישראל אינו נחשב בכור, ליטול פי שנים בנכסי אביו. \u0003ור' שמעון בן לקיש אומר: יש לו בכור לנחלה.\u0004 ומבארים את השיטות: \u0003ר' יוחנן אומר: אין לו בכור לנחלה\u0004 — \u0003דהא הוה ליה\u0004 \u0005[שהרי\u0006 כבר \u0005היה לו]\u0006 בן שהוא \u0003ראשית אונו,\u0004 ובענין נחלה נאמר: \"כי הוא ראשית אונו לו משפט הבכורה\" (דברים כא, יז). \u0003ור' שמעון בן לקיש אומר: יש לו בכור לנחלה,\u0004 כי \u0003גר שנתגייר כקטן שנולד דמי\u0004 \u0005[נחשב],\u0006 כאדם חדש, שזהו בנו הראשון.","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והולכים\u0006 הם \u0005לשיטתם],\u0006 שנחלקו בענין דומה, \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003היו לו בנים בגיותו ונתגייר\u0004 — \u0003ר' יוחנן אמר: קיים\u0004 בבנים אלה מצות \u0003פריה ורביה, ור' שמעון בן לקיש אמר: לא קיים.\u0004 ומבארים, \u0003ר' יוחנן אמר: קיים\u0004 בכך את הציווי הכללי \u0003\"לא תהו בראה לשבת יצרה\"\u0004 (ישעיהו מה, יח), שהוסיף בישוב העולם, וכבר יצא ידי חובתו. \u0003ור' שמעון בן לקיש אמר: לא קיים פריה ורביה,\u0004 כי \u0003גר שנתגייר כקטן שנולד דמי\u0004 \u0005[נחשב].\u0006","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שתיאמר המחלוקת בשני המקרים, \u0003דאי איתמר בהא קמייתא\u0004 \u0005[שאם היתה נאמרת\u0006 רק \u0005בזו הראשונה]\u0006 לענין נחלה, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' שמעון בן לקיש,\u0004 שהבן הנולד ראשון בישראל הוא בכור לנחלה, \u0003משום\u0004 ש\u0003בגיותן לאו\u0004 \u0005[לא] בני נחלה נינהו\u0006 \u0005[הם],\u0006 \u0003אבל בהא\u0004 \u0005[בזו]\u0006 במצות פריה ורביה, \u0003אימא מודה ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לר' יוחנן\u0004 שקיים פריה ורביה, שהרי נאמר: \u0003\"לא תהו בראה לשבת יצרה\", והא עבד ליה\u0004 \u0005[והרי כבר עשה לו]\u0006 מצות \u0003שבת.\u0004","ולהיפך, \u0003ואי איתמר בהא\u0004 \u0005[ואם\u0006 היה \u0005נאמר\u0006 רק \u0005בזו]\u0006 בענין פריה ורביה, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו\u0006 דוקא \u0005אומר]\u0006 \u0003ר' יוחנן\u0004 שקיים פריה ורביה, מפני שקיים \"לשבת יצרה\", \u0003אבל בהא\u0004 \u0005[בזו]\u0006 בענין נחלה, \u0003אימא מודה ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לר' שמעון בן לקיש\u0004 שאין מתחשבים בבנים שילד בגיותו, על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 שתיאמר המחלוקת בשני המקרים. ומקשים על שיטת ר' יוחנן.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מי שלא היו לו בנים, ונשא אשה שכבר ילדה\u0004 ב\u0003עודה שפחה ונשתחררה\u0004 לאחר מכן, או שילדה ב\u0003עודה גויה ונתגיירה, ומשבאתה לישראל ילדה\u0004 — \u0003ולדה בכור לנחלה ואינו בכור לכהן.\u0004","ונברר: אותה שפחה וגיורת, שבנה שילדה בישראל הוא בכור לנחלה, \u0003ילדה ממאן\u0004 \u0005[ממי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שילדה \u0003מישראל שלא היו לו בנים,\u0004 שבו עוסקת המשנה מתחילה — \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע מדובר דוקא ב\u0003גיורת ושפחה? אפילו בת ישראל\u0004 שכבר ילדה \u0003נמי\u0004 \u0005[גם כן]\u0006 הדין כן!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר במשנה בשני מקרים שונים: בתחילה — במי שהיו לו בנים ונשא בת ישראל שכבר ילדה, והמקרה השני — במי שילדה בעודה שפחה או גויה, ומשבאתה לישראל ילדה ממי שהוא כמותה, \u0003מגר שהיו לו בנים ונתגייר; וקתני\u0004 \u0005[\u0006הרי הוא \u0005שונה]\u0006 שהוא \u0003בכור לנחלה,\u0004 שלא כדברי ר' יוחנן!","ודוחים: \u0003לא, לעולם\u0004 תפרש שילדה \u0003מישראל שלא היו לו בנים,\u0004 ומה שהוזכרו דוקא גיורת ושפחה — לא לענין נחלה הובא, אלא מה ששנינו \u0003\"ואינו בכור לכהן\" איצטריכא ליה\u0004 \u0005[הוצרך לו],\u0006 כדי","\u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יוסי הגלילי,\u0004 שחלק על כך במשנתנו ו\u0003אמר:\u0004 ילד זה הוא \u0003בכור לנחלה ולכהן, שנאמר: \"פטר רחם בישראל\"\u0004 (ראה שמות יג, ב) — שאין הנולדים תחילה נחשבים \"פטר רחם\" \u0003עד שיפטרו\u0004 (יפתחו) \u0003רחם מישראל,\u0004 ומה שילדה בגויותה אינו נחשב, על כן \u0003קא משמע לן דלא\u0004 \u0005[משמיע לנו\u0006 התנא \u0005שלא\u0006 כדבריו\u0005],\u0006 אלא כיון שכבר ילדה בגויותה — אין זה \"פטר רחם\".","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מן הברייתא שלא כר' יוחנן: \u0003היו לו בנים בגיותו ונתגייר,\u0004 ונולדו לו בנים — \u0003יש לו בכור לנחלה! אמר רבינא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב אחא: הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003ודאי\u0004 שיטת \u0003ר' יוסי הגלילי הוא,\u0004 ש\u0003אמר\u0004 לענין פדיון הבן: \u0003\"פטר רחם בישראל\"\u0004 — \u0003עד שיפטרו רחם מישראל, ויליף איהו\u0004 \u0005[ולמד הוא]\u0006 הגוי שנתגייר, \u0003מינה דידה\u0004 \u0005[ממנה]\u0006 מגיורת, שאין מתחשבים במה שילדו קודם שנתגיירו.","\u0003אמר רב אדא בר אהבה: לוייה שילדה\u0004 — \u0003בנה פטור מחמש סלעים\u0004 של פדיון הבן. ושואלים: \u0003דאיעבר ממאן\u0004 \u0005[שהתעברה ממי]?\u0006 \u0003אילימא דאיעבר\u0004 \u0005[אם תאמר שהתעברה]\u0006 \u0003מכהן\u0004 או \u0003מלוי, מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע מדובר דוקא ב\u0003לוייה? אפילו ישראלית נמי\u0004 \u0005[גם כן]\u0006 פטורה, שהרי הבן עצמו כהן או לוי!","אלא תאמר \u0003דאיעבר\u0004 \u0005[שהתעברה]\u0006 הלויה \u0003מישראל\u0004 — גם זה תמוה, מדוע הולכים אחר האם? הלא \u0003\"למשפחתם לבית אבתם\"\u0004 (במדבר א, ב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 שאין יחוס המשפחה בישראל אלא אחר האב ולא אחר האם!","\u0003אמר רב פפא:\u0004 צריכים לומר \u0003דאיעבר\u0004 \u0005[שהתעברה]\u0006 \u0003מגוי,\u0004 ובמקרה זה הולכים אחר האם, ובן לויה פטור מחמש סלעים. \u0003ולא תימא אליבא דמאן דאמר\u0004 \u0005[ולא תאמר ש\u0006דבר זה נכון \u0005על פי\u0006 שיטתו \u0005של מי שאומר]\u0006 \u0003אין מזהמין את הולד,\u0004 כלומר, אין מייחסים כלל את הולד לאביו הגוי, והוא כשר. \u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מזהמין את הולד,\u0004 ומייחסים אותו גם לאב, על כל פנים הולכים אחר אמו, ו\u0003לוי פסול מיקרי\u0004 \u0005[נקרא],\u0006 ופטור מפדיון.","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 הסבר אחר: \u0003לעולם\u0004 תפרש \u0003דאיעבר\u0004 \u0005[שהתעברה]\u0006 לויה זו \u0003מישראל. ו\u0004אף שבדרך כלל מייחסים את הבן למשפחת האב, \u0003שאני התם דאמר קרא\u0004 \u0005[שונה שם,\u0006 לענין פדיון הבן, \u0005שאמר הכתוב]\u0006 \u0003\"פטר רחם\",\u0004 ומשמע ש\u0003בפטר רחם תלא רחמנא\u0004 \u0005[תלתה התורה]\u0006 מצוה זו, וכיון שיצא מרחמה של לויה — הרי הוא פטור. ומקשים על שיטת רב פפא, הסבור כי לויה שנתעברה מישראל בנה חייב בפדיון הבן.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מי שהיו לו בנים ונשא אשה שלא ילדה,\u0004 או שנשא מי ש\u0003נתגיירה\u0004 כשהיא \u0003מעוברת,\u0004 או \u0003נשתחררה\u0004 כשהיא \u0003מעוברת,\u0004 וילדה לאחר שנתגיירה.","\u0003ו\u0004כן אשה שעדיין לא ביכרה ו\u0003ילדה היא וכהנת\u0004 (בת כהן), \u0003היא ולויה\u0004 (בת לוי), \u0003היא ואשה שכבר ילדה,\u0004 ונתערבו הולדות זה בזה, ואין ידוע מי הוא בנה של זו שלא ביכרה. \u0003וכן מי שלא שהתה אחרי בעלה שלשה חדשים ונשאת, וילדה\u0004 ילד לאחר שבעה חדשים, \u0003ואין ידוע אם\u0004 ילד זה הוא \u0003בן תשעה ל\u0004בעל ה\u0003ראשון אם בן שבעה לאחרון\u0004 — הריהו \u0003בכור לכהן ואינו בכור לנחלה.\u0004","ומדייקים: \u0003מכלל\u0004 ההלכה בענין מי שנתערב ולדה בולד כהנת או בולד לויה, אתה למד שאשה שהיא בת \u0003כהונה\u0004 (כהנת) \u0003ו\u0004בת \u0003לויה פטורין\u0004 מפדיון. ונברר: \u0003דאיעבר ממאן\u0004 \u0005[שהתעברה ממי]?\u0006 \u0003אילימא דאיעבר\u0004 \u0005[אם תאמר שהתעברה]\u0006 \u0003מכהן\u0004 או \u0003לוי, אי הכי מאי איריא\u0004 \u0005[אם כך מה שייך],\u0006 מדוע מדובר דוקא ב\u0003כהנת ולויה? אפילו\u0004 היתה \u0003בת ישראל נמי\u0004 \u0005[גם כן]\u0006 פטור הבן מפדיון, שהרי הוא כהן או לוי!","\u0003אלא\u0004 תאמר \u0003דאיעבר\u0004 \u0005[שהתעברה]\u0006 \u0003מגוי\u0004 — על כך יש לתמוה: האם \u0003כהנת פטורה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב פפא: בדיק לן\u0004 \u0005[בדק,\u0006 בחן \u0005אותנו]\u0006 \u0003רבה\u0004 בשאלה הבאה: \u0003כהנת שנתעברה מגוי מהו? ואמינא ליה\u0004 \u0005[ואמרנו לו]:\u0006 \u0003לאו היינו\u0004 \u0005[האם אין זה]\u0006 מה שאמר \u0003רב אדא בר אהבה,\u0004 ש\u0003אמר: לויה שילדה בנה פטור מחמש סלעים,\u0004 והעמדנוה במי שנתעברה מגוי? והוא הדין לכהנת!","\u0003ואמר לי\u0004 רבה: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לויה\u0004 שילדה לגוי — בנה נחשב לוי, משום שהאם \u0003בקדושתה קיימא\u0004 \u0005[עומדת],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כך \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לויה שנשבית\u0004 (על ידי גוים, ויש להניח שנאנסה שם) \u0003או שנבעלה בעילת זנות\u0004 — עדיין \u0003נותנין לה מן המעשר\u0004 הראשון, כדין לויה, \u0003ואוכלת,\u0004 שאין זה פוסל אותה מן הזכות לקבלת מעשר.","\u0003אלא כהנת, כיון דאי בעיל לה\u0004 \u0005[שאם בועל אותה]\u0006 הגוי \u0003הויא\u0004 \u0005[הרי היא\u0006 נעשית\u0005]\u0006 כ\u0003זרה\u0004 (שאינה כהנת) ונפסלת מן התרומה, אם כן גם הנולד לה מן הגוי נחשב כזר, וחייב בפדיון. ואם כן, באיזה מקרה פוטרת משנתנו את בן הכהנת מן הפדיון?","ומעירים: \u0003הניחא\u0004 \u0005[זה\u0006 אמנם \u0005נוח],\u0006 אינו קשה \u0003ל\u0004שיטת \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 ש\u0003אמר\u0004 כי דברי רב אדא, הפוטר את בן הלויה מפדיון, עוסקים בלויה \u0003דאיעבר\u0004 \u0005[שהתעברה]\u0006 \u0003מישראל,\u0004 ואם כן הוא \u0003מוקי לה בדאיעבר\u0004 \u0005[מעמיד אותה,\u0006 את משנתנו בענין כהנת ולויה, במקרה \u0005שהתעברה]\u0006 \u0003מישראל,\u0004 ולכן בנה פטור מפדיון. \u0003אלא ל\u0004שיטת \u0003רב פפא,\u0004 הסבור שכהנת ולויה שנתעברה מישראל, בנה חייב בפדיון, \u0003במאי מוקי לה\u0004 \u0005[במה\u0006 הוא \u0005מעמיד אותה]?\u0006 באיזה מקרה פטורה כהנת מפדיון?","ומשיבים: \u0003לעולם\u0004 אין מדובר במשנה בכהנת ממש, אלא באשה \u0003דאיעבר\u0004 \u0005[שהתעברה]\u0006 \u0003מכהן,\u0004 ולכן בנה פטור מפדיון. \u0003ו\u0004אולם \u0003היא\u0004 עצמה \u0003בת ישראל, ואמאי קרי\u0004 \u0005[ומדוע קורא]\u0006 \u0003לה \"כהנת\"?\u0004 משום ש\u0003בנה כהן.\u0004"],["\u0003איתמר\u0004 \u0005[נאמר],\u0006 נחלקו אמוראים בשאלה הבאה: \u0003כהן שמת והניח בן\u0004 בכור שהוא \u0003חלל,\u0004 כגון שנשא אשה גרושה, ובנו נתחלל מקדושת הכהונה, ודינו כזר (בן ישראל) שאביו חייב לפדותו. \u0003רב חסדא אמר: הבן חייב לפדות את עצמו,\u0004 ואילו \u0003רבה בר רב הונא אמר: אין חייב לפדות את עצמו.\u0004 ומסבירים: \u0003כל היכא\u0004 \u0005[כל מקום]\u0006 ש\u0003מת האב לאחר שלשים\u0004 יום משנולד הבן, שאז כבר נתחייב אביו בפדיונו — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003אין הבן חייב לפדות את עצמו, שהרי זכה אביו בפדיונו\u0004 כאילו הפריש חמשה סלעים וזכה בהם לעצמו, שהרי הוא כהן.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003מת האב בתוך שלשים יום,\u0004 שעדיין לא חלה חובת פדיון, \u0003רב חסדא אמר: הבן חייב לפדות את עצמו, דהא\u0004 \u0005[שהרי]\u0006 עדיין \u0003לא זכה אביו לפדיונו.\u0004 ואילו \u0003רבה בר רב הונא אמר: אין הבן חייב לפדות\u0004 את \u0003עצמו, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לכהן התובע ממנו את פדיונו: \u0003אתינא מכח גברא דלא מצית לאשתעויי דינא בהדיה\u0004 \u0005[אני בא מכוח אדם שאין אתה יכול להתדיין איתו],\u0006 שאילו היה אבי בחיים היה זוכה בפדיון לעצמו, ומכוחו אני בא.","ומנסים להביא ראיה ממשנתנו, \u0003תנן\u0004 \u0005[ששנינו]:\u0006 אשה ש\u0003נתגיירה מעוברת\u0004 וילדה את בנה הראשון כשהיא בת ישראל — הולד \u0003בכור לכהן,\u0004 וצריך לפדות את עצמו. \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 לכהן: \u0003אתינא מכח גברא דלא מצית לאשתעויי דינא בהדיה\u0004 \u0005[אני בא מכוח אדם שאין אתה יכול להתדיין איתו],\u0006 שהרי אינך יכול לדרוש את הפדיון מן האב הגוי! דוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003גוי דלית ליה חייס\u0004 \u0005[שאין לו ייחוס],\u0006 שאין בנו מתייחס כלל אחריו.","ומעירים: בענין זה שנחלקו בו חכמים, \u0003אמר ר' שמעון יאסיניא, אמר ר' שמעון בן לקיש\u0004 כדעת רב חסדא: \u0003כהן שמת בתוך שלשים והניח בן חלל\u0004 — \u0003הבן חייב לפדות את עצמו, שלא זכה האב בפדיונו.\u0004 אם \u0003מת לאחר שלשים יום\u0004 של הבן — \u0003אין הבן חייב לפדות\u0004 את \u0003עצמו, שהרי זכה\u0004 כבר \u0003האב בפדיונו.\u0004","שנינו במשנה: \u0003וכן מי שלא שהתה אחרי בעלה שלשה חדשים\u0004 ונשאת וילדה בן שהוא בכור לאמו, ואין ידוע אם הוא בן תשעה לראשון או בן שבעה לאחרון — הבן בכור לכהן, ואינו בכור לנחלה.","ומדייקים: \u0003בכור לנחלה הוא דלא הוי\u0004 \u0005[שאינו],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003כ\u0004בן \u0003פשוט שקיל\u0004 \u0005[\u0006הוא \u0005נוטל].\u0006 \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יקבל חלק בנחלה? \u0003ליזיל לגבי האי ולידחייה\u0004 \u0005[שילך אצל זה,\u0006 בנו של הראשון, \u0005ושידחה אותו],\u0006 ויאמר לו: הבא ראיה שאתה ממשפחתנו וטול נחלה, \u0003ו\u0004כן ילך \u0003לגבי האי ולידחייה\u0004 \u0005[אצל זה,\u0006 בנו של השני, \u0005ו\u0006גם הוא \u0005ידחה אותו]\u0006 מאותו טעם!","\u0003אמר ר' ירמיה: לא נצרכא\u0004 (נצרכה) הלכה זו שאינו בכור לנחלה, \u0003אלא ל\u0004בן ה\u0003בא אחריו\u0004 מכל אחד מן האבות, שאינו בכור לנחלה, שמא ספק זה הוא אחיו הבכור. \u0003ו\u0004לפי זה מה ששנינו: בכור לכהן ואינו בכור לנחלה — \u0003הכי קאמר\u0004 \u0005[וכך אומר\u0006 התנא\u0005]:\u0006 בן מסופק זה הוא \u0003בכור לכהן, והבא אחריו אין בכור לנחלה.\u0004","ושואלים: \u0003ולכתבו\u0004 \u0005[ושיכתבו]\u0006 הספק והבא אחריו, כתב \u0003הרשאה להדדי\u0004 \u0005[זה לזה], בו הם נותנים רשות זה לזה לתבוע את חלקו, וכך יתבעו את חלק הבכורה במשותף, שהרי אחד מהם בוודאי בכור!\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת \u0003שלא בהרשאה\u0004 — \u0003הא מוקמינן לה קמן\u0004 \u0005[הרי אנו מעמידים אותה לפנינו],\u0006 בסוגיה להלן (מט,א) שמדובר \u0003בהרשאה!\u0004","ואומרים: משנתנו, ממנה עולה כי אין כאן דין בכור לנחלה, \u0003מסייע ליה\u0004 \u0005[מסייעת לו]\u0006 \u0003לר' ינאי,\u0004 ש\u0003אמר ר' ינאי:\u0004 שני תינוקות של שני אנשים שנתערבו, ואין ידוע מי הוא בנו של מי, אם \u0003הוכרו\u0004 הבנים מתחילה, מי הוא בנו של מי, \u0003ולבסוף נתערבו — כותבין הרשאה זה לזה\u0004, לתבוע חלק בנחלת כל אחד מן האבות, ואין הבנים האחרים יכולים לדחות כל אחד מהם ולומר שאינו אחיהם.","אבל \u0003לא הוכרו\u0004 הבנים מתחילה כלל \u0003ובסוף נתערבו\u0004— \u0003אין כותבין הרשאה זה לזה,\u0004 משום שלא היתה זכיה לאף אחד מהם אפילו רגע אחד בחלקו בנחלת אביו, ולכן אינו יכול לכתוב עליו הרשאה. ואף במשנתנו, הספק ואחיו הבא אחריו, מתחילה לא הוכר אף אחד מהם כבכור לאביו, ולכן אינם יכולים לכתוב על כך הרשאה.","\u0003אי זהו בכור לנחלה ולכהן:\u0004 האשה \u0003המפלת שפיר,\u0004 עור של עובר קודם שהחל לקבל צורת ולד, שהיה \u0003מלא מים,\u0004 או \u0003מלא דם,\u0004 או \u0003מלא גנינין\u0004 (חתיכות בשר). וכן \u0003המפלת כמין דגים וחגבים שקצים ורמשים, והמפלת ליום ארבעים\u0004 של ההריון — \u0003הבא\u0004 (הנולד) \u0003אחריהם\u0004 נחשב \u0003בכור לנחלה ו\u0004גם \u0003לכהן,\u0004 מפני שאין הראשון נחשב כולד כלל להיחשב כ\"פטר רחם\".","\u0003יוצא דופן,\u0004 ולד שנולד בניתוח דרך דופן הרחם, ולא בדרך לידה, \u0003וה\u0004ולד ש\u0003בא אחריו\u0004 — \u0003שניהן אינן בכור, לא לנחלה ולא לכהן. ר' שמעון אומר: הראשון\u0004 הוא בכור \u0003לנחלה,\u0004 אם הוא בכור לאביו. אבל אינו בכור לכהן, מפני שאינו \"פטר רחם\", שלא יצא הראשון דרך פתח הרחם. \u0003והשני,\u0004 כיון שנולד ראשון דרך פתח הרחם, הוא בכור \u0003לחמש סלעים,\u0004 אבל לא בכור לנחלה.","שנינו במשנה: יוצא דופן והולד הבא אחריו — שניהן אינן בכור, לא לנחלה ולא לכהן. ומסבירים: ה\u0003ראשון,\u0004 יוצא הדופן, \u0003לנחלה לא\u0004 נחשב בכור — מפני שלקיים את הכתוב \u0003\"וילדו לו\"\u0004 (דברים כא, טו) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 כפי שנאמר בענין בכור לנחלה, וזו אינה נחשבת לידה. וכן \u0003לחמש סלעים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 נחשב בכור, משום ש\u0003\"פטר רחם\"\u0004 (שמות יג, ב) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 והרי לא פטר (פתח תחילה) את הרחם.","וכן ה\u0003שני,\u0004 הנולד אחריו, בכור \u0003לנחלה לא\u0004 נחשב — משום ש\u0003\"ראשית אונו\" בעינן\u0004 \u0005[צריכים אנו],\u0006 שנאמר: \"כי הוא ראשית אונו לו משפט הבכורה\" (דברים כא, יז), וזה אינו הראשון. וכן \u0003לחמש סלעים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 נחשב כבכור, שכן, \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 התנא של משנתנו: \u0003בכור\u0004 רק \u0003לדבר אחד,\u0004 שהוא פטר רחם, אבל לא נולד ראשון לאמו, \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003בכור\u0004 לענין פדיון הבן.","ועוד שנינו במשנה, \u0003ר' שמעון אומר: הראשון,\u0004 יוצא הדופן — בכור \u0003לנחלה, והשני\u0004 — בכור \u0003לחמש סלעים.\u0004 ומסבירים: אף שלענין נחלה נאמר \"וילדו לו\", ויציאה דרך דופן לכאורה אינה לידה, \u0003ר' שמעון\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר:\u0004 מה שנאמר \u0003\"תלד\"\u0004 (ויקרא יב, ב) לענין טומאת לידה — הרי זה בא \u0003לרבות יוצא דופן,\u0004 שגם הוא נחשב כילוד. ואם כן, גם לענין בכור לנחלה הרי זה בכלל \"וילדו לו\".","\u0003ו\u0004לדעת ר' שמעון, \u0003השני\u0004 הוא בכור \u0003לחמש סלעים\u0004 לכהן, מפני ש\u0003קסבר\u0004 \u0005[הוא סבור]:\u0006 \u0003בכור\u0004 רק \u0003לדבר אחד,\u0004 שהוא פוטר תחילה את הרחם, \u0003הוי\u0004 \u0005[הרי הוא]\u0006 \u0003בכור,\u0004 למרות שלא נולד ראשון לאמו."],["\u0003מי שלא בכרה אשתו\u0004 (שעדיין לא ילדה), \u0003וילדה שני זכרים,\u0004 ואין ידוע מי הבכור — \u0003נותן\u0004 האב \u0003חמש סלעים לכהן,\u0004 מפני שאחד מהם ודאי בכור. \u0003מת אחד מהן\u0004 מהזכרים \u0003בתוך שלשים יום\u0004 ללידה, לפני שחלה חובת הפדיון — \u0003האב פטור\u0004 מספק, שמא הבכור מת.","\u0003מת האב והבנים קיימים, ר' מאיר אומר: אם נתנו\u0004 את הפדיון לכהן \u0003עד שלא חלקו\u0004 ביניהם את נכסי אביהם — \u0003נתנו, ואם לאו\u0004 \u0005[לא]\u0006 שכבר חלקו — \u0003פטורין,\u0004 כאשר יבואר בגמרא. \u0003ר' יהודה אומר:\u0004 כבר \u0003נתחייבו\u0004 ה\u0003נכסים,\u0004 נכסי אביהם, בחמש סלעים לכהן, וחייבים הבנים לתת. מי שעדיין לא ביכרה אשתו וילדה \u0003זכר ונקבה,\u0004 ואין ידוע מי הראשון — \u0003אין כאן לכהן כלום,\u0004 שמא הנקבה נולדה תחילה, והכהן הבא להוציא מן האב — עליו מוטלת חובת הראיה.","שנינו במשנה: מת האב והבנים קיימים, ר' מאיר אומר: אם נתנו את הפדיון לכהן עד שלא חלקו — נתנו, ואם לאו — פטורים. ושואלים: \u0003דמית\u0004 \u0005[שמת]\u0006 \u0003האב אימת\u0004 \u0005[מתי]?\u0006 \u0003אילימא דמית\u0004 \u0005[אם תאמר שמת]\u0006 \u0003לאחר שלשים יום\u0004 — \u0003בהא\u0004 \u0005[בזו]\u0006 \u0003אמר ר' מאיר כי\u0004 \u0005[\u0006ש\u0005כאשר]\u0006 \u0003חלקו פטורין? והא אשתעבדן להו לנכסי\u0004 \u0005[והרי\u0006 כבר \u0005נשתעבדו להם הנכסים]\u0006 למצות הפדיון!","\u0003אלא\u0004 צריך לומר \u0003דמית\u0004 \u0005[שמת]\u0006 האב \u0003בתוך שלשים יום,\u0004 קודם שהתחייב אביהם בפדיון, ומצות הפדיון חלה על הבכור עצמו, אלא שאין ידוע מי הוא. ואולם על כך יש לשאול: והלא לא נתחייבו נכסי אביהם לפדיון, ואם כן \u0003מאי שנא כי חלקו\u0004 \u0005[מה שונה\u0006 הדין \u0005כאשר חלקו]\u0006 ביניהם את הנכסים, שלדעת ר' מאיר פטורים, מפני ש\u0003אזיל לגבי האי ומדחי ליה\u0004 \u0005[שהולך\u0006 הכהן \u0005אל\u0006 בן \u0005זה ו\u0006הוא \u0005דוחה אותו]\u0006 ואומר שאינו הבכור, וכן \u0003דאזיל לגבי האי ומדחי ליה\u0004 \u0005[שהולך\u0006 הכהן \u0005אל\u0006 בן \u0005זה ודוחה אותו]?\u0006 והרי, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא חלקו נמי\u0004 \u0005[גם כן]\u0006 — \u0003ליזיל לגבי האי ולידחייה, וליזיל לגבי האי ולידחייה\u0004 \u0005[שילך אל זה וידחה אותו, ושילך אל זה וידחה אותו]!\u0006","\u0003אמר ר' ירמיה: זאת אומרת,\u0004 מכאן יש ללמוד ש\u0003שני יוסף בן שמעון\u0004 (אנשים ששמם שווה) \u0003שהיו בעיר אחת ולקחו\u0004 (קנו) \u0003שדה בשותפות\u0004 — \u0003בעל חוב,\u0004 שיש לו שטר חוב הכתוב על שם יוסף בן שמעון, \u0003גובה אותה מהם\u0004 בחובו, ואף על פי שלא ידוע מי החייב האמיתי, מפני \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לכל אחד מהם: \u0003אי בדידך מסיקנא\u0004 \u0005[אם בך אני נושה]\u0006 — \u0003מנתא דידך קא שקילנא\u0004 \u0005[את המנה,\u0006 החלק \u0005שלך\u0006 בשדה שלכם \u0005אני נוטל],\u0006 \u0003ואי בחברך מסיקנא\u0004 \u0005[ואם בחברך אני נושה]\u0006 — \u0003מנתא דחברך קא שקילנא\u0004 \u0005[את המנה,\u0006 החלק \u0005של חברך אני נוטל],\u0006 שהרי יש לחייב האמיתי חלק בשדה; ואף במשנתנו, האחים שלא חלקו — שותפים בנכסי אביהם, ולפיכך יכול הכהן לגבות מנכסים אלו את חובו.","\u0003אמר רבא\u0004 בתמיהה: \u0003מכדי\u0004 \u0005[הרי]\u0006 כלל יש בידינו, \u0003נכסי דבר איניש אינון ערבין ביה\u0004 \u0005[\u0006ש\u0005נכסיו של אדם הם ערבים לו],\u0006 לפרעון חובותיו, \u0003מי איכא מידי\u0004 \u0005[האם יש,\u0006 היתכן \u0005דבר\u0006 כזה\u0005],\u0006 \u0003דלדידיה לא מצי תבע ליה, ולערב מצי תבע ליה\u0004 \u0005[שאותו,\u0006 את החייב, \u0005אינו יכול לתבוע, ואת הערב יכול לתבוע]? והתנן\u0006 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המלוה את חבירו על ידי ערב\u0004 — \u0003לא יפרע מן הערב, וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 בפירושה: ש\u0003לא יתבע מן הערב תחלה,\u0004 אלא עליו לתבוע את הלווה תחילה. והלא כאן אין הכהן יכול לתבוע אף אחד מן האחים, והוא גובה מנכסיהם!","\u0003אלא אמר רבא:\u0004 לעולם יש לפרש שמדובר במשנה כ\u0003שמת\u0004 האב \u0003לאחר שלשים יום,\u0004 וכבר נשתעבדו נכסי האב לפדיון. \u0003ואי דאיכא נכסי טובא\u0004 \u0005[ואם יש נכסים מרובים]\u0006 לגבות מהם — \u0003הכא נמי דשקיל\u0004 \u0005[כך גם כן\u0006 הדין — \u0005שנוטל\u0006 הכהן\u0005]\u0006 חמש סלעים, גם לאחר שחלקו הבנים בנכסי אביהם, שעל הבנים לפרוע את חובות אביהם ממה שירשו. \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]?\u0006 \u0003כגון דליכא\u0004 \u0005[שאין]\u0006 במה שירשו מאביהם \u0003אלא חמש סלעים.\u0004","\u0003ודכולי עלמא אית להו\u0004 \u0005[ולדעת הכל יש להם,\u0006 הם מקבלים\u0005]\u0006 את מה שאמר \u0003רב אסי,\u0004 ש\u0003אמר רב אסי: האחין שחלקו\u0004 בנכסי אביהם — הרי שב\u0003מחצה\u0004 מהחלק שקיבלו הם נחשבים כ\u0003יורשין, ו\u0004ב\u0003מחצה\u0004 הם נחשבים כ\u0003לקוחות\u0004 (כקונים). \u0003ו\u0004כן צריך לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003מלוה הכתובה בתורה,\u0004 כלומר, חוב המפורש בתורה, כגון פדיון הבן —"],["\u0003לאו\u0004 \u0005[לא]\u0006 \u0003ככתובה בשטר דמיא\u0004 \u0005[נחשבת],\u0006 אלא כמלוה על פה. \u0003ודכולי עלמא אית להו\u0004 \u0005[ולדעת הכל יש להם,\u0006 הם מקבלים\u0005]\u0006 את דברי \u0003רב פפא,\u0004 ש\u0003אמר רב פפא: מלוה על פה\u0004 — \u0003גובה מן היורשין\u0004 של החייב, \u0003ואינו גובה מן הלקוחות\u0004 שקנו ממנו. ואם כן, יכול הכהן לגבות את דמי פדיון הבן רק מן המחצית של נכסי האב עליה נחשבים הבנים יורשים. והואיל ואין בנכסי האב אלא חמישה סלעים נמצא שהכהן יכול לגבות רק שנים ומחצה סלעים.","\u0003ו\u0004לפי זה, \u0003הכא\u0004 \u0005[כאן],\u0006 שנחלקו ר' מאיר ור' יהודה במשנתנו \u0003ב\u0004ענין \u0003חמש ולא בחצי חמש קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003שר' מאיר סבר\u0004 \u0005[סבור]\u0006 שהתורה ציותה לתת בפדיון \u0003חמש\u0004 סלעים דוקא, \u0003ולא חצי\u0004 (או חלק מ) \u0003חמש,\u0004 ולכן פטורים האחים מלתת לכהן אותם שנים וחצי סלעים. \u0003ו\u0004אילו \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003חמש\u0004 — \u0003ואפילו חצי חמש,\u0004 ולכן נוטל הכהן אותם שנים וחצי סלעים, שהם נחשבים לגביהם כיורשים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבזה נחלקו, מדוע לשון המשנה היא: \u0003ר' יהודה אומר נתחייבו נכסים?\u0004 הלא \u0003נתחייב גברא\u0004 \u0005[האיש],\u0006 כלומר, חייבים האחים לתת, \u0003מיבעי ליה\u0004 \u0005[צריך היה]\u0006 לומר! \u0003ועוד\u0004 קשה, שהרי \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יהודה אומר: האחין\u0004 שאין ידוע מי מהם הבכור, \u0003שחלקו\u0004 בנכסי אביהם, \u0003אם יש עשרה זוז\u0004 (דינר) שהם שני סלעים ומחצה \u0003לזה, ועשרה זוז לזה\u0004 — \u0003חייבין\u0004 לתת לכהן, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פטורין;\u0004 ויש לשאול:","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003עשרה זוז לזה ועשרה זוז לזה? אילימא\u0004 \u0005[אם תאמר]\u0006 שיש לכל אחד מהם עשרה זוז בנכסי האב, \u0003בין\u0004 בחלק ה\u0003ירושה בין\u0004 בחלק ה\u0003לקוחות\u0004 יחד, ונמצא שיש בחלק הירושה של שניהם עשרה זוז, שהם שנים וחצי סלעים, \u0003ו\u0004ר' יהודה אומר שהם חייבים משום שלדעתו \u0003חמש ואפילו חצי חמש,\u0004 כלומר, שצריך לתת לכהן גם פחות מחמישה סלעים, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 — \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע חייבים דווקא\u0005]\u0006 אם יש לפחות \u0003עשרה\u0004 זוזים? \u0003אפילו\u0004 אם יש \u0003בציר\u0004 \u0005[פחות]\u0006 \u0003מעשרה\u0004 זוזים \u0003נמי\u0004 \u0005[גם כן]\u0006 יטול הכהן מה שיש, ומדוע שנה ר' יהודה שהם פטורים?","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כשיש \u0003עשרה זוז\u0004 של \u0003ירושה לזה, ועשרה זוז\u0004 של \u0003ירושה לזה,\u0004 ובסך הכל חמישה סלעים, ולדעת ר' יהודה, דווקא במקרה זה צריכים לתת פדיון לכהן. \u0003אלמא\u0004 \u0005[מכאן]\u0006 שר' יהודה \u0003חמש ולא חצי חמש סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ולא כמו שפירשנו!","\u0003אלא\u0004 צריך לומר, \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל],\u0006 גם ר' מאיר וגם ר' יהודה סבורים: \u0003חמש\u0004 דוקא צריך לתת לכהן \u0003ולא חצי חמש, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004דברי \u0003רב אסי ורב פפא קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 שמדובר באופן שאין בנכסי אביהם אלא חמישה סלעים, ור' מאיר סבור כרב אסי ורב פפא, ואין כאן אלא שנים וחצי סלעים בחלק הירושה, ואין הכהן יכול לגבותם. ואילו ר' יהודה אינו סבור כאחד מהם, ולדעתו עומדים כל חמשת הסלעים לגביית הפדיון.","\u0003ואיכא דמתני ליה אסיפא\u0004 \u0005[ויש ששונים את הענין הזה על סופה],\u0006 ששנינו כי מי שנולדו לו שני בנים, ואין ידוע איזה מהם בכור, ומת האב, ר' יהודה אומר: \u0003נתחייבו הנכסים,\u0004 וגם אם כבר חלקו את נכסי אביהם — חייבים הבנים לשלם לכהן. ושואלים: \u0003דמית\u0004 \u0005[שמת]\u0006 \u0003האב אימת\u0004 \u0005[אימתי]?\u0006 \u0003אילימא דמית\u0004 \u0005[אם תאמר שמת]\u0006 \u0003לאחר שלשים\u0004 יום מלידתם, שכבר נתחייב האב בפדיון, \u0003מכלל\u0004 הדברים אתה למד ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 שבמקרה זה, \u0003כי\u0004 \u0005[\u0006ש\u0005כאשר]\u0006 \u0003חלקו פטורין?\u0004 תמוה הדבר, \u0003הא אישתעבדי להו נכסי\u0004 \u0005[הרי\u0006 כבר \u0005נשתעבדו להם הנכסים]!\u0006","\u0003אלא\u0004 צריך לומר שמת \u0003בתוך שלשים\u0004 יום, קודם שנתחייבו נכסי האב, והחוב מוטל איפוא על הבן הבכור, אלא שאין יודעים מי הוא. ושואלים: אם כן, גם \u0003כי\u0004 \u0005[כאשר]\u0006 כבר \u0003חלקו\u0004 האחים ביניהם את נכסי אביהם, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מחייב ר' יהודה? ליזיל לגבי האי לידחייה\u0004 \u0005[שילך\u0006 הכהן \u0005אצל\u0006 בן \u0005זה וידחה אותו]\u0006 בטענה שאינו הבכור, \u0003וגבי האי ולידחייה\u0004 \u0005[\u0006וילך \u0005אצל\u0006 בן \u0005זה וידחה אותו]\u0006 בטענה שאינו הבכור!","\u0003אמר ר' ירמיה: זאת אומרת,\u0004 ממה שר' יהודה מחייב את האחים לתת את הפדיון לכהן, יש ללמוד כי \u0003שני יוסף בן שמעון שהיו בעיר אחת, ולקח\u0004 (קנה) \u0003אחד מהם שדה מחבירו\u0004 — בעל חוב, שיש בידו שטר חוב על שם יוסף בן שמעון מוקדם לזמן הקניה, \u0003גובה\u0004 את חובו \u0003ממנו\u0004 מהשדה, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לקונה: \u0003אי בדידך מסיקנא\u0004 \u0005[אם בך אני נושה]\u0006 — \u0003מנתא דידך קא שקילנא\u0004 \u0005[\u0006את \u0005המנה,\u0006 החלק \u0005שלך אני נוטל],\u0006 \u0003ואי בחברך מסיקנא\u0004 \u0005[ואם בחברך אני נושה],\u0006 \u0003משתעבדא לי מקמי דידך\u0004 \u0005[\u0006הרי השדה הזה \u0005משועבד לי לפניך].\u0006","\u0003אמר רבא\u0004 בתמיהה: \u0003מכדי נכסוהי דבר איניש אינון ערבין ביה\u0004 \u0005[הלא נכסיו של אדם הם הערבים לו],\u0006 האם ייתכן שממנו אינו יכול לגבות, ומן הערב (נכסיו) הוא גובה? \u0003וכולה\u0004 (כל ההמשך) \u0003כלישנא קמא\u0004 \u0005[כמו בלשון הראשונה]\u0006 שהובאה בעמוד הקודם, על דברי ר' מאיר.","\u0003שתי נשים\u0004 של איש אחד \u0003שלא בכרו\u0004 (ילדו), \u0003וילדו שני זכרים\u0004 ונתערבו — \u0003נותן\u0004 האב \u0003עשרה סלעים לכהן,\u0004 אף שלא ידוע של מי כל אחד מהם, מפני שכל אחד מהם בכור ודאי. \u0003מת אחד מהן בתוך שלשים יום,\u0004 קודם שחלה חובת הפדיון, \u0003אם לכהן אחד נתן\u0004 פדיון שניהם — \u0003יחזיר לו\u0004 הכהן \u0003חמש סלעים,\u0004 מפני שפטור היה מלפדות את המת, \u0003ואם לשני כהנים נתן\u0004 — \u0003אינו יכול להוציא מידם,\u0004 מפני שכל כהן אומר שהוא מחזיק בפדיון של הבן החי.","ואם ולדות נשיו שהתערבו היו \u0003זכר ונקבה, או שני זכרים ונקבה\u0004 — \u0003נותן חמש סלעים לכהן,\u0004 מפני שאחד מן הזכרים ודאי בכור אחד לאמו, ועל השני שהוא ספק — אין הכהן יכול להוציא מידו. ואם היו הולדות \u0003שתי נקבות וזכר, או שני זכרים ושתי נקבות\u0004 — \u0003אין כאן לכהן כלום,\u0004 שמא שתי הנקבות יצאו תחילה.","\u0003אחת\u0004 מנשיו שכבר \u0003בכרה ואחת שלא בכרה, וילדו שני זכרים\u0004 והתערבו — \u0003נותן חמש סלעים לכהן,\u0004 מפני שוודאי אחד מהם בכור; \u0003מת אחד מהן בתוך שלשים יום\u0004 — \u0003האב פטור\u0004 מספק, שמא הבכור מת.","\u0003מת האב והבנים קיימים, ר' מאיר אומר: אם נתנו\u0004 פדיון לכהן \u0003עד שלא חלקו\u0004 ביניהם את נכסי האב — \u0003נתנו, ואם לאו\u0004 \u0005[לא],\u0006 שכבר חלקו — \u0003פטורין\u0004 מלתת. \u0003ר' יהודה אומר: נתחייבו\u0004 ה\u0003נכסים,\u0004 ויתנו מהם הבנים חמש סלעים לכהן. ואם ילדו שתי נשיו, האשה שביכרה והאשה שלא ביכרה, \u0003זכר ונקבה,\u0004 והתערבו — \u0003אין לכהן כלום,\u0004 שמא המבכרת ילדה את הנקבה.","\u0003שתי נשים של שני אנשים שלא בכרו, וילדו שני זכרים\u0004 והתערבו — \u0003זה נותן חמש סלעים לכהן וזה נותן חמש סלעים,\u0004 מפני שלכל אחד נולד בכור ודאי. ואם \u0003מת אחד מהם\u0004 מהולדות \u0003בתוך שלשים\u0004 ללידה, וכבר נתנו פדיון עבורם, \u0003אם לכהן אחד נתנו\u0004 — \u0003יחזיר להם חמש סלעים\u0004 של פדיון המת, ו\u0003אם לשני כהנים נתנו\u0004 — \u0003אינן יכולין להוציא מידם,\u0004 מפני שכל כהן טוען שהוא מחזיק בפדיון החי.","היו הולדות שהתערבו \u0003זכר ונקבה\u0004 — \u0003האבות פטורין,\u0004 מפני שכל אחד אומר שהוא אבי הנקבה, אבל \u0003הבן חייב לפדות את עצמו,\u0004 שהרי הוא ודאי בכור. היו הולדות שהתערבו \u0003שתי נקבות וזכר, או שתי נקבות ושני זכרים\u0004 — \u0003אין כאן לכהן כלום,\u0004 שהרי אין כאן בכור ודאי.","אשה \u0003אחת\u0004 ש\u0003בכרה\u0004 ואשה \u0003אחת שלא בכרה, של שני אנשים, וילדו שני זכרים\u0004 והתערבו — \u0003זה שלא בכרה אשתו נותן חמש סלעים לכהן,\u0004 שהרי ודאי נולד לו בכור. ואם ילדו \u0003זכר ונקבה\u0004 — \u0003אין כאן לכהן כלום,\u0004 שמא זו שלא ביכרה אשתו ילדה את הנקבה.","שנינו במשנה בענין שתי נשים של שני אנשים שהתערבו בכורותיהם, שאם נתנו האבות את פדיונותיהם לשני כהנים, ומת אחד מהבכורות — אינם יכולים להוציא מהכהנים את הפדיון שנתנו עבורו. ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע\u0005]\u0006 הדין כשנתנו האבות את הפדיונות ל\u0003שני כהנים\u0004 ומת אחד מהבכורות, \u0003דאזיל לגבי האי ומדחי ליה\u0004 \u0005[שהולך\u0006 האב \u0005אצל\u0006 כהן \u0005זה ודוחה אותו]\u0006 הכהן, וטוען שנטל עבור החי, \u0003ואזיל לגבי האי ומדחי ליה\u0004 \u0005[והולך אצל\u0006 כהן \u0005זה,\u0006 השני, \u0005ודוחה אותו],\u0006 ואומר שנטל עבור החי?","והרי כשנתנו ל\u0003כהן אחד נמי\u0004 \u0005[גם כן]\u0006 ידחה אותם, \u0003ליזיל לגבי האי\u0004 \u0005[שילך אצלו\u0006 אב \u0005זה]\u0006 \u0003ולידחייה\u0004 \u0005[וידחה אותו]\u0006 ויטען שבנו הוא החי, \u0003וליזיל לגבי האי\u0004 \u0005[שילך אליו\u0006 אב \u0005זה]\u0006 \u0003ולידחייה\u0004 \u0005[וידחה אותו],\u0006 ויאמר שבנו הוא החי! \u0003אמר שמואל:\u0004"],["\u0003בבא בהרשאה,\u0004 שבא אחד מהאבות ובידו כתב הרשאה מהאב השני, לדון עם הכהן על חמש הסלעים שבידו, ולכן אין הכהן יכול לדחותם. אבל כשנתנו לשני כהנים, לא יועיל כתב הרשאה, מפני שכל כהן ידחה אותם ויאמר שחבירו הוא שנטל את פדיון המת.","ומקשים, \u0003והאמרי נהרדעי\u0004 \u0005[והרי אומרים חכמי נהרדעא]:\u0006 \u0003לא כתבינן אדרכתא אמטלטלי\u0004 \u0005[אין כותבים הרשאה על מיטלטלים],\u0006 אלא רק על תביעת קרקע, ואלו כאן תובעים מהכהן מעות שהם מיטלטלים! ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלו],\u0006 שאין כותבים על מיטלטלים, אמורים \u0003היכא דכפריה\u0004 \u0005[במקום שכפר בו\u0006 הנתבע\u0005],\u0006 שהוא טוען שלא קיבל מן התובע דבר, \u0003אבל היכא דלא כפריה\u0004 — \u0003כתבינן\u0004 \u0005[במקום שלא כפר בו\u0006 — \u0005כותבים אנו]\u0006 הרשאה גם על מיטלטלים. וכאן הכהן טוען שהתובע אותו אינו אבי המת, אך אינו כופר בעצם קבלת המעות.","שנינו במשנה, שאם שתי נשים של שני אנשים שלא ביכרו, ילדו \u0003זכר ונקבה,\u0004 ואין ידוע של מי הזכר ושל מי הנקבה — האבות פטורים מפדיון הבן, מפני שכל אחד טוען שאשתו ילדה נקבה. אבל הבן חייב בפדיון, מפני שהוא ודאי בכור. ואם ילדו שתי נקבות וזכר, או שתי נקבות ושני זכרים — \u0003אין כאן לכהן כלום,\u0004 שמא הנקבות נולדו תחילה. \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003רב הונא\u0004 לגבי אותו מקרה: ילדו \u0003שני זכרים ונקבה\u0004 — \u0003אין כאן לכהן כלום,\u0004 למרות שוודאי יש כאן בכור. ולא רק האבות פטורים, מפני שכל אחד טוען שהנקבה היא בתו, ונולדה ראשונה, אלא גם הבנים פטורים, מפני שכל אחד מן הזכרים טוען שמא נולדה נקבה לפניו.","ושואלים: \u0003ותנא דידן\u0004 \u0005[והתנא שלנו]\u0006 מדוע לא הוסיף אופן זה? ומשיבים: \u0003כיון\u0004 ש\u0003ב\u0004אופן שנשואות הנשים ל\u0003שני אנשים הוא דמשכחת לה\u0004 \u0005[שאתה מוצא אותה]\u0006 לפטור לגמרי, אבל \u0003באיש אחד ושתי נשים לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה]\u0006 לפטור, שהרי ודאי נולד בכור לאיש זה, ובכל מקרה הוא חייב חמישה סלעים לכהן — \u0003לא מתני ליה\u0004 \u0005[אינו שונה אותו\u0006 התנא שלנו\u0005]\u0006 גם בשתי נשים של שני אנשים. מפני ששיטתו של התנא במשנתנו היא שבכל מקום בו הוא שונה \"אין כאן לכהן כלום\" הדין זהה גם בשתי נשים של שני אנשים וגם בשתי נשים של איש אחד.","\u0003מת הבן בתוך שלשים יום, אף על פי שנתן\u0004 כבר האב פדיון \u0003לכהן\u0004 — \u0003יחזיר\u0004 לו הכהן את חמשת הסלעים. מת הבן \u0003לאחר שלשים יום, אף על פי שלא נתן\u0004 האב עדיין — \u0003יתן,\u0004 שהרי כבר נתחייב בפדיונו. \u0003מת ביום שלשים\u0004 עצמו — הרי זה \u0003כיום שלפניו,\u0004 שאין מצות פדיון אלא למי שכבר מלאו לו שלושים יום. \u0003ר' עקיבא אומר: אם\u0004 כבר \u0003נתן\u0004 לכהן את הסלעים — \u0003לא יטול\u0004 ממנו, \u0003ואם\u0004 עדיין \u0003לא נתן\u0004 — \u0003לא יתן.\u0004","בענין מחלוקת חכמים ור' עקיבא שבמשנתנו, מסבירים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 שאין מצות פדיון אלא לאחר שנשלמו שלושים יום? \u0003גמרי\u0004 \u0005[למדים הם]\u0006 בגזירה שווה \u0003\"חדש\" \"חדש\" מ\u0004פדיון בכורות ישראל ב\u0003מדבר,\u0004 כאשר באו הלויים תחתם, \u0003מה התם\u0004 \u0005[שם]\u0006 בפדיון על ידי הלויים נאמר: \"...פקוד כל בכר זכר לבני ישראל מבן חדש \u0003ומעלה\"\u0004 (במדבר ג, מ), שמשמעו — לאחר שלושים, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן],\u0006 במצות הפדיון לדורות, שנאמר \"מבן חדש תפדה\" (במדבר יח, טז), צריך להיות \u0003ומעלה,\u0004 כלומר, לאחר שלושים.","\u0003ור' עקיבא מספקא ליה\u0004 \u0005[מסופק היה לו\u0006 הדבר\u0005]:\u0006 האם \u0003מדאיצטריך למכתב\u0004 \u0005[מ\u0006כך \u0005שהוצרך לכתוב\u0006 בתורה\u0005]\u0006 \u0003\"ומעלה\" גבי\u0004 \u0005[אצל]\u0006 מצות \u0003ערכין:\u0004 \"ואם מבן ששים שנה ומעלה...\" (ויקרא כז, ז), ללמד ש\"בן ששים\" הוא מי שכבר מלאו לו ששים שנה, \u0003ולא גמרי\u0004 \u0005[למדים]\u0006 דיני הערכין בבנין אב \u0003מ\u0004פדיון הבכורות ב\u0003מדבר\u0004 (שנאמר בו \"ומעלה\"), שכל מקום בו נאמר \"מבן\" הרי זה מי שנשלם בו פרק זמן זה, אם כן, פדיון הבכורות במדבר וערכין \u0003הוו להו\u0004 \u0005[הרי הם]\u0006 \u0003שני כתובים הבאים כאחד,\u0004 המלמדים אותו דין,","\u0003וכל שני כתובים הבאים כאחד\u0004 — \u0003אין מלמדין\u0004 למקום אחר.","ולכן יש לומר כי בפדיון בכורות לדורות דינו של יום שלושים כיום שלאחריו, ושלא כדעת חכמים; \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 אומרים אנו ששני כתובים הבאים כאחד \u0003אין מלמדין\u0004 — הרי זה \u0003לעלמא\u0004 \u0005[לכלל],\u0006 לדינים שונים לגמרי, \u0003אבל לגופייהו\u0004 \u0005[לעצמם]\u0006 \u0003מלמדין,\u0004 ויש ללמוד פדיון בכורות לדורות מפדיון הבכורות במדבר, ודינו כיום שלפניו. \u0003ומשום הכי\u0004 \u0005[כך]\u0006 \u0003מספקינן ליה\u0004 \u0005[מסופקים אנו בו],\u0006 לדעת ר' עקיבא, בבכור ביום שלושים.","\u0003אמר רב אשי: הכל מודים לענין אבילות,\u0004 שולד שמת ב\u0003יום שלשים\u0004 — נידון \u0003כ\u0004מת ב\u0003יום שלפניו,\u0004 שדינו כנפל, ואין נוהגים בו דיני אבילות. \u0003ו\u0004טעם הדבר, שהרי \u0003אמר\u0004 \u0003שמואל: הלכה כדברי המיקל באבל.\u0004","\u0003מת האב בתוך שלשים\u0004 יום ללידת הבכור — הרי הבן \u0003בחזקת שלא נפדה,\u0004 מפני שאין רגילים לפדותו אז, \u0003עד שיביא\u0004 הבן \u0003ראיה שנפדה;\u0004 מת האב \u0003לאחר שלשים יום\u0004 — הרי הבן \u0003בחזקת שנפדה, עד שיאמרו לו\u0004 לבן \u0003שלא נפדה.\u0004 היה צריך \u0003הוא לפדות\u0004 עצמו, שאביו לא פדאו, \u0003ו\u0004גם את \u0003בנו\u0004 צריך הוא \u0003לפדות\u0004 — \u0003הוא קודם לבנו. ר' יהודה אומר: בנו קודמו, שמצותו\u0004 (מצות פדיון האב עצמו) מוטלת היתה \u0003על אביו, ומצות\u0004 פדיון \u0003בנו\u0004 — מוטלת \u0003עליו.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 נחלקו אמוראים בענין זה: \u0003הפודה את בנו\u0004 ונתן לכהן חמישה סלעים \u0003בתוך שלשים יום\u0004 ללידת הבן, \u0003רב אמר: בנו פדוי, ושמואל אמר: אין בנו פדוי.\u0004 ומסבירים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 אם אמר האב \u0003\"מעכשיו\u0004 הוא פדוי\" — \u0003אין בנו פדוי,\u0004 שהרי עדיין אין חיוב בפדיון, וכן מצד אחר, אם אמר האב שהפדיון יחול \u0003לאחר שלשים יום, ואיתנהו למעות\u0004 \u0005[\u0006ועדיין \u0005נמצאות המעות]\u0006 לאחר שלושים יום — \u0003ודאי בנו פדוי,\u0004 מפני שהמעות מצויים ברשות הכהן בזמן חיוב הפדיון.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה כשאמר האב לכהן שהפדיון יחול \u0003לאחר שלשים יום, ונתעכלו המעות,\u0004 אבדו מן העולם קודם לכן, \u0003רב אמר: בנו פדוי\u0004 — \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 ביחס ל\u0003קידושי אשה,\u0004 כשמקדש אשה במעות על מנת שיחולו הקידושין לאחר שלושים יום; \u0003התם לאו אף על גב\u0004 \u0005[שם,\u0006 האם \u0005לא אף על פי]\u0006 ש\u0003נתעכלו המעות\u0004 בתוך שלושים יום — \u0003הוו קידושי\u0004 \u0005[הרי הם קידושין],\u0006"],["\u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה]\u0006 הדין.","\u0003ושמואל אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך: התם\u0004 \u0005[שם],\u0006 כשנתעכלו המעות קודם שחלו הקידושין, אין זה מעכב מפני ש\u0003בידו\u0004 היה \u0003לקדשה מעכשיו\u0004 כשנתנם, אבל \u0003הכא\u0004 \u0005[כאן],\u0006 כשנתעכלו מעות הפדיון — \u0003אין בידו לפדותו מעכשיו\u0004 כשנתנם. ובפסק ההלכה במחלוקת רב ושמואל מעירים: \u0003ואף על גב דקיימא לן\u0004 \u0005[ואף על פי שמוחזק בידינו]\u0006 \u0003דכל היכא דפליגי\u0004 \u0005[שכל מקום שחולקים]\u0006 \u0003רב ושמואל\u0004 — \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב באיסורי\u0004 \u0005[ב\u0006ענייני \u0005איסורים]\u0006 \u0003וכשמואל בדיני\u0004 \u0005[ב\u0006ענייני \u0005ממונות],\u0006 \u0003הכא הלכתא כוותיה\u0004 \u0005[כאן הלכה כשיטתו]\u0006 של \u0003שמואל,\u0004 שהפודה את בנו בתוך שלושים יום — אין בנו פדוי.","ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מת\u0004 הבן \u0003בתוך שלשים יום אף על פי שנתן לכהן\u0004 — \u0003יחזיר לו\u0004 הכהן \u0003חמש סלעים.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 כש\u0003מת\u0004 בתוך שלושים — מחזיר, \u0003הא\u0004 \u0005[אבל]\u0006 כאשר \u0003לא מת\u0004 בתוך שלושים — \u0003בנו פדוי,\u0004 למרות שהאב נתן את המעות קודם הזמן, שלא כדברי שמואל! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דאיתנהו למעות\u0004 \u0005[שהמעות נמצאות\u0006 עדיין\u0005].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה נוספת ממה ששנינו במשנתנו: מת האב בתוך שלושים, הרי הבן \u0003בחזקת שלא נפדה עד שיאמרו לו שנפדה\u0004 על ידי אביו. ובמקרה שנפדה — מועיל הפדיון, למרות שהמעות ניתנו קודם שלושים, ושלא כדברי שמואל! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 מדובר \u0003דאיתנהו למעות בעינייהו\u0004 \u0005[שהמעות נמצאות בעינן].\u0006","ומסופר, \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב יהודה: הפודה את בנו בתוך שלשים יום\u0004 — \u0003בנו פדוי. אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003שמואל אמר\u0004 ש\u0003אין בנו פדוי, ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003בנו פדוי?\u0004 ומעירים: \u0003ואף על גב דקיימא לן\u0004 \u0005[ואף על פי שמוחזק בידינו]\u0006 \u0003כרב באיסורי\u0004 \u0005[ב\u0006ענייני \u0005איסורים]\u0006 \u0003וכשמואל בדיני\u0004 \u0005[ב\u0006ענייני \u0005ממונות],\u0006 \u0003הכא הלכתא כותיה\u0004 \u0005[כאן הלכה כשיטתו]\u0006 של \u0003שמואל.\u0004","שנינו במשנתנו: \u0003הוא לפדות ובנו לפדות הוא קודם לבנו וכו'.\u0004 ומביאים מה שאמרו חכמים על משנתנו במקום אחר. שכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במשנתנו: \u0003הוא לפדות ובנו לפדות\u0004 — \u0003הוא קודם לבנו. ר' יהודה אומר: בנו קודמו, שמצותו,\u0004 מצות פדיונו מוטלת \u0003על אביו, ומצות\u0004 פדיון \u0003בנו\u0004 מוטלת \u0003עליו.\u0004","\u0003אמר ר' ירמיה: הכל מודים היכא דליכא\u0004 \u0005[במקום שאין]\u0006 לו \u0003אלא חמש סלעים\u0004 — \u0003הוא קודם לבנו,\u0004 ושלא כמשמעות המשנה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003דמצוה דידיה עדיף\u0004 \u0005[שהמצוה שלו\u0006 להיפדות \u0005עדיפה].\u0006 \u0003כי פליגי היכא דאיכא\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים\u0006 הרי זה \u0005במקום שיש]\u0006 \u0003חמש\u0004 סלעים \u0003משועבדות\u0004 (נכסים שמכר לאחרים, והם משועבדים לפרעון חובותיו הקודמים) \u0003וחמש\u0004 סלעים \u0003בני חורין,\u0004 בידו;","\u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003מלוה\u0004 חובת תשלום \u0003הכתובה בתורה,\u0004 כגון פדיון הבן — \u0003כמלוה\u0004 ה\u0003כתובה בשטר דמיא\u0004 \u0005[נחשבת],\u0006 שגובים אותה מנכסים משועבדים, \u0003ו\u0004לכן \u0003דידיה\u0004 \u0005[את\u0006 חוב הפדיון \u0005שלו]\u0006 \u0003אזיל וטריף ממשעבדי\u0004 \u0005[הולך\u0006 הכהן \u0005וטורף מ\u0006הנכסים \u0005המשועבדים],\u0006 כדין מילוה בשטר, \u0003ובהני\u0004 \u0005[ובאלה]\u0006 \u0003חמש\u0004 הסלעים שהם \u0003בני חורין\u0004 — \u0003פריק ליה לבריה\u0004 \u0005[פודה את בנו].\u0006","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מלוה הכתובה בתורה\u0004 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ככתובה בשטר דמיא\u0004 \u0005[נחשבת],\u0006 אלא כמילוה על פה, ולא ניתן לגבות את דמי הפדיון מן המשועבדים, \u0003הלכך\u0004 \u0005[על כן]\u0006 קיום ה\u0003מצוה דידיה\u0004 \u0005[שלו]\u0006 להיות פדוי, \u0003עדיף\u0004 \u0005[עדיפה],\u0006 ויפדה עצמו בחמש בני החורין.","\u0003חמש סלעים\u0004 (שקלים) של כסף \u0003של\u0004 פדיון ה\u0003בן,\u0004 שנאמר בו: \"כסף חמשת שקלים בשקל הקודש\" (במדבר יח, טז), מחשבים בהם את שקל הקדש \u0003במנה צורי,\u0004 המטבע של צור, שתכולת הכסף שבו גבוהה ביותר. ולא במטבע מדינה, שהוא שווה שמינית ממנו.","\u0003שלשים\u0004 שקלים \u0003של עבד\u0004 שהומת על ידי שור (שמות נא, לב), וכן \u0003חמשים של אונס ושל מפתה\u0004 נערה בתולה (ראה שמות כב, טז. דברים כב, כט). וכן \u0003מאה של מוציא שם רע\u0004 על אשתו שלא מצא לה בתולים (ראה דברים כב, יט) — \u0003כולם,\u0004 גם אלה שלא הוזכר בהם שקל — הריהם \u0003בשקל הקדש,\u0004 שהוא עשרים גרה (ראה במדבר יח, טו), ומחשבים אותם \u0003במנה צורי. וכולן,\u0004 כל הדברים הנפדים — \u0003נפדין בכסף,\u0004 במטבע, או \u0003בשוה כסף, חוץ משקלים,\u0004 מחצית השקל שתורמים למקדש בכל שנה, שהוא ניתן במטבע דוקא.","שנינו במשנה: חמש סלעים של בן ב\u0003מנה צורי.\u0004 ובפירוש הדברים \u0003אמר ר' אסי:\u0004 יש לתת חמישה סלעים \u0003ממנה של צורי,\u0004 היוצא במדינת צור. \u0003ר' אמי אמר:\u0004 חמישה סלעים שווים \u0003דינרא ערבא\u0004 \u0005[דינר\u0006 זהב \u0005ערבי].\u0006 \u0003ר' חנינא אומר: איסתרא סרסיא דמיזדבנא תמניא בדינרא\u0004 \u0005[סלע סורי שנמכרים שמונה\u0006 ממנו \u0005בדינר\u0006 זהב גדול\u0005],\u0006 יש לתת \u0003חמש מינייהו\u0004 \u0005[מהם]\u0006 \u0003לפדיון הבן.\u0004"]]};
